window.CHAPTER_DATA = {"1":"<section class=\"chapter-section\" id=\"ch1\" data-book=\"kshitij-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">1</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-2 (गद्य खंड) — पाठ 1</div>\n      <h2>नेताजी का चश्मा</h2>\n      <p>स्वयं प्रकाश | कहानी — देशभक्ति, नागरिक कर्तव्य और कैप्टन चश्मेवाले का राष्ट्रप्रेम | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch1-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch1-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">सेनानी न होते हुए भी चश्मेवाले को लोग 'कैप्टन' क्यों कहते थे?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>चश्मेवाला न तो कोई फौजी था और न ही सुभाष चंद्र बोस की 'आज़ाद हिंद फ़ौज' का भूतपूर्व सिपाही। फिर भी कस्बे के लोग उसे आदर और व्यंग्य के मिले-जुले भाव से 'कैप्टन' कहते थे, जिसके प्रमुख कारण निम्नलिखित हैं:</p>\n          <ul>\n            <li><strong>प्रगाढ़ देशभक्ति व राष्ट्रप्रेम:</strong> चश्मेवाले के हृदय में देश के शहीदों और स्वतंत्रता सेनानियों के प्रति अपार श्रद्धा थी। नेताजी की बिना चश्मे वाली अधूरी मूर्ति उसे कचोटती थी।</li>\n            <li><strong>सक्रिय नागरिक निष्ठा:</strong> वह अत्यंत निर्धन और शारीरिक रूप से अपंग (लँगड़ा) फेरीवाला था, फिर भी अपने सीमित संसाधनों में से नेताजी की मूर्ति पर अपनी ओर से नियमित चश्मा लगाता था।</li>\n            <li><strong>सेनानी जैसी मानसिक भावना:</strong> सेनानी की वर्दी न पहनते हुए भी उसके विचार व समर्पण एक सच्चे सिपाही जैसे थे, इसलिए कस्बे वाले उसे 'कैप्टन' कहकर पुकारते थे।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्वतंत्रता सेनानियों व नेताजी के प्रति अगाध श्रद्धा का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गरीबी व अपंगता के बावजूद नियमित चश्मा लगाने की निष्ठा</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सटीक भाषा एवं शब्द-संयोजन</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch1-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch1-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">हालदार साहब ने ड्राइवर को पहले चौराहे पर गाड़ी रोकने के लिए मना किया था, लेकिन बाद में तुरंत रोकने को कहा— (क) हालदार साहब पहले मायूस क्यों हो गए थे? (ख) मूर्ति पर सरकंडे का चश्मा क्या उम्मीद जगाता है? (ग) हालदार साहब इतनी-सी बात पर भावुक क्यों हो उठे?</div>\n      <div class=\"q-marks\">5 अंक (100-120 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>(क) हालदार साहब की मायूसी का कारण:</strong> हालदार साहब को पता चला था कि देशभक्त कैप्टन चश्मेवाले की मृत्यु हो चुकी है। वे मायूस थे कि अब कस्बे के चौराहे पर नेताजी की मूर्ति तो होगी, किंतु उसकी आँखों पर चश्मा लगाने वाला कोई नहीं होगा, क्योंकि मास्टर जी बनाना भूल गए और कैप्टन अब रहा नहीं।</p>\n          <p><strong>(ख) सरकंडे के चश्मे से जागने वाली उम्मीद:</strong> सरकंडा घास की तीली से बना एक छोटा-सा खिलौना चश्मा था, जिसे प्रायः छोटे बच्चे खेल-खेल में बनाते हैं। यह चश्मा इस पावन सत्य को उजागर करता है कि देशभक्ति किसी एक व्यक्ति तक सीमित नहीं है, बल्कि देश की नई पीढ़ी (बच्चों) के नन्हें दिलों में भी राष्ट्रप्रेम और शहीदों के प्रति सम्मान जीवित है। देश का भविष्य सुरक्षित हाथों में है।</p>\n          <p><strong>(ग) हालदार साहब के भावुक होने का कारण:</strong> हालदार साहब ने जब देखा कि साधनहीन बच्चों ने अपनी बाल-सुलभ भावना से नेताजी की आँखों पर सरकंडे का चश्मा पहना रखा है, तो उनकी निराशा पल भर में आशा में बदल गई। इस पवित्र राष्ट्रभाव को देखकर उनकी आँखें भर आईं और वे श्रद्धा से अभिभूत हो उठे।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (क): कैप्टन की मृत्यु व मूर्ति के चश्माविहीन होने की चिंता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (ख): भावी पीढ़ी में राष्ट्रप्रेम व देश के सुरक्षित भविष्य की आशा</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (ग): बच्चों की निष्ठा व भावुक संवेदनशीलता का प्रभाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch1-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch1-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">आशय स्पष्ट कीजिए— \"बार-बार सोचते, क्या होगा उस कौम का जो अपने देश की खातिर घर-गृहस्थी-जवानी-जिंदगी सब कुछ होम देने वालों पर भी हँसती है और अपने लिए बिकने के मौके ढूँढ़ती है।\"</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>आशय:</strong> लेखक ने इस कथन के माध्यम से समाज में व्याप्त स्वार्थपरता, संवेदनहीनता और गिरते नैतिक मूल्यों पर गहरा क्षोभ व्यक्त किया है।</p>\n          <p>जो नागरिक उन स्वतंत्रता सेनानियों का उपहास उड़ाते हैं जिन्होंने देश की आजादी के लिए अपना सुख, परिवार और सर्वस्व न्योछावर कर दिया, वे समाज के लिए अभिशाप हैं। यदि समाज अपने देशप्रेमियों का सम्मान करने के बजाय निजी स्वार्थों के लिए बिकने और समझौते करने के अवसर ढूँढ़ने लगे, तो ऐसे राष्ट्र की स्वाधीनता और संस्कृति का पतन निश्चित है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शहीदों के बलिदान का उपहास उड़ाने पर क्षोभ का प्रकटीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्वार्थपरता और राष्ट्रीय पतन की आशंका का सटीक विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch1-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch1-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">पानवाले का एक रेखाचित्र प्रस्तुत कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>पानवाला सड़क के चौराहे पर अपनी दुकान चलाता था। उसका शब्द-चित्र निम्नलिखित है:</p>\n          <ul>\n            <li>वह एक काला, मोटा और खुशमिजाज आदमी था जिसकी बड़ी-सी तोंद हँसने पर थिरकती थी।</li>\n            <li>उसके मुँह में हमेशा पान ठूँसा रहता था, जिसके कारण उसके दाँत लाल-काले हो चुके थे और बात करने से पहले उसे नीचे पीक थूकनी पड़ती थी।</li>\n            <li>वह स्वभाव से मजाकिया, बातूनी और व्यंग्य कसने वाला था, परंतु अंदर से एक संवेदनशील हृदय भी रखता था; कैप्टन की मृत्यु पर वह अपनी आँखें पोंछता है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शारीरिक बनावट (मोटा, काला, थिरकती तोंद) का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पान खाने की आदत व स्वभावगत विशेषताओं का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch1-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch1-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">\"वो लँगड़ा क्या जाएगा फ़ौज में। पागल है पागल!\" कैप्टन के प्रति पानवाले की इस टिप्पणी पर अपनी प्रतिक्रिया लिखिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>पानवाले की यह टिप्पणी अत्यंत अनुचित, संवेदनहीन और निंदनीय है। किसी भी व्यक्ति की शारीरिक दिव्यांगता या गरीबी का उपहास उड़ाना अमानवीय है।</p>\n          <p>कैप्टन यदि शारीरिक रूप से लँगड़ा था, तो क्या हुआ? मानसिक और आत्मिक रूप से उसका राष्ट्रप्रेम किसी भी स्वस्थ सैनिक से कहीं अधिक ऊँचा था। पानवाला जिसे 'पागलपन' समझ रहा था, वह वास्तव में कैप्टन की असीम देशभक्ति और समर्पण था। समाज को ऐसे देशभक्तों का उपहास करने के बजाय उनके प्रति कृतज्ञ होना चाहिए।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">टिप्पणी की संवेदनहीनता व अमानवीयता की आलोचना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कैप्टन के आंतरिक राष्ट्रप्रेम व उच्च आचरण की प्रतिष्ठा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch1-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch1-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">निम्नलिखित वाक्य पात्रों की कौन-सी विशेषता की ओर संकेत करते हैं— (क) हालदार साहब हमेशा चौराहे पर रुकते और नेताजी को निहारते। (ख) पानवाला उदास हो गया। उसने पीछे मुड़कर मुँह का पान नीचे थूका और सिर झुकाकर अपनी धोती के सिरे से आँखें पोंछता हुआ बोला—मास्टर जी! कैप्टन मर गया। (ग) कैप्टन बार-बार मूर्ति पर चश्मा लगा देता था।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <ul>\n            <li><strong>(क) हालदार साहब:</strong> यह उनकी प्रगाढ़ देशभक्ति, राष्ट्रीय प्रतीकों के प्रति आदर और समाज की सूक्ष्म घटनाओं के प्रति गहरी संवेदनशीलता को दर्शाता है।</li>\n            <li><strong>(ख) पानवाला:</strong> ऊपरी हँसी-मजाक के पीछे उसके भीतर एक संवेदनशील, सहृदय और मानवीय गुणों से युक्त व्यक्ति छिपा था, जिसे कैप्टन की मृत्यु का गहरा दुख था।</li>\n            <li><strong>(ग) कैप्टन चश्मेवाला:</strong> यह उसकी अमर देशभक्ति, नेताजी के प्रति अगाध श्रद्धा और अपने सीमित साधनों में भी कर्तव्य पालन करने की निष्ठा को दर्शाता है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (क): हालदार साहब की देशप्रेम भावना का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (ख): पानवाले की आंतरिक मानवीय संवेदना</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (ग): कैप्टन के कर्तव्यबोध व राष्ट्रभक्ति का विश्लेषण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch1-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch1-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">जब तक हालदार साहब ने कैप्टन को साक्षात देखा नहीं था तब तक उनके मानस पटल पर उसका कौन-सा चित्र रहा होगा? अपनी कल्पना से लिखिए।</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>'कैप्टन' नाम सुनकर हालदार साहब ने सोचा होगा कि वह कोई लंबा-चौड़ा, रोबीला, मजबूत कद-काठी का फौजी जवान होगा। उसके सिर पर फौजी टोपी, तन पर वर्दी और चेहरे पर रौब होगा जो आज़ाद हिंद फ़ौज में सुभाष चंद्र बोस का साथी रहा होगा।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">फौजी जवान, रोबीले कद-काठी व वर्दीधारी व्यक्तित्व की कल्पना</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch1-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch1-q8')\">\n      <div class=\"q-num\">प्रश्न 8</div>\n      <div class=\"q-text\">अपने इलाके/शहर में लगी किसी महापुरुष की मूर्ति के संदर्भ में बताइए कि उसके प्रति आपका और समाज का क्या उत्तरदायित्व होना चाहिए?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>सार्वजनिक स्थलों पर लगी महापुरुषों की प्रतिमाएँ हमारे राष्ट्रीय गौरव और प्रेरणा की प्रतीक हैं। उनके प्रति हमारा और समाज का निम्नलिखित कर्तव्य है:</p>\n          <ol>\n            <li>मूर्ति और उसके आसपास के परिसर को स्वच्छ और सुंदर बनाए रखना; उस पर धूल, पक्षियों की गंदगी या कचरा न जमने देना।</li>\n            <li>मूर्ति को किसी भी प्रकार की क्षति या असामाजिक तत्वों के अनादर से बचाना।</li>\n            <li>विशेष राष्ट्रीय अवसरों (जयंती, पुण्यतिथि आदि) पर उन्हें माल्यार्पण कर उनके आदर्शों और विचारों को अपने आचरण में उतारना।</li>\n          </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्वच्छता व नियमित रखरखाव का उत्तरदायित्व</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सम्मान की रक्षा व आदर्शों को अपनाने का संकल्प</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: अभिकथन और कारण (Assertion &amp; Reason)</div>\n      <div class=\"cbq-question\">\n        <strong>अभिकथन (A):</strong> कैप्टन चश्मेवाले का राष्ट्रप्रेम किसी वर्दीधारी सैनिक से कम नहीं था।<br>\n        <strong>कारण (R):</strong> वह अपनी गरीबी और शारीरिक दिव्यांगता के बावजूद नेताजी की मूर्ति को कभी चश्माविहीन नहीं रहने देता था।<br>\n        <strong>विकल्प:</strong><br>\n        (क) अभिकथन (A) और कारण (R) दोनों सही हैं तथा कारण (R), अभिकथन (A) की सही व्याख्या करता है।<br>\n        (ख) अभिकथन (A) और कारण (R) दोनों सही हैं, परंतु कारण (R), अभिकथन की सही व्याख्या नहीं करता।<br>\n        (ग) अभिकथन (A) सही है, परंतु कारण (R) गलत है।<br>\n        (घ) अभिकथन (A) गलत है, परंतु कारण (R) सही है।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>सही उत्तर: (क)</strong><br>\n        <em>व्याख्या:</em> कैप्टन के पास सैन्य साधन नहीं थे, परंतु उसकी राष्ट्रभक्ति कर्म में प्रकट होती थी। उसने अपने सामर्थ्य से नेताजी की अधूरी मूर्ति को चश्मा देकर देशप्रेम की मिसाल पेश की, अतः कारण (R) सीधे तौर पर अभिकथन (A) की पुष्टि करता है।\n      </div>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 2: केस-आधारित प्रश्न (Case-Based Question)</div>\n      <div class=\"cbq-question\">\n        \"देशभक्ति केवल युद्धभूमि में प्राण न्योछावर करने का नाम नहीं है, अपितु दैनिक जीवन में राष्ट्रीय प्रतीकों का सम्मान करना भी देशभक्ति है।\" 'नेताजी का चश्मा' कहानी के आधार पर स्पष्ट कीजिए कि आम नागरिक देश निर्माण में किस प्रकार योगदान दे सकते हैं?\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        कहानी यह अमर संदेश देती है कि देश सीमाओं से घिरे भू-भाग का नाम नहीं है, बल्कि वहाँ रहने वाले नागरिकों, प्रकृति, संस्कृति और राष्ट्रीय प्रतीकों से बनता है। आम नागरिक निम्नलिखित तरीकों से देशसेवा कर सकते हैं:<br>\n        1. <strong>राष्ट्रीय स्मारकों व प्रतीकों का आदर:</strong> महापुरुषों की प्रतिमाओं, तिरंगे और सार्वजनिक संपत्तियों की सुरक्षा व सम्मान करना।<br>\n        2. <strong>स्वच्छता व पर्यावरण संरक्षण:</strong> अपने आसपास के परिवेश को स्वच्छ रखना, जल-विद्युत की बचत करना।<br>\n        3. <strong>कर्तव्यनिष्ठा:</strong> अपने कार्य (पढ़ाई, व्यवसाय, नौकरी) को ईमानदारी से पूर्ण करना ताकि राष्ट्र समृद्ध बन सके।\n      </div>\n    </div>\n  </div>\n</section>","2":"<section class=\"chapter-section\" id=\"ch2\" data-book=\"kshitij-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">2</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-2 (गद्य खंड) — पाठ 2</div>\n      <h2>बालगोबिन भगत</h2>\n      <p>रामवृक्ष बेनीपुरी | रेखाचित्र — कबीरपंथी संत, कर्मयोग, आडंबर-विरोध और सामाजिक सुधार | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch2-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch2-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">खेतीबारी से जुड़े गृहस्थ बालगोबिन भगत अपनी किन चारित्रिक विशेषताओं के कारण 'साधु' कहलाते थे?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>बालगोबिन भगत बाह्य वेशभूषा या संन्यास के आडंबरों से नहीं, बल्कि अपने शुद्ध आचरण और उदात्त मानवीय गुणों के कारण 'साधु' थे:</p>\n          <ul>\n            <li><strong>सत्यवादी और निष्कपट आचरण:</strong> वे कभी झूठ नहीं बोलते थे और सभी के साथ खरा व्यवहार रखते थे। किसी से व्यर्थ झगड़ा नहीं करते थे।</li>\n            <li><strong>अपरिग्रह और ईमानदारी:</strong> वे किसी की वस्तु को बिना पूछे हाथ तक नहीं लगाते थे और न ही उसका व्यवहार में उपयोग करते थे।</li>\n            <li><strong>कबीर के प्रति अटूट निष्ठा:</strong> वे कबीर को 'साहब' मानते थे। अपने खेत में जो कुछ भी अनाज पैदा होता, उसे सिर पर लादकर पहले कबीरपंथी मठ ले जाते और वहाँ से प्रसाद रूप में जो बचता, उसी से गृहस्थी चलाते थे।</li>\n            <li><strong>राग-द्वेष से मुक्ति:</strong> वे सुख-दुख, लाभ-हानि में समभाव रहते थे तथा मृत्यु को परमात्मा से आत्मा का मिलन मानकर आनंद मनाते थे।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सत्यवादिता, ईमानदारी और अपरिग्रह का स्पष्ट उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कबीर के प्रति समर्पण व सात्विक जीवन-शैली</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch2-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch2-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">भगत की पुत्रवधू उन्हें अकेले क्यों नहीं छोड़ना चाहती थी?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>भगत की पुत्रवधू अत्यंत सुशील, समझदार और संवेदनशील स्त्री थी। वह निम्नलिखित मानवीय कारणों से अपने वृद्ध ससुर को अकेला नहीं छोड़ना चाहती थी:</p>\n          <ul>\n            <li><strong>वृद्धावस्था और एकाकीपन की चिंता:</strong> भगत के इकलौते पुत्र की मृत्यु के बाद घर में उनकी देखभाल करने वाला कोई दूसरा नहीं बचा था।</li>\n            <li><strong>भोजन व स्वास्थ्य की फ़िक्र:</strong> भगत स्वयं कभी किसी से सेवा नहीं लेते थे। पुत्रवधू को चिंता थी कि यदि वे बीमार पड़ गए, तो उन्हें एक घूँट पानी देने वाला और समय पर भोजन पकाने वाला कोई नहीं रहेगा।</li>\n            <li><strong>त्यागमयी निष्ठा:</strong> वह अपने सुख की परवाह किए बिना अपने ससुर की बुढ़ापे में सेवा करके अपना कर्तव्य निभाना चाहती थी।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वृद्धावस्था, बीमारी व भोजन की चिंता का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पुत्रवधू के सेवाभाव, कर्तव्यनिष्ठा व त्याग का चित्रण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch2-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch2-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">भगत ने अपने बेटे की मृत्यु पर अपनी भावनाएँ किस तरह व्यक्त कीं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>बेटे की मृत्यु पर बालगोबिन भगत ने पारंपरिक लोगों की तरह रोना-पीटना नहीं मचाया, बल्कि उनका व्यवहार अत्यंत विस्मयकारी और आध्यात्मिक था:</p>\n          <ul>\n            <li>उन्होंने बेटे के शव को आँगन में एक चटाई पर लिटाकर सफेद चादर से ढक दिया और उस पर कुछ फूल तथा तुलसीदल बिखेर दिए।</li>\n            <li>सिरहाने एक दीपक जलाकर वे खँजड़ी बजाते हुए मस्ती में कबीर के पद गाने लगे।</li>\n            <li>रोती हुई पुत्रवधू को चुप कराते हुए उन्होंने कहा कि यह रोने का नहीं, बल्कि आनंद मनाने का उत्सव है; क्योंकि विरहिणी आत्मा अपने प्रियतम परमात्मा से मिलने चली गई है। यह उनके उच्च आध्यात्मिक ज्ञान का परिचायक था।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शव के सम्मुख खँजड़ी बजाकर कबीर के पद गाने का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आत्मा और परमात्मा के मिलन का उत्सव मानने का दार्शनिक भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch2-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch2-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">भगत के व्यक्तित्व और उनकी वेशभूषा का अपने शब्दों में चित्रण कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>शारीरिक व्यक्तित्व:</strong> बालगोबिन भगत साठ से ऊपर के मझोले कद के गोरे-चिट्टे आदमी थे। उनके बाल पक चुके थे, लंबी दाढ़ी-जटाएँ तो नहीं रखते थे किंतु उनका चेहरा हमेशा सफेद बालों से जगमगाता रहता था।</p>\n          <p><strong>वेशभूषा:</strong> वे कपड़े बिल्कुल कम पहनते थे। कमर में एक लँगोटी और सिर पर कबीरपंथियों की-सी कनफटी टोपी पहनते थे। सर्दियों में ऊपर से एक काली कमली ओढ़ लेते थे। माथे पर रामानंदी चंदन का टीका और गले में तुलसी की जड़ों की बेडौल माला पहनते थे।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आयु, कद-काठी व मुखमंडल का स्पष्ट वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">लँगोटी, टोपी, चंदन व तुलसी माला की वेशभूषा का अंकन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch2-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch2-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">बालगोबिन भगत की दिनचर्या लोगों के अचरज का कारण क्यों थी?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>भगत की दिनचर्या में अटूट नियमबद्धता और कठोर साधना थी:</p>\n          <ul>\n            <li>वे कड़ाके की ठंड (माघ की भोर) में भी मुँह-अंधेरे उठते और गाँव से दो मील दूर जाकर नदी में स्नान करते थे। लौटकर पोखरे के ऊँचे भिंडे पर बैठकर खँजड़ी बजाते हुए प्रभातियाँ गाते थे।</li>\n            <li>वृद्धावस्था और बीमारी में भी उन्होंने कभी अपने नियमों में ढील नहीं दी।</li>\n            <li>इतना कठिन श्रम और व्रत-उपवास करते हुए भी वे कभी किसी से सहारा या भिक्षा नहीं माँगते थे। उनके इसी अडिग नियम और संकल्प को देखकर लोग दाँतों तले उँगली दबाते थे।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">माघ की भीषण ठंड में भोर स्नान व प्रभाती गायन का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वृद्धावस्था में भी नियम न टूटने की कठोर साधना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch2-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch2-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">पाठ के आधार पर बालगोबिन भगत के मधुर गायन की विशेषताएँ लिखिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>बालगोबिन भगत के गायन में अद्भुत जादुई प्रभाव था:</p>\n          <ul>\n            <li><strong>अलौकिक रस की सृष्टि:</strong> उनका कंठ इतना सुरीला था कि जब वे गाते थे, तो ऐसा लगता मानो एक स्वर स्वर्ग की ओर जा रहा हो और दूसरा धरती पर खड़े लोगों के कानों में अमृत घोल रहा हो।</li>\n            <li><strong>कर्म और संगीत का समन्वय:</strong> आषाढ़ की रिमझिम में खेत में धान रोपते हुए जब वे गाते, तो बच्चे झूम उठते, मेड़ पर खड़ी औरतों के ओंठ काँपकर गुनगुनाने लगते और हलवाहों के पैर ताल से उठने लगते थे।</li>\n            <li>उनका संगीत मन की निराशा को दूर भगाकर वातावरण में एक दिव्य आनंद और स्फूर्ति भर देता था।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कंठ की मधुरता व स्वर्ग-धरती के रूपक का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">खेत में किसानों, बच्चों व औरतों पर संगीत के प्रभाव का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch2-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch2-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">कुछ मार्मिक प्रसंगों के आधार पर यह दिखाई देता है कि बालगोबिन भगत प्रचलित सामाजिक मान्यताओं को नहीं मानते थे। पाठ के आधार पर उन प्रसंगों का उल्लेख कीजिए।</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>बालगोबिन भगत ने समाज की दकियानूसी और रूढ़िवादी परंपराओं को तोड़कर आधुनिक सुधारवादी दृष्टि का परिचय दिया:</p>\n          <ul>\n            <li><strong>पुत्र की चिता को मुखाग्नि:</strong> हिंदू परंपरा के अनुसार दाह-संस्कार पुरुष करते हैं, किंतु भगत ने सामाजिक परंपरा को धता बताते हुए अपने मृत बेटे की चिता को अपनी पुत्रवधू के हाथों से ही मुखाग्नि दिलवाई।</li>\n            <li><strong>विधवा-विवाह का क्रांतिकारी कदम:</strong> श्राद्ध की अवधि समाप्त होते ही उन्होंने पुत्रवधू के भाई को बुलाकर आदेश दिया कि इसका दूसरा विवाह कर देना। उस समय विधवा-विवाह समाज में पाप समझा जाता था।</li>\n            <li><strong>मृत्यु पर शोक न मनाना:</strong> वे मृत्यु को मातम न मानकर आत्मा और परमात्मा के मिलन का उत्सव मानते थे। इस प्रकार वे सामाजिक पाखंडों से सर्वथा मुक्त थे।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पुत्रवधू से मुखाग्नि दिलवाने के प्रसंग का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">विधवा-विवाह के साहसिक कदम का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मृत्यु को उत्सव मानने की दार्शनिक चेतना</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch2-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch2-q8')\">\n      <div class=\"q-num\">प्रश्न 8</div>\n      <div class=\"q-text\">धान की रोपाई के समय समूचे माहौल को भगत की स्वर-लहरियाँ किस तरह चमत्कृत कर देती थीं? उस माहौल का शब्द-चित्र प्रस्तुत कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>आषाढ़ की रिमझिम फुहारों के बीच समूचा गाँव खेतों में उमड़ पड़ता था। आसमान बादलों से घिरा, ठंडी पुरवाई चल रही और पानी भरे कीचड़युक्त खेतों में धान की रोपाई हो रही थी।</p>\n          <p>तभी भगत का मधुर कंठ गूँज उठता—<em>\"गोदी में पियवा, चमक उठे सखिया, चिहुँक उठे ना!\"</em> उनका यह गायन खेतों में जादू बिखेर देता था। बच्चे पानी में खेलते हुए उछलने लगते, मेड़ पर कलेवा लिए बैठी स्त्रियों के होंठ अपने-आप थिरकने लगते और रोपनी करने वालों की उँगलियाँ एक निश्चित क्रम से धान के पौधों को रोपने लगती थीं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आषाढ़ के प्राकृतिक दृश्य व धान रोपाई का अंकन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भगत के गायन से श्रम में लयबद्धता व जादू का संचार</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: केस-आधारित सामाजिक चेतना (Competency Question)</div>\n      <div class=\"cbq-question\">\n        \"भगत का यह निर्णय कि उनकी पुत्रवधू का पुनर्विवाह हो, तत्कालीन समाज के लिए एक क्रांति था।\" वर्तमान नारी सशक्तिकरण के संदर्भ में भगत के इस कदम का मूल्यांकन कीजिए।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        भगत ने अपने व्यक्तिगत स्वार्थ (बुढ़ापे में अपनी सेवा) को त्यागकर अपनी युवा पुत्रवधू के भविष्य, सम्मान और सुख को प्राथमिकता दी। उनका यह कदम सिद्ध करता है कि वे सच्चे अर्थों में नारी स्वतंत्रता और मानवीय अधिकारों के पक्षधर थे। आज भी जब कई परिवारों में विधवाओं के साथ उपेक्षापूर्ण व्यवहार होता है, भगत का यह प्रगतिशील चिंतन पूरे समाज के लिए प्रकाश स्तंभ है।\n      </div>\n    </div>\n  </div>\n</section>","3":"<section class=\"chapter-section\" id=\"ch3\" data-book=\"kshitij-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">3</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-2 (गद्य खंड) — पाठ 3</div>\n      <h2>लखनवी अंदाज़</h2>\n      <p>यशपाल | व्यंग्य निबंध — पतनशील सामंती वर्ग की दिखावटी जीवन-शैली, नफासत और नई कहानी पर कटाक्ष | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch3-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch3-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">लेखक को नवाब साहब के किन हाव-भावों से महसूस हुआ कि वे उनसे बातचीत करने के लिए तनिक भी उत्सुक नहीं हैं?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखक के अचानक डिब्बे में प्रवेश करते ही नवाब साहब के चेहरे पर असंतोष और संकोच का भाव उभर आया। उनके निम्नलिखित हाव-भावों से बेरुखी साफ झलक रही थी:</p>\n          <ul>\n            <li>नवाब साहब ने लेखक के आने पर कोई मुस्कान नहीं दी और न ही शिष्टाचार वश कोई अभिवादन (सलाम) किया।</li>\n            <li>वे लेखक की उपस्थिति की उपेक्षा करते हुए खिड़की से बाहर घूरने लगे और निरंतर रेलगाड़ी के बाहर देखते रहे।</li>\n            <li>उनकी आँखों में एकांत चिंतन में विघ्न पड़ जाने का असंतोष साफ दिखाई दे रहा था।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">चेहरे पर असंतोष व उपेक्षापूर्ण दृष्टि का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">खिड़की के बाहर घूरने व अभिवादन न करने का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch3-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch3-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">नवाब साहब ने बहुत ही यत्न से खीरा काटा, नमक-मिर्च बुरका, अंततः सूँघकर ही खिड़की से बाहर फेंक दिया। उन्होंने ऐसा क्यों किया होगा? उनका ऐसा करना उनके कैसे स्वभाव को इंगित करता है?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>खीरा बाहर फेंकने का कारण:</strong> नवाब साहब सेकंड क्लास के साधारण डिब्बे में खीरा जैसी साधारण (अदना) वस्तु अकेले बैठकर मजे से खाना चाहते थे। किंतु लेखक के आ जाने पर उनका रईसी का झूठा अहंकार जाग उठा। वे लेखक के सामने खीरा खाकर अपनी नवाबी शान को कम नहीं होने देना चाहते थे। अतः उन्होंने खीरे को केवल सूँघकर खिड़की से बाहर फेंकने का ढोंग रचा ताकि लेखक पर अपनी झूठी रईसी और नज़ाकत की धाक जमा सकें।</p>\n          <p><strong>स्वभाव की विशेषताएँ:</strong> उनका ऐसा करना उनके <strong>खोखले दिखावे, कृत्रिम जीवन-शैली, दंभ और सामंती अहंकार</strong> को इंगित करता है। वे यथार्थ से दूर केवल कल्पना और प्रदर्शन की दुनिया में जीने वाले पतनोन्मुख वर्ग के प्रतिनिधि हैं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">झूठी नवाबी शान दिखाने व धाक जमाने के कारण का विश्लेषण</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दिखावटीपन, बनावटी नफासत व सामंती पतन के स्वभाव का उल्लेख</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch3-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch3-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">बिना विचार, घटना और पात्रों के भी क्या कहानी लिखी जा सकती है? यशपाल के इस विचार से आप कहाँ तक सहमत हैं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>हम लेखक यशपाल के विचार से पूर्णतया सहमत हैं। किसी भी सार्थक कहानी के निर्माण के लिए तीन मूलभूत तत्वों—<strong>कथ्य (विचार), घटना (कथानक) और पात्र (चरित्र)</strong> का होना अनिवार्य है। इनके बिना कोई वास्तविक कहानी अस्तित्व में नहीं आ सकती।</p>\n          <p>लेखक ने नवाब साहब के खीरा सूँघकर पेट भरने और डकार लेने के ढोंग के माध्यम से उन 'नई कहानी' के लेखकों पर तीखा व्यंग्य किया है, जो बिना किसी यथार्थ घटना, विचार या पात्र के केवल शब्दों का जाल बुनकर कहानी रचने का खोखला दावा करते हैं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कहानी के मूल तत्वों (विचार, घटना, पात्र) की अनिवार्यता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नई कहानी के खोखलेपन पर लेखक के व्यंग्य का स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch3-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch3-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">आप इस व्यंग्य निबंध को और क्या नाम देना चाहेंगे? कारण सहित बताइए।</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>हम इस पाठ को <strong>'झूठी शान'</strong> अथवा <strong>'नवाबी ढोंग'</strong> अथवा <strong>'दिखावे की नफासत'</strong> नाम देना चाहेंगे।</p>\n          <p><strong>कारण:</strong> पूरी कहानी में नवाब साहब की वास्तविकता और उनके बनावटी प्रदर्शन के बीच का द्वंद्व ही मुख्य विषय है। खीरा जैसी तुच्छ वस्तु को सूँघकर बाहर फेंकना केवल खोखले दिखावे की पराकाष्ठा है, अतः यह शीर्षक सटीक होगा।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सार्थक व उपयुक्त नए शीर्षक का सुझाव</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तार्किक कारण का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch3-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch3-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">नवाब साहब द्वारा खीरा खाने की तैयारी करने का एक विस्तृत चित्र प्रस्तुत किया गया है। इस पूरी प्रक्रिया को अपने शब्दों में व्यक्त कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>नवाब साहब ने खीरे की तैयारी अत्यंत नजाकत और करीने से की:</p>\n          <ol>\n            <li>सीट के नीचे से लोटा निकालकर दोनों खीरों को खिड़की के बाहर धोया और तौलिए से पोंछा।</li>\n            <li>जेब से चाकू निकालकर खीरों के सिर काटे, उन्हें गोदकर झाग निकाला।</li>\n            <li>फिर खीरों को बड़े एहतियात से छीलकर उनकी फाँकों को करीने से तौलिए पर सजाया।</li>\n            <li>उन पर जीरा-मिला नमक और लाल मिर्च की सुर्खी बुरकी। फाँकों पर पानी की बूँदें चमकने लगीं, जिससे मुँह में पानी आ रहा था।</li>\n          </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">खीरा धोने, झाग निकालने व छीलने की प्रक्रिया</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">फाँकें सजाने व नमक-मिर्च बुरकने की नजाकत का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch3-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch3-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">'लखनवी अंदाज़' पाठ में सामंती वर्ग की किस बनावटी जीवन-शैली पर व्यंग्य किया गया है? आज के समाज में भी ऐसी प्रवृत्ति कहाँ दिखाई देती है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>पाठ में उस पतनशील सामंती वर्ग पर तीखा कटाक्ष किया गया है जिनकी रियासतें और नवाबी तो छिन चुकी हैं, किंतु वे अभी भी अपनी झूठी शान, कृत्रिम नजाकत और प्रदर्शनप्रियता का चोला ओढ़े हुए हैं।</p>\n          <p>आज के उपभोक्तावादी समाज में भी यह दिखावा खूब देखा जा सकता है। लोग केवल दूसरों को प्रभावित करने और 'स्टेटस सिंबल' बनाने के लिए महँगे ब्रांडेड कपड़े, महंगे मोबाइल और कर्ज लेकर विलासिता की वस्तुएँ खरीदते हैं। यह भी उसी लखनवी नवाबियत का आधुनिक रूप है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पतनशील सामंती वर्ग के खोखले दंभ पर व्यंग्य</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आधुनिक समाज में स्टेटस सिंबल व उपभोक्तावादी दिखावे से तुलना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: अभिकथन और कारण (Assertion &amp; Reason)</div>\n      <div class=\"cbq-question\">\n        <strong>अभिकथन (A):</strong> नवाब साहब द्वारा डकार लेना उनके पेट भरने का नहीं, बल्कि मानसिक संतुष्टि के झूठे प्रदर्शन का प्रमाण था।<br>\n        <strong>कारण (R):</strong> भौतिक रूप से खीरा खाए बिना केवल सूँघने से उदर तृप्त नहीं हो सकता, डकार केवल नवाबी नफासत का नाटक था।<br>\n        <strong>विकल्प:</strong><br>\n        (क) (A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।<br>\n        (ख) (A) और (R) दोनों सही हैं, परंतु (R), (A) की सही व्याख्या नहीं करता।<br>\n        (ग) (A) सही है, परंतु (R) गलत है।<br>\n        (घ) (A) गलत है, परंतु (R) सही है।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>सही उत्तर: (क)</strong><br>\n        <em>व्याख्या:</em> नवाब साहब लेखक पर अपनी रईसी की धाक जमाने के लिए अवास्तविक डकार लेते हैं, जो दिखावे की पराकाष्ठा है। अतः (R) बिल्कुल सही व्याख्या करता है।\n      </div>\n    </div>\n  </div>\n</section>","4":"<section class=\"chapter-section\" id=\"ch4\" data-book=\"kshitij-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">4</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-2 (गद्य खंड) — पाठ 4</div>\n      <h2>एक कहानी यह भी</h2>\n      <p>मन्नू भंडारी | आत्मकथ्य — नारी चेतना, स्वतंत्रता आंदोलन, पितृसत्ता से संघर्ष और वैचारिक विकास | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch4-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch4-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">लेखिका के व्यक्तित्व पर किन-किन व्यक्तियों का किस रूप में प्रभाव पड़ा?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखिका मन्नू भंडारी के व्यक्तित्व के निर्माण में मुख्य रूप से दो व्यक्तियों का निर्णायक प्रभाव पड़ा:</p>\n          <ul>\n            <li><strong>पिता का प्रभाव:</strong> लेखिका के पिता ने उनके मन में हीनता की ग्रंथि (काले रंग और दुबलेपन के कारण) भी पैदा की, किंतु साथ ही उनमें देश-दुनिया के प्रति जागरूकता, राजनीतिक समझ और क्रांतिकारी विचार भरने का कार्य भी किया। पिता के शक्की स्वभाव और दंभ ने लेखिका के स्वाभिमान को धार दी।</li>\n            <li><strong>हिंदी प्राध्यापिका शीला अग्रवाल का प्रभाव:</strong> कॉलेज में शीला अग्रवाल ने लेखिका को केवल साहित्य पढ़ना ही नहीं सिखाया, बल्कि श्रेष्ठ साहित्य को परखने की दृष्टि दी। उन्होंने लेखिका के रगों में बहते खून को लावे में बदल दिया और उन्हें स्वाधीनता संग्राम की सक्रिय भागीदारी के लिए प्रेरित किया।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पिता के वैचारिक प्रभाव व अंतर्विरोधों का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शीला अग्रवाल द्वारा साहित्य रुचि व चेतना जगाने का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch4-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch4-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">मन्नू भंडारी के पिता के स्वभाव की क्या विशेषताएँ थीं?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>मन्नू भंडारी के पिता का व्यक्तित्व अंतर्विरोधों और जटिलताओं से भरा था:</p>\n          <ul>\n            <li><strong>विद्वान एवं संवेदनशील:</strong> वे अत्यंत कोमल हृदय, दरियादिल, सुशिक्षित और प्रतिष्ठित व्यक्ति थे। उन्होंने अंग्रेजी-हिंदी शब्दकोश का निर्माण किया था।</li>\n            <li><strong>क्रोधी और शक्की:</strong> आर्थिक झटकों और अपनों द्वारा दिए गए धोखों के कारण वे अत्यधिक क्रोधी, अहंवादी और संशयवादी बन गए थे।</li>\n            <li><strong>विरोधाभासी मानसिकता:</strong> वे एक ओर आधुनिक सोच रखते हुए बेटी को राजनीति व बहसों में शामिल करना चाहते थे, लेकिन दूसरी ओर परंपरावादी होकर उसे चारदीवारी के दायरे में ही रखना चाहते थे।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">विद्वत्ता व प्रतिष्ठा के साथ शक्की स्वभाव का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">रूढ़िवादी व प्रगतिशील विचारों के द्वंद्व का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch4-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch4-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">लेखिका के पिता ने रसोई को 'भटियारखाना' कहकर क्यों संबोधित किया?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखिका के पिता रसोई को 'भटियारखाना' इसलिए कहते थे क्योंकि उनका मानना था कि रसोई में लगातार काम करने से व्यक्ति की बौद्धिक क्षमता, प्रतिभा और रचनात्मक ऊर्जा नष्ट हो जाती है। वे अपनी बेटियों को केवल चूल्हे-चौके तक सीमित नहीं देखना चाहते थे, बल्कि देश और समाज की बौद्धिक बहसों में सक्रिय भागीदार बनाना चाहते थे।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रतिभा व क्षमता नष्ट होने के तर्क का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बौद्धिक विकास को प्राथमिकता देने का भाव</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch4-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch4-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">वह कौन-सी घटना थी जिसके बाद लेखिका को न अपनी आँखों पर विश्वास हो पाया और न अपने कानों पर?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>जब कॉलेज की प्रिंसिपल ने पत्र भेजकर लेखिका के पिता को कॉलेज बुलाया और शिकायत की कि मन्नू के एक इशारे पर लड़कियाँ क्लास छोड़ हड़ताल कर देती हैं, तो पिता क्रोधित होकर घर से निकले थे। लेखिका डरकर पड़ोस में बैठ गई कि घर लौटते ही पिता उसे पीटेंगे।</p>\n          <p>किंतु जब पिता कॉलेज से लौटे, तो वे बेहद खुश और गर्व से भरे हुए थे। उन्होंने कहा—\"पूरे कॉलेज पर मेरी बेटी का दबदबा है! यह तो स्वाधीनता आंदोलन की पुकार है, इसे कोई कैसे रोक सकता है!\" पिता का यह बदला हुआ रूप देखकर लेखिका को न अपनी आँखों पर विश्वास हुआ और न अपने कानों पर।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रिंसिपल की शिकायत और पिता के प्रारंभिक क्रोध का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पिता के गर्व और प्रशंसा भरे व्यवहार पर लेखिका का आश्चर्य</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch4-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch4-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">लेखिका की अपने पिता से वैचारिक टकराहट को अपने शब्दों में लिखिए।</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखिका और उनके पिता में गहरी वैचारिक टकराहट थी, जो दोनों के विचारों के अंतर्विरोध से उपजी थी:</p>\n          <ul>\n            <li><strong>घर की सीमा बनाम खुले मैदान की स्वतंत्रता:</strong> पिता चाहते थे कि लेखिका घर में बैठकर राजनीतिक चर्चाएँ सुने और चिंतन करे, किंतु लेखिका नारों, जुलूसों और हड़तालों में सड़कों पर उतरकर सक्रिय क्रांति करना चाहती थी।</li>\n            <li><strong>समाज की प्रतिष्ठा की चिंता:</strong> पिता दकियानूसी समाज और पड़ोसियों की टीका-टिप्पणियों से भयभीत हो जाते थे, जबकि लेखिका सामाजिक बंधनों की परवाह किए बिना अपनी राह स्वयं चुनना चाहती थी।</li>\n            <li><strong>अहं का टकराव:</strong> पिता का अत्यधिक अहंवादी होना और लेखिका का विद्रोही स्वाभिमान दोनों में निरंतर द्वंद्व उत्पन्न करता था।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">घर की चारदीवारी बनाम सक्रिय भागीदारी का द्वंद्व</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सामाजिक भय बनाम विद्रोही स्वाभिमान का विश्लेषण</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch4-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch4-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">इस आत्मकथ्य के आधार पर स्वाधीनता आंदोलन के परिदृश्य का चित्रण करते हुए उसमें मन्नू जी की भूमिका को रेखांकित कीजिए।</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>आंदोलन का परिदृश्य:</strong> सन 1942 से 1947 के दौरान भारत का स्वाधीनता संग्राम अपने चरम पर था। प्रभातफेरियों, हड़तालों, भाषणों, जुलूसों और 'अंग्रेजों भारत छोड़ो' के नारों से देश का कोना-कोना गूँज रहा था। युवा वर्ग में देशभक्ति का अभूतपूर्व ज्वार था।</p>\n          <p><strong>मन्नू जी की भूमिका:</strong> मन्नू जी केवल दर्शक नहीं, बल्कि अजमेर में युवाओं और छात्राओं की मुखर नेत्री थीं। वे कॉलेज में हड़ताल करवाती थीं, सड़कों पर जुलूस निकालती थीं और चौराहे पर खड़े होकर जोशीले भाषण देती थीं। उन्होंने सामाजिक वर्जनाओं को तोड़कर स्वाधीनता समर में अपनी सक्रिय आहुति दी।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्वाधीनता आंदोलन के माहौल (हड़ताल, जुलूस) का अंकन</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मन्नू जी के नेतृत्व, भाषण व सक्रिय भागीदारी का उल्लेख</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch4-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch4-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">लेखिका के बचपन का 'पड़ोस-कल्चर' आज के 'फ्लैट-कल्चर' से किस प्रकार भिन्न था?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखिका के बचपन में पड़ोस-कल्चर का मतलब था कि पूरा मोहल्ला एक बड़े परिवार जैसा होता था। घर की दीवारें भले अलग हों, लेकिन सुख-दुख, खेल और भोजन में कोई भेद नहीं था। बच्चे किसी भी घर में बिना रोकटोक जा सकते थे।</p>\n          <p>इसके विपरीत आज का 'फ्लैट-कल्चर' अत्यंत संकीर्ण, आत्मकेंद्रित और एकाकी हो चुका है। लोग पास के फ्लैट में रहने वाले पड़ोसी का नाम तक नहीं जानते। सुरक्षा और निजता के नाम पर मनुष्य ने स्वयं को एक संकीर्ण पिंजरे में बंद कर लिया है, जिससे आत्मीयता समाप्त हो गई है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बचपन के पड़ोस-कल्चर की आत्मीयता व सहभागिता का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आधुनिक फ्लैट-कल्चर के एकाकीपन व संकीर्णता की तुलना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: अभिकथन और कारण (Assertion &amp; Reason)</div>\n      <div class=\"cbq-question\">\n        <strong>अभिकथन (A):</strong> मन्नू भंडारी के पिता आधुनिक विचारों के समर्थक होते हुए भी पूरी तरह परंपरावादी थे।<br>\n        <strong>कारण (R):</strong> वे चाहते थे कि मन्नू देश-दुनिया की राजनीतिक बहसें सुने, परंतु सड़कों पर लड़कों के साथ हड़ताल व नारेबाज़ी न करे।<br>\n        <strong>विकल्प:</strong><br>\n        (क) (A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।<br>\n        (ख) (A) और (R) दोनों सही हैं, परंतु (R), (A) की सही व्याख्या नहीं करता।<br>\n        (ग) (A) सही है, परंतु (R) गलत है।<br>\n        (घ) (A) गलत है, परंतु (R) सही है।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>सही उत्तर: (क)</strong><br>\n        <em>व्याख्या:</em> पिता के व्यक्तित्व में विरोधाभास था—वे नारी प्रगति तो चाहते थे, लेकिन सामाजिक मर्यादा व प्रतिष्ठा की रूढ़िवादी बेड़ियों से मुक्त नहीं हो सके थे। अतः (R) बिल्कुल सही व्याख्या करता है।\n      </div>\n    </div>\n  </div>\n</section>","5":"<section class=\"chapter-section\" id=\"ch5\" data-book=\"kshitij-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">5</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-2 (गद्य खंड) — पाठ 5</div>\n      <h2>नौबतखाने में इबादत</h2>\n      <p>यतींद्र मिश्र | व्यक्तिचित्र — उस्ताद बिस्मिल्ला खाँ, शहनाई वादन, काशी की गंगा-जमुनी संस्कृति और साधना | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch5-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch5-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">शहनाई की दुनिया में डुमराँव को क्यों याद किया जाता है?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>शहनाई की दुनिया में डुमराँव को दो प्रमुख कारणों से याद किया जाता है:</p>\n          <ol>\n            <li><strong>बिस्मिल्ला खाँ का जन्मस्थान:</strong> भारत रत्न से सम्मानित शहनाई के अद्वितीय वादक उस्ताद बिस्मिल्ला खाँ का जन्म डुमराँव (बिहार) में हुआ था।</li>\n            <li><strong>नरकट घास की उपलब्धता:</strong> शहनाई बजाने के लिए जिस 'रीड' की आवश्यकता होती है, वह अंदर से पोली घास 'नरकट' डुमराँव में सोन नदी के किनारों पर ही प्रचुर मात्रा में पाई जाती है। इसके बिना शहनाई का वादन संभव नहीं है।</li>\n          </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बिस्मिल्ला खाँ के जन्मस्थल का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सोन नदी किनारे नरकट घास की रीड का महत्व</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch5-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch5-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">बिस्मिल्ला खाँ को शहनाई की 'मंगलध्वनि का नायक' क्यों कहा गया है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>भारतीय परंपरा में शहनाई विवाह, धार्मिक अनुष्ठान और मांगलिक अवसरों पर बजाई जाने वाली अत्यंत पावन ध्वनि है। बिस्मिल्ला खाँ को इसका नायक इसलिए कहा गया है क्योंकि:</p>\n          <ul>\n            <li>उन्होंने शहनाई को लोक-वाद्यों के सीमित घेरे से निकालकर शास्त्रीय संगीत के सर्वोच्च मंचों पर प्रतिष्ठित किया।</li>\n            <li>वे लगभग अस्सी वर्षों तक अखंड साधना के साथ शहनाई के माध्यम से सुरीली व मंगलकारी सुर-सृष्टि करते रहे।</li>\n            <li>उनकी शहनाई के सुरों में ईश्वर की इबादत, विनम्रता और शांति का वास था, जो हर श्रोता को पवित्र आनंद से भर देता था।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शहनाई को शास्त्रीय मंच पर प्रतिष्ठित करने का योगदान</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अखंड साधना व सुरों की आध्यात्मिक पवित्रता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch5-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch5-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">सुषिर-वाद्यों से क्या अभिप्राय है? शहनाई को 'सुषिर वाद्यों में शाह' की उपाधि क्यों दी गई होगी?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>सुषिर-वाद्य:</strong> वे वाद्य यंत्र जो फूँक मारकर बजाए जाते हैं और जिनमें छिद्रों (नाड़ियों) के माध्यम से सुर निकाले जाते हैं, उन्हें 'सुषिर-वाद्य' कहा जाता है; जैसे—बाँसुरी, शहनाई, शंख आदि।</p>\n          <p><strong>'शाह-ने' (शाह) की उपाधि:</strong> अरब देश में फूँककर बजाए जाने वाले वाद्यों को 'नय' कहते हैं। शहनाई की बनावट अत्यंत सुरीली, मधुर और कर्णप्रिय होती है। सभी सुषिर वाद्यों में इसकी ध्वनि सर्वाधिक मनमोहक और राग-रागिनियों को प्रकट करने में सबसे समर्थ है, इसलिए इसे वाद्यों का राजा यानी 'शाह-ने' या 'शहनाई' कहा गया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सुषिर-वाद्य की सटीक परिभाषा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">'शाह-ने' शब्द की व्युत्पत्ति और मधुरता का तर्क</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch5-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch5-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">आशय स्पष्ट कीजिए: (क) \"फ़टा सुर न बख्शें। लुंगिया का क्या है, आज फटी है, तो कल सिल जाएगी...\" (ख) \"काशी में संगीत-आयोजन की एक प्राचीन एवं अद्भुत परंपरा है। यह आयोजन पिछले कई बरसों से संकटमोचन मंदिर में होता आया है...\"</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>(क) आशय:</strong> बिस्मिल्ला खाँ के लिए बाह्य भौतिक चमक-दमक, कपड़े और मान-सम्मान का कोई मूल्य नहीं था। उनके लिए कला (सुर) की साधना सर्वोपरि थी। वे ईश्वर से प्रार्थना करते थे कि उनकी कला में कभी कोई खोट (फटा सुर) न आए, क्योंकि वस्त्र तो फटने पर सिला जा सकता है, किंतु यदि साधना और सुर में दरार आ गई तो उसे कभी सुधारा नहीं जा सकता।</p>\n          <p><strong>(ख) आशय:</strong> काशी सांस्कृतिक समन्वय की नगरी है। संकटमोचन मंदिर में हनुमान जयंती पर शास्त्रीय संगीत का भव्य समारोह होता है, जिसमें बिस्मिल्ला खाँ जैसे मुस्लिम उस्ताद पूरे श्रद्धाभाव से शहनाई वादन करते हैं। यह प्रसंग भारत की साझी गंगा-जमुनी तहजीब और हिंदू-मुस्लिम सौहार्द का जीवंत प्रमाण है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (क): कला-साधना को भौतिक वस्त्रों से श्रेष्ठ मानने का भाव</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (ख): काशी के संकटमोचन मंदिर में सांस्कृतिक समन्वय</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch5-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch5-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">बिस्मिल्ला खाँ के व्यक्तित्व की कौन-कौन सी विशेषताओं ने आपको सर्वाधिक प्रभावित किया?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>उस्ताद बिस्मिल्ला खाँ के व्यक्तित्व की निम्नलिखित विशेषताओं ने हमें गहराई से प्रभावित किया:</p>\n          <ul>\n            <li><strong>सादा जीवन और उच्च विचार:</strong> भारत रत्न प्राप्त करने के बाद भी वे फटी लुंगी पहनने में संकोच नहीं करते थे; उनमें तनिक भी अहंकार नहीं था।</li>\n            <li><strong>सांप्रदायिक सौहार्द के प्रतीक:</strong> वे सच्चे मुस्लिम होकर नमाज़ अदा करते थे, तो साथ ही काशी विश्वनाथ और बालाजी मंदिर के प्रति उनकी अटूट श्रद्धा थी। वे भारत की साझी गंगा-जमुनी संस्कृति के जीवंत प्रतीक थे।</li>\n            <li><strong>अविराम रियाज़ व समर्पण:</strong> अस्सी वर्ष की आयु में भी वे स्वयं को एक नौसिखिया मानकर ईश्वर से सच्चे सुर की नेमत माँगते थे।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सादगी और विनम्रता का वर्णन</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">धार्मिक सहिष्णुता व गंगा-जमुनी समन्वय</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">निरंतर सीखने की लगन व रियाज़</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch5-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch5-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">मुहर्रम से बिस्मिल्ला खाँ के जुड़ाव को अपने शब्दों में लिखिए।</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>मुहर्रम के महीने में बिस्मिल्ला खाँ का खानदान शोक मनाता था। मुहर्रम की आठवीं तारीख उनके लिए अत्यंत महत्त्वपूर्ण थी:</p>\n          <ul>\n            <li>इस दिन खाँ साहब न तो कोई राग बजाते थे और न ही किसी जलसे में भाग लेते थे।</li>\n            <li>वे आठ किलोमीटर पैदल रोते हुए नौहा बजाते चलते थे। उनकी आँखों से इमाम हुसैन और उनके शहीदों के गम में लगातार आँसू बहते थे। इस प्रकार उनकी शहनाई शोक और करुणा की अभिव्यक्ति बन जाती थी।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मुहर्रम में राग-रंग का त्याग व शोक का पालन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पैदल नौहा बजाने व आंसुओं द्वारा श्रद्धांजलि का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch5-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch5-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">बिस्मिल्ला खाँ का काशी से क्या अटूट संबंध था? उन्होंने काशी छोड़ने से क्यों इनकार किया?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>जब एक शिष्य ने बिस्मिल्ला खाँ को अमेरिका में बसने और वहाँ संगीत विद्यालय खोलने का प्रस्ताव दिया और कहा कि हम वहाँ काशी जैसा वातावरण बना देंगे, तो खाँ साहब ने उत्तर दिया—<em>\"तुम सब कुछ ला दोगे, पर गंगा मइया कहाँ से लाओगे? बाबा विश्वनाथ का मंदिर कहाँ से लाओगे?\"</em></p>\n          <p>काशी केवल एक शहर नहीं, बल्कि खाँ साहब की संगीत-साधना, बालाजी की ड्योढ़ी, गंगा जी की पवित्र लहरों और उनके पूर्वजों की स्मृतियों का तीर्थ था। वे काशी और गंगा को छोड़कर स्वर्ग में भी नहीं रह सकते थे।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अमेरिका जाने के प्रस्ताव को अस्वीकार करने का प्रसंग</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गंगा, विश्वनाथ व बालाजी मंदिर के प्रति अगाध निष्ठा का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: केस-आधारित विश्लेषण (Case-Based Competency)</div>\n      <div class=\"cbq-question\">\n        \"काशी संस्कृति की पाठशाला है। शास्त्रों में आनंदकानन के नाम से पूजित। काशी में कलाधर हनुमान व नृत्य विश्वनाथ हैं। काशी में बिस्मिल्ला खाँ हैं।\" प्रस्तुत कथन के आलोक में स्पष्ट कीजिए कि बिस्मिल्ला खाँ काशी के सांस्कृतिक समन्वय के प्रतीक कैसे बने?\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        बिस्मिल्ला खाँ भारत की साझी संस्कृति के साकार रूप थे। वे पाँचों वक्त नमाज़ पढ़ते थे, मुहर्रम में नौबत बजाकर रोते थे, और वहीं दूसरी ओर काशी विश्वनाथ और संकटमोचन मंदिर की ड्योढ़ी पर बैठकर शहनाई बजाते थे। जब भी काशी से बाहर जाते, तो सबसे पहले विश्वनाथ जी की दिशा में मुँह करके शहनाई का पहला सुर अर्पित करते थे। उनका यह आचरण सिद्ध करता है कि संगीत और संस्कृति किसी मजहब की सीमाओं में नहीं बँधती।\n      </div>\n    </div>\n  </div>\n</section>","6":"<section class=\"chapter-section\" id=\"ch6\" data-book=\"kshitij-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">6</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-2 (गद्य खंड) — पाठ 6</div>\n      <h2>संस्कृति</h2>\n      <p>भदंत आनंद कौसल्यायन | विचारात्मक निबंध — सभ्यता और संस्कृति में अंतर, मानव कल्याण, त्याग और वैज्ञानिक दृष्टि | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch6-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch6-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">लेखक की दृष्टि में 'सभ्यता' और 'संस्कृति' की सही समझ अब तक क्यों नहीं बन पाई है?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखक के अनुसार 'सभ्यता' और 'संस्कृति' ऐसे शब्द हैं जिनका उपयोग सबसे अधिक होता है, किंतु इन्हें सबसे कम समझा गया है। लोग इन दोनों शब्दों को प्रायः एक ही अर्थ में मिला देते हैं और इनके साथ 'भौतिक' या 'आध्यात्मिक' जैसे विशेषण जोड़कर इनके मूल अर्थ को और अधिक भ्रामक व उलझावपूर्ण बना देते हैं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दोनों शब्दों के घालमेल और विशेषणों द्वारा उत्पन्न भ्रम का उल्लेख</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch6-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch6-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">आग की खोज एक बहुत बड़ी खोज क्यों मानी जाती है? इस खोज के पीछे रही प्रेरणा के मुख्य स्रोत क्या रहे होंगे?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>बड़ी खोज का कारण:</strong> आग की खोज ने मानव सभ्यता को अंधकार और कच्चे भोजन के आदिम युग से निकालकर प्रकाश, सुरक्षा और पके हुए भोजन के युग में पहुँचाया। इसने मनुष्य को अन्य प्राणियों से श्रेष्ठ बनाया।</p>\n          <p><strong>प्रेरणा के मुख्य स्रोत:</strong></p>\n          <ul>\n            <li>पेट की ज्वाला (भूख) शांत करने और भोजन को सुपाच्य बनाने की आवश्यकता।</li>\n            <li>अंधेरे और जंगली हिंसक पशुओं के भय से आत्मरक्षा की इच्छा।</li>\n            <li>शीत व ठंड से बचाव के लिए ऊष्मा (गर्मी) प्राप्त करने की चाहत।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मानव जीवन में आग के क्रांतिकारी प्रभाव का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भूख, भय व ठंड से बचाव की प्रेरणा का स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch6-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch6-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">वास्तविक अर्थों में 'संस्कृत व्यक्ति' किसे कहा जा सकता है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखक के अनुसार वास्तविक अर्थों में 'संस्कृत व्यक्ति' वह है जो अपनी मूल प्रज्ञा, बुद्धि और योग्यता के बल पर किसी सर्वथा नए तथ्य या वस्तु का पहली बार आविष्कार करता है। जैसे—जिसने पहली बार आग की खोज की या जिसने गुरुत्वाकर्षण का सिद्धांत खोजा (न्यूटन), वे संस्कृत व्यक्ति थे। केवल पूर्वजों की खोजों का उपभोग करने वाला व्यक्ति संस्कृत नहीं, बल्कि केवल 'सभ्य' होता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अपनी प्रज्ञा से नई वस्तु का आविष्कार करने का लक्षण</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">संस्कृत और सभ्य के बीच मौलिक अंतर</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch6-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch6-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">न्यूटन को 'संस्कृत मानव' कहा गया, लेकिन उनके बाद के वैज्ञानिकों को 'सभ्य' कहा गया, 'संस्कृत' नहीं—क्यों?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>न्यूटन ने अपनी मौलिक प्रतिभा और जिज्ञासा से गुरुत्वाकर्षण के सिद्धांत का सबसे पहले आविष्कार किया था, इसलिए वे 'संस्कृत मानव' थे। आज का भौतिक विज्ञान का विद्यार्थी न्यूटन से कहीं अधिक नियमों और गूढ़ रहस्यों को जानता है, परंतु वह ज्ञान उसने स्वयं अपनी मौलिक प्रज्ञा से नहीं खोजा, बल्कि न्यूटन और अन्य पूर्वजों से विरासत में पाया है। अतः आज का विद्यार्थी या वैज्ञानिक न्यूटन से अधिक 'सभ्य' तो हो सकता है, परंतु 'संस्कृत' नहीं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">न्यूटन द्वारा मौलिक खोज का तर्क</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">परवर्ती वैज्ञानिकों द्वारा विरासत में ज्ञान पाने का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch6-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch6-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">किन महत्त्वपूर्ण आवश्यकताओं की पूर्ति के लिए सुई-धागे का आविष्कार हुआ होगा?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>सुई-धागे का आविष्कार मनुष्य के तन को ढँकने (लज्जा निवारण) तथा शीत, धूप और वर्षा से शरीर की रक्षा करने के लिए दो अलग-अलग कपड़ों या चमड़े के टुकड़ों को आपस में जोड़ने की आवश्यकता से हुआ होगा।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तन ढँकने व प्राकृतिक प्रकोपों से रक्षा की आवश्यकता</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch6-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch6-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">'मानव संस्कृति एक अविभाज्य वस्तु है'—स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>मानव संस्कृति का मूल तत्व है—कल्याण की भावना, परोपकार, त्याग और सत्य की खोज। इसमें ऐसा कोई भी अंश नहीं है जो मनुष्य को मनुष्य से अलग करे। जब तक मनुष्य का चिंतन और कर्म समस्त मानव जाति के कल्याण से जुड़ा है, तब तक वह संस्कृति है। जब संस्कृति को संकीर्ण मजहब, जाति या राष्ट्र की सीमाओं में बाँटकर दूसरों के विनाश के लिए इस्तेमाल किया जाता है, तो वह संस्कृति नहीं बल्कि 'असंस्कृति' बन जाती है। अतः सच्ची संस्कृति अखंड और अविभाज्य है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कल्याण भावना और सार्वभौमिकता का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">संस्कृति और असंस्कृति का भेद व अखंडता का निष्कर्ष</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch6-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch6-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">सभ्यता और संस्कृति में क्या मूल अंतर है? पाठ के आधार पर स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखक के अनुसार 'संस्कृति' और 'सभ्यता' में निम्नलिखित मौलिक अंतर है:</p>\n          <ul>\n            <li><strong>संस्कृति:</strong> मनुष्य की वह आंतरिक योग्यता, प्रेरणा, बुद्धि और चिंतन है जिससे वह किसी नई चीज का आविष्कार या नए सत्य की खोज करता है। यह साधन और योग्यता है।</li>\n            <li><strong>सभ्यता:</strong> संस्कृति के परिणामस्वरूप जो भौतिक वस्तुएँ, सुख-साधन, रहन-सहन, खान-पान और तकनीकी उपकरण बनते हैं, वे सभ्यता कहलाते हैं। यह बाह्य परिणाम और उपभोग की वस्तु है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">संस्कृति को आंतरिक योग्यता व अन्वेषण शक्ति बताना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सभ्यता को बाह्य भौतिक उपलब्धि व जीवन-शैली बताना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: अभिकथन और कारण (Assertion &amp; Reason)</div>\n      <div class=\"cbq-question\">\n        <strong>अभिकथन (A):</strong> जो आविष्कार मानव कल्याण की भावना से जुड़े नहीं होते, वे संस्कृति का परिणाम नहीं बल्कि असंस्कृति हैं।<br>\n        <strong>कारण (R):</strong> परमाणु बम और संहारक अस्त्रों का निर्माण आत्म-विनाश का साधन होने के कारण अप-संस्कृति को जन्म देता है।<br>\n        <strong>विकल्प:</strong><br>\n        (क) (A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।<br>\n        (ख) (A) और (R) दोनों सही हैं, परंतु (R), (A) की सही व्याख्या नहीं करता।<br>\n        (ग) (A) सही है, परंतु (R) गलत है।<br>\n        (घ) (A) गलत है, परंतु (R) सही है।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>सही उत्तर: (क)</strong><br>\n        <em>व्याख्या:</em> लेखक के अनुसार संस्कृति का मूल तत्व 'कल्याण' है। जब बुद्धि और विज्ञान का प्रयोग मानव जाति के विनाश के लिए होता है, तो वह असंस्कृति कहलाता है, अतः (R) बिल्कुल सही व्याख्या करता है।\n      </div>\n    </div>\n  </div>\n</section>","7":"<section class=\"chapter-section\" id=\"ch7\" data-book=\"kshitij-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">7</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-2 (काव्य खंड) — पाठ 7</div>\n      <h2>पद</h2>\n      <p>सूरदास (सूरसागर के भ्रमरगीत से) | ब्रजभाषा — गोपियों का वाक्चातुर्य, अनन्य कृष्ण प्रेम और निर्गुण योग पर सगुण भक्ति की विजय | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch7-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">गोपियों द्वारा उद्धव को भाग्यवान कहने में क्या व्यंग्य निहित है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>गोपियाँ उद्धव को 'बड़भागी' (भाग्यवान) कहकर वास्तव में उन पर तीखा वक्रोक्तिपूर्ण व्यंग्य करती हैं। उनके कहने का वास्तविक भाव यह है कि उद्धव अत्यंत अभागे हैं:</p>\n          <ul>\n            <li>वे प्रेम के साक्षात् अवतार भगवान श्रीकृष्ण के इतने निकट रहते हैं, फिर भी उनके हृदय में प्रेम और अनुराग की एक बूँद भी उत्पन्न नहीं हो सकी।</li>\n            <li>वे प्रेम के अलौकिक आनंद और विरह-मिलन के दिव्य सुख से सर्वथा वंचित हैं। इसलिए गोपियों की दृष्टि में उनका यह अनासक्त जीवन निरर्थक और दुर्भाग्यपूर्ण है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वक्रोक्ति/व्यंग्य के स्वरूप का स्पष्टीकरण (भाग्यवान कहकर अभागा बताना)</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कृष्ण के सान्निध्य में रहकर भी प्रेमरहित रहने का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch7-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">उद्धव के व्यवहार की तुलना किस-किस से की गई है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>गोपियों ने उद्धव के प्रेमहीन और अनासक्त व्यवहार की तुलना निम्नलिखित दो प्राकृतिक उदाहरणों से की है:</p>\n          <ol>\n            <li><strong>कमल के पत्ते (पुरइनि पात) से:</strong> जिस प्रकार कमल का पत्ता जल के भीतर रहते हुए भी जल से गीला नहीं होता और उस पर पानी की एक बूँद भी नहीं टिकती, उसी प्रकार उद्धव कृष्ण के समीप रहते हुए भी उनके प्रेम से अछूते हैं।</li>\n            <li><strong>तेल लगी गागर (गागरी) से:</strong> जिस प्रकार तेल से चुपड़े हुए मटके को जल में डुबोने पर उस पर पानी की एक बूँद भी नहीं ठहरती, उसी प्रकार ज्ञानमार्गी उद्धव पर कृष्ण के अगाध प्रेम-सागर का कोई असर नहीं होता।</li>\n          </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कमल के पत्ते (पुरइनि पात) के उदाहरण का सटीक विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तेल लगी मटकी के उदाहरण का सटीक विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch7-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">गोपियों ने किन-किन उदाहरणों के माध्यम से उद्धव को उलाहने दिए हैं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>गोपियों ने उद्धव और कृष्ण को निम्नलिखित प्रतीकों और उदाहरणों से उलाहने दिए हैं:</p>\n          <ul>\n            <li><strong>कमल के पत्ते व तेल की गगरी:</strong> उद्धव के स्नेहहीन और रूखे स्वभाव पर व्यंग्य किया।</li>\n            <li><strong>प्रेम की नदी (प्रीति-नदी):</strong> उद्धव ने प्रेम रूपी नदी में कभी पाँव तक नहीं डुबोया और रूप पर मुग्ध नहीं हुए।</li>\n            <li><strong>कड़वी ककड़ी (करुई ककरी):</strong> योग संदेश को कड़वी ककड़ी के समान अरुचिकर और त्याज्य बताया।</li>\n            <li><strong>हारिल की लकड़ी:</strong> अपने एकनिष्ठ प्रेम की तुलना हारिल पक्षी की लकड़ी से करके कृष्ण के प्रति अपने अटूट समर्पण को दर्शाया।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कमल पत्ते, तेल गागर व प्रीति नदी के उपमान</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कड़वी ककड़ी व हारिल की लकड़ी के उलाहनों का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch7-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">उद्धव द्वारा दिए गए योग के संदेश ने गोपियों की विरहाग्नि में घी का काम कैसे किया?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>गोपियाँ मथुरा से श्रीकृष्ण के लौटने की प्रतीक्षा में तन और मन की विरह-वेदना को इस आशा के साथ सह रही थीं कि कृष्ण शीघ्र लौटेंगे और उनका प्रेम साकार होगा। किंतु जब उद्धव ने आकर उन्हें कृष्ण के प्रेम को भूलने और निर्गुण ब्रह्म की कठोर योग-साधना अपनाने का संदेश दिया, तो उनकी सारी आशाएँ टूट गईं।</p>\n          <p>जिस संदेश से उन्हें सांत्वना मिलने की उम्मीद थी, उसी ने उनकी विरह-व्यथा और पीड़ा को अत्यधिक भड़का दिया। इस प्रकार योग के संदेश ने जलती हुई विरहाग्नि में आहुति (घी) डालने का कार्य किया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मिलन की आशा के टूटने और निराशा का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">योग संदेश द्वारा विरह-वेदना भड़कने का रूपक</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch7-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">'मरजादा न लही' के माध्यम से कौन-सी मर्यादा न रहने की बात की जा रही है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>यहाँ प्रेम की मर्यादा न रहने की बात की जा रही है। प्रेम की शाश्वत मर्यादा यह है कि प्रेम के बदले प्रेम दिया जाए और प्रेमी की भावनाओं का सम्मान किया जाए।</p>\n          <p>गोपियों ने कृष्ण के प्रेम में अपनी कुल-मर्यादा, लोक-लाज सब कुछ त्याग दिया था। किंतु कृष्ण ने उनके प्रेम के उत्तर में स्वयं आने के बजाय योग का रूखा संदेश भेज दिया और छल किया। इस प्रकार कृष्ण ने प्रेम की मर्यादा का उल्लंघन किया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रेम के बदले प्रेम देने की मर्यादा का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कृष्ण द्वारा योग संदेश भेजकर मर्यादा भंग करने का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch7-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">कृष्ण के प्रति अपने अनन्य प्रेम को गोपियों ने किस प्रकार अभिव्यक्त किया है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>गोपियों ने विभिन्न मार्मिक उदाहरणों से कृष्ण के प्रति अपनी अनन्य भक्ति प्रकट की है:</p>\n          <ul>\n            <li><strong>गुड़ में लिपटी चींटियों (गुर चाँटी ज्यौं पागी):</strong> जिस प्रकार चींटियाँ गुड़ से चिपट जाती हैं और अपने प्राण त्याग देती हैं, उसी प्रकार गोपियाँ भी कृष्ण के प्रेम में लीन हैं।</li>\n            <li><strong>हारिल की लकड़ी:</strong> जिस प्रकार हारिल पक्षी लकड़ी को पंजों में कसकर पकड़े रहता है, वैसे ही उन्होंने मन, कर्म और वचन से कृष्ण को अपने हृदय में बसा रखा है।</li>\n            <li>वे सोते, जागते, दिन-रात, स्वप्न में केवल 'कान्ह-कान्ह' की रट लगाती रहती हैं।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गुड़-चींटी व हारिल की लकड़ी के दृष्टांतों का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मन-क्रम-वचन से कृष्ण-स्मरण का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch7-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">गोपियों ने उद्धव से योग की शिक्षा कैसे लोगों को देने की बात कही है?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>गोपियों ने उद्धव से कहा—<em>\"यह तौ सूर तिनहिं लै सौंपौ, जिनके मन चक्री।\"</em></p>\n          <p>अर्थात यह निर्गुण योग का संदेश उन लोगों को जाकर सौंपिए जिनका मन चंचल, अस्थिर और चक्री (भौंरे या चक्र) के समान भटकता रहता है। गोपियों का मन तो एकमात्र श्रीकृष्ण के अनन्य प्रेम में दृढ़ और स्थिर है, इसलिए उन्हें किसी अन्य योग-साधना की लेशमात्र भी आवश्यकता नहीं है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अस्थिर व भटके हुए मन वाले लोगों को देने का सुझाव</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गोपियों के स्थिर व एकाग्र प्रेम का विपरीत भाव</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch7-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q8')\">\n      <div class=\"q-num\">प्रश्न 8</div>\n      <div class=\"q-text\">प्रस्तुत पदों के आधार पर गोपियों का योग-साधना के प्रति दृष्टिकोण स्पष्ट करें।</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>गोपियों के लिए निर्गुण योग-साधना पूर्णतया निरर्थक, अरुचिकर और कष्टप्रद है:</p>\n          <ul>\n            <li><strong>कड़वी ककड़ी के समान:</strong> गोपियाँ कहती हैं कि योग का नाम सुनते ही मुँह का स्वाद कड़वी ककड़ी जैसा अरुचिकर हो जाता है (<em>'ज्यों करुई ककरी'</em>)।</li>\n            <li><strong>एक असाध्य बीमारी:</strong> वे योग को ऐसी भयानक व्याधि मानती हैं जिसे न कभी उन्होंने पहले देखा, न सुना और न ही कभी भोगा।</li>\n            <li>वे सगुण साकार प्रेम को ही मुक्ति और आनंद का सच्चा मार्ग मानती हैं तथा ज्ञानमार्ग पर प्रेममार्ग की श्रेष्ठता स्थापित करती हैं।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कड़वी ककड़ी और बीमारी (व्याधि) के उपमानों का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">ज्ञान पर सगुण प्रेम की प्रतिष्ठा का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch7-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q9')\">\n      <div class=\"q-num\">प्रश्न 9</div>\n      <div class=\"q-text\">गोपियों के अनुसार राजा का धर्म क्या होना चाहिए?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>गोपियों के अनुसार—<em>\"राजधरम तौ यहै सूर, जो प्रजा न जाहिं सताए।\"</em></p>\n          <p>अर्थात एक सच्चे और आदर्श राजा का प्रथम कर्तव्य यह है कि वह अपनी प्रजा की सुख-सुविधाओं का ध्यान रखे और प्रजा को किसी भी प्रकार का कष्ट न पहुँचने दे। कृष्ण मथुरा के राजा बनकर स्वयं अपनी विरहिणी प्रजा (गोपियों) को कष्ट दे रहे हैं, जो राजधर्म के विरुद्ध है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रजा को न सताने के राजधर्म का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कृष्ण द्वारा राजधर्म के उल्लंघन पर गोपियों का कटाक्ष</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch7-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q10')\">\n      <div class=\"q-num\">प्रश्न 10</div>\n      <div class=\"q-text\">गोपियों को कृष्ण में ऐसे कौन-से परिवर्तन दिखाई दिए जिनके कारण वे अपना मन वापस पा लेने की बात कहती हैं?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>गोपियों को लगता है कि मथुरा जाकर श्रीकृष्ण अब पहले जैसे निश्छल और सीधे प्रेमी नहीं रहे, बल्कि राजनीतिज्ञ बन गए हैं:</p>\n          <ul>\n            <li>कृष्ण ने अब बड़े-बड़े राजनीति के ग्रंथ पढ़ लिए हैं जिससे उनकी बुद्धि और चतुराई बहुत बढ़ गई है (<em>\"हरि हैं राजनीति पढ़ि आए\"</em>)।</li>\n            <li>वे अब प्रेम का निर्वाह करने के स्थान पर छल-कपट और कूटनीति से काम ले रहे हैं।</li>\n            <li>जो दूसरों को अनीति से छुड़ाते थे, वे स्वयं गोपियों पर योग संदेश भेजकर अनीति कर रहे हैं। इस बदलाव के कारण गोपियाँ अपना मन वापस माँगती हैं।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कृष्ण द्वारा राजनीति पढ़ने व चतुर बनने का आरोप</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रेम के बदले छल व अनीति करने पर मन वापस माँगना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch7-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q11')\">\n      <div class=\"q-num\">प्रश्न 11</div>\n      <div class=\"q-text\">गोपियों ने अपने वाक्चातुर्य के आधार पर ज्ञानी उद्धव को परास्त कर दिया, उनके वाक्चातुर्य की विशेषताएँ लिखिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>गोपियों का वाक्चातुर्य अद्भुत, तर्कपूर्ण और व्यंग्यमयी है:</p>\n          <ul>\n            <li><strong>वक्रोक्ति और व्यंग्य:</strong> वे उद्धव को 'बड़भागी' कहकर उनकी अज्ञानता पर तीखा कटाक्ष करती हैं।</li>\n            <li><strong>सटीक उपमान:</strong> योग को कड़वी ककड़ी और बीमारी (व्याधि) बताकर वे उद्धव के ज्ञानमार्ग को निरुत्तर कर देती हैं।</li>\n            <li><strong>सहज और निश्चल तर्क:</strong> वे शास्त्रार्थ के जटिल तर्कों से नहीं, बल्कि अपने सच्चे प्रेम की अनुभूति के बल पर प्रकांड ज्ञानी उद्धव को मूक (मौन) कर देती हैं।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">व्यंग्य, वक्रोक्ति व सटीक उपमानों का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रेम की अनुभूति द्वारा ज्ञान के तर्कों को परास्त करने का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch7-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q12')\">\n      <div class=\"q-num\">प्रश्न 12</div>\n      <div class=\"q-text\">संकलित पदों को ध्यान में रखते हुए सूरदास के भ्रमरगीत की मुख्य विशेषताएँ बताइए।</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>सूरदास का 'भ्रमरगीत' हिंदी साहित्य की विरह और भक्ति काव्य परंपरा का अद्वितीय रत्न है:</p>\n          <ul>\n            <li><strong>निर्गुण पर सगुण भक्ति की विजय:</strong> भ्रमरगीत में सूरदास ने ज्ञान और योग के शुष्क मार्ग पर सगुण साकार प्रेम भक्ति की पूर्ण विजय स्थापित की है।</li>\n            <li><strong>विरह-वेदना और उपालंभ:</strong> इसमें गोपियों की विरह-वेदना की गहराई और भौंरे को माध्यम बनाकर उद्धव व कृष्ण को दिए गए उपालंभ (उलाहने) अत्यंत मार्मिक हैं।</li>\n            <li><strong>संगीतात्मक ब्रजभाषा:</strong> पदों में कोमलकांत पदावली, माधुर्य गुण, गेयता (गीत शैली) तथा अनुप्रास, उपमा, रूपक और दृष्टांत अलंकारों का अनुपम प्रयोग है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सगुण भक्ति की ज्ञानमार्ग पर विजय का सिद्धांत</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">ब्रजभाषा का माधुर्य, गेयता व उपालंभ काव्य-शिल्प</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: काव्यांश-आधारित विश्लेषण (Extract-Based Competency)</div>\n      <div class=\"cbq-question\">\n        \"हमारे हरि हारिल की लकरी। मन क्रम बचन नंद-नंदन उर, यह दृढ़ करि पकरी॥\"<br>\n        प्रस्तुत पंक्तियों में हारिल पक्षी की लकड़ी का रूपक गोपियों की किस मानसिक अवस्था और भक्ति-भावना को दर्शाता है?\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        हारिल पक्षी अपने पंजों में लकड़ी के तिनके को सदा पकड़े रहता है और उसे अपना एकमात्र जीवन-आधार मानता है। ठीक उसी प्रकार गोपियों ने मन, कर्म और वाणी से श्रीकृष्ण को अपने हृदय में दृढ़तापूर्वक धारण कर रखा है। यह रूपक उनके <strong>एकनिष्ठ, अनन्य और अडिग समर्पण</strong> को दर्शाता है, जहाँ कृष्ण के अतिरिक्त उनके जीवन का कोई अन्य अवलंबन नहीं है।\n      </div>\n    </div>\n  </div>\n</section>","8":"<section class=\"chapter-section\" id=\"ch8\" data-book=\"kshitij-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">8</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-2 (काव्य खंड) — पाठ 8</div>\n      <h2>राम-लक्ष्मण-परशुराम संवाद</h2>\n      <p>गोस्वामी तुलसीदास (रामचरितमानस के बालकांड से) | अवधी भाषा, दोहा-चौपाई छंद — वीर रस, रौद्र रस, हास्य-व्यंग्य और मर्यादा | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch8-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch8-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">परशुराम के क्रोध करने पर लक्ष्मण ने धनुष के टूट जाने के लिए कौन-कौन से तर्क दिए?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लक्ष्मण ने हँसते हुए परशुराम के समक्ष निम्नलिखित तर्क प्रस्तुत किए:</p>\n          <ul>\n            <li><strong>बचपन के धनुषों की समानता:</strong> हमने बचपन में खेल-खेल में न जाने कितनी धनुहियाँ तोड़ डालीं, तब तो मुनिवर ने कभी ऐसा क्रोध नहीं किया। इस धनुष पर इतनी विशेष ममता क्यों?</li>\n            <li><strong>जीर्ण-शीर्ण पुराना धनुष:</strong> यह धनुष अत्यंत पुराना और जर्जर था। ऐसे सड़े-गले धनुष के टूटने से किसी को क्या लाभ या क्या हानि हो सकती है?</li>\n            <li><strong>राम का दोष नहीं:</strong> श्री राम ने तो इसे नए के भ्रम में केवल छुआ मात्र था, छूते ही यह अपने-आप टूट गया। इसमें रघुपति का कोई दोष नहीं है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बचपन की धनुहियों का तर्क</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">धनुष के पुराने व जर्जर होने का तर्क</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">राम द्वारा केवल छूते ही टूटने का स्पष्टीकरण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch8-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch8-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">परशुराम के क्रोध करने पर राम और लक्ष्मण की जो प्रतिक्रियाएँ हुईं, उनके आधार पर दोनों के स्वभाव की विशेषताएँ अपने शब्दों में लिखिए।</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>श्री राम का स्वभाव:</strong></p>\n          <ul>\n            <li><strong>धैर्य और विनम्रता:</strong> राम अत्यंत शांत, सौम्य और मर्यादा पुरुषोत्तम हैं। वे परशुराम के भीषण क्रोध के सामने हाथ जोड़कर स्वयं को उनका 'एक दास' कहते हैं।</li>\n            <li><strong>शीतलता:</strong> उनके वचन जल के समान शीतल और क्रोध को शांत करने वाले हैं। वे बड़ों का आदर करना भली-भाँति जानते हैं।</li>\n          </ul>\n          <p><strong>लक्ष्मण का स्वभाव:</strong></p>\n          <ul>\n            <li><strong>उग्रता और वाक्पटुता:</strong> लक्ष्मण स्वभाव से अत्यंत उग्र, तेजस्वी और निर्भीक हैं। वे अन्याय या अनुचित अहंकार को बिल्कुल सहन नहीं करते।</li>\n            <li><strong>व्यंग्यबाण:</strong> वे परशुराम के फरसे और डींगों से तनिक भी नहीं डरते, बल्कि तीखे व्यंग्य बाणों से उनके क्रोध को और भड़का देते हैं।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">श्री राम के शील, विनय व मर्यादा का विश्लेषण</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">लक्ष्मण की निर्भीकता, उग्रता व व्यंग्य-क्षमता का विश्लेषण</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch8-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch8-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">लक्ष्मण और परशुराम के संवाद का जो अंश आपको सबसे अच्छा लगा, उसे अपने शब्दों में संवाद शैली में लिखिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>लक्ष्मण (हँसकर व्यंग्य भाव से):</strong> हे मुनिवर! आप तो अपने आपको बहुत बड़ा योद्धा समझते हैं और बार-बार मुझे अपना यह फरसा दिखाकर डराना चाहते हैं। ऐसा लगता है मानो आप फूँक मारकर पहाड़ उड़ाना चाहते हैं!</p>\n          <p><strong>परशुराम (क्रोध से काँपते हुए):</strong> अरे मूर्ख बालक! तू अपने सामने साक्षात काल को नहीं देख रहा है। मेरे इस फरसे की भयानकता तो गर्भ के बच्चों का भी नाश कर देती है!</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नाटकीय संवाद शैली में सुंदर प्रस्तुति</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पात्रानुकूल भावों (हँसी, व्यंग्य, क्रोध) का सटीक अंकन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch8-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch8-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">परशुराम ने अपने विषय में सभा में क्या-क्या कहा, निम्न पद्यांश के आधार पर लिखिए: \"बाल ब्रह्मचारी अति कोही। बिस्वबिदित छत्रियकुल द्रोही...\"</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>परशुराम ने अपनी वीरता और पराक्रम की प्रशंसा करते हुए सभा में कहा:</p>\n          <ul>\n            <li>वे बाल ब्रह्मचारी हैं और स्वभाव से अत्यंत क्रोधी हैं। सारा संसार जानता है कि वे क्षत्रिय कुल के चिर-शत्रु हैं।</li>\n            <li>उन्होंने अपनी भुजाओं के बल से अनेक बार पृथ्वी को क्षत्रिय राजाओं से विहीन कर दिया और जीती हुई सारी भूमि ब्राह्मणों को दान कर दी।</li>\n            <li>उनका फरसा इतना क्रूर है जिसने सहस्रबाहु की भुजाओं को काट डाला था और इसकी गर्जना से गर्भ के बच्चे भी नष्ट हो जाते हैं।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बाल ब्रह्मचारी, क्रोधी व क्षत्रिय-विनाशक होने का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भूमि दान व सहस्रबाहु के वध का संदर्भ</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch8-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch8-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">लक्ष्मण ने वीर योद्धा की क्या-क्या विशेषताएँ बताईं?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लक्ष्मण ने परशुराम को लक्ष्य करते हुए एक सच्चे शूरवीर की निम्नलिखित विशेषताएँ बताईं:</p>\n          <ul>\n            <li><strong>कर्म में विश्वास:</strong> शूरवीर युद्धभूमि में अपनी वीरता का पराक्रम दिखाते हैं, मुँह से अपनी प्रशंसा के ढोल नहीं पीटते (<em>\"सूर समर करनी करहिं नहिं जनावहिं आपु\"</em>)।</li>\n            <li><strong>डींगें न हाँकना:</strong> युद्ध में शत्रु को सामने पाकर केवल कायर व्यक्ति ही अपने पराक्रम की डींगें हाँकते हैं।</li>\n            <li><strong>धैर्य और शील:</strong> सच्चे वीर धीर, क्षोभरहित और गंभीर होते हैं तथा गाली देने जैसी अशोभनीय हरकतें नहीं करते।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">युद्धभूमि में कर्म प्रदर्शन बनाम आत्मप्रशंसा का भेद</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">धैर्य, गंभीरता व अमर्यादित आचरण न करने का गुण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch8-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch8-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">साहस और शक्ति के साथ विनम्रता हो तो बेहतर है—इस कथन पर अपने विचार लिखिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>यह कथन शत-प्रतिशत सत्य है। साहस और शक्ति जब बिना विवेक और विनम्रता के प्रकट होते हैं, तो वे विनाशकारी अहंकार और आतंक बन जाते हैं, जैसा कि परशुराम के क्रोधी व्यवहार में दिखाई देता है।</p>\n          <p>किंतु जब साहस और शक्ति के साथ 'विनम्रता' जुड़ जाती है, तो वह मनुष्य को सर्वप्रिय, सम्मानीय और महान बना देती है, जैसा कि भगवान श्री राम के आचरण में देखने को मिलता है। विनम्रता शक्ति को संयम प्रदान करती है और व्यक्ति समाज को जोड़ने का कार्य करता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">विनम्रता विहीन शक्ति के दुष्परिणाम (अहंकार) का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">विनम्रता युक्त शक्ति की दिव्यता व प्रभाव (श्री राम का उदाहरण)</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch8-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch8-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">भाव स्पष्ट कीजिए: (क) बिहसि लखनु बोले मृदु बानी। अहो मुनीसु महाभट मानी॥ (ख) इहाँ कुम्हड़बतिया कोउ नाहीं। जे तरजनी देखि मरि जाहीं॥ (ग) गाधिसूनु कह हृदयँ हसि मुनिहि हरियरे सूझ। अयमय खाँड़ न ऊखमय अजहुँ न बूझ अबूझ॥</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>(क) भाव:</strong> लक्ष्मण मंद मुस्कान के साथ मधुर वाणी में व्यंग्य करते हुए कहते हैं कि हे मुनिवर! आप तो अपने आपको बहुत बड़ा शूरवीर योद्धा मानते हैं और मुझे बार-बार फरसा दिखाकर डराने का प्रयास कर रहे हैं।</p>\n          <p><strong>(ख) भाव:</strong> यहाँ कोई कुम्हड़े (कद्दू) का छोटा कोमल फल नहीं है जो आपकी तर्जनी उँगली की ओर इशारा करने मात्र से मुरझाकर मर जाएगा। हम भी क्षत्रिय हैं और आपके फरसे से भयभीत नहीं होंगे।</p>\n          <p><strong>(ग) भाव:</strong> विश्वामित्र मन ही मन हँसकर सोचते हैं कि परशुराम को सब जगह हरा ही हरा (विजय ही विजय) सूझ रहा है। वे राम और लक्ष्मण को गन्ने के रस से बनी साधारण गुड़ की खाँड समझ रहे हैं, जबकि ये दोनों लोहे से बनी फौलादी तलवार (खाँडा) हैं। मुनि इनके वास्तविक प्रभाव से अभी भी अनजान हैं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (क) व (ख): लक्ष्मण के व्यंग्य व निर्भीकता का भाव</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (ग): विश्वामित्र के आंतरिक चिंतन व श्लेष अलंकार का स्पष्टीकरण</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch8-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch8-q8')\">\n      <div class=\"q-num\">प्रश्न 8</div>\n      <div class=\"q-text\">पाठ में आए व्यंग्य के कोई दो उदाहरण छाँटकर लिखिए।</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <ol>\n            <li><strong>पहला उदाहरण:</strong> <em>\"पुनि पुनि मोहि देखआव कुठारू। चहत उड़ावन फूँकि पहारू॥\"</em> (लक्ष्मण कहते हैं कि आप बार-बार फरसा दिखाकर ऐसे डरा रहे हैं मानो फूँक से पहाड़ उड़ा देंगे)।</li>\n            <li><strong>दूसरा उदाहरण:</strong> <em>\"कोटि कुलिस सम बचनु तुम्हारा। व्यर्थ धरहु धनु बान कुठारा॥\"</em> (आपके तो वचन ही करोड़ों वज्रों के समान कठोर हैं, आपने व्यर्थ में ही धनुष, बाण और फरसा धारण कर रखा है)।</li>\n          </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दो सटीक व्यंग्य उद्धरणों का उल्लेख व व्याख्या</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch8-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch8-q9')\">\n      <div class=\"q-num\">प्रश्न 9</div>\n      <div class=\"q-text\">निम्नलिखित पंक्तियों में प्रयुक्त अलंकार पहचानकर लिखिए: (क) बालकु बोलि बधौं नहि तोही। (ख) कोटि कुलिस सम बचनु तुम्हारा। (ग) तुम्ह तौ कालु हाँक जनु लावा। बार बार मोहि लागि बोलावा॥</div>\n      <div class=\"q-marks\">3 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <ul>\n            <li><strong>(क) 'बालकु बोलि बधौं नहि तोही':</strong> 'ब' वर्ण की बार-बार आवृत्ति होने के कारण यहाँ <strong>अनुप्रास अलंकार</strong> है।</li>\n            <li><strong>(ख) 'कोटि कुलिस सम बचनु तुम्हारा':</strong> वचनों की तुलना करोड़ों वज्रों से 'सम' वाचक शब्द द्वारा की गई है, अतः यहाँ <strong>उपमा अलंकार</strong> है। (साथ ही 'क' वर्ण की आवृत्ति से अनुप्रास भी है)।</li>\n            <li><strong>(ग) 'तुम्ह तौ कालु हाँक जनु लावा':</strong> 'जनु' वाचक शब्द का प्रयोग काल की संभावना व्यक्त करने के लिए हुआ है, अतः यहाँ <strong>उत्प्रेक्षा अलंकार</strong> तथा 'बार बार' में <strong>पुनरुक्ति प्रकाश अलंकार</strong> है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (क): अनुप्रास अलंकार</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (ख): उपमा अलंकार</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (ग): उत्प्रेक्षा व पुनरुक्ति प्रकाश अलंकार</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch8-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch8-q10')\">\n      <div class=\"q-num\">प्रश्न 10</div>\n      <div class=\"q-text\">तुलसीदास के काव्य-शिल्प और अवधी भाषा की प्रमुख विशेषताएँ लिखिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>प्रस्तुत प्रसंग में तुलसीदास जी के काव्य-शिल्प की निम्नलिखित विशेषताएँ दृष्टिगोचर होती हैं:</p>\n          <ul>\n            <li><strong>साहित्यिक अवधी भाषा:</strong> तत्सम शब्दावली से युक्त अत्यंत परिमार्जित, प्रवाहमयी और कर्णप्रिय अवधी भाषा का प्रयोग।</li>\n            <li><strong>छंद-योजना:</strong> चौपाई और दोहा छंद का सुंदर और शास्त्रीय निर्वाह, जो इसे गेय और लयबद्ध बनाता है।</li>\n            <li><strong>रस-परिपाक:</strong> वीर रस, रौद्र रस और हास्य-व्यंग्य का अद्भुत संगम। लक्ष्मण के तीखे व्यंग्य बाण संवाद को अत्यंत नाटकीय बना देते हैं।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">साहित्यिक अवधी व दोहा-चौपाई छंद का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नाटकीयता, व्यंग्य व रस-संयोजन का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: शिल्प सौंदर्य और भाषा विश्लेषण (Stylistic Competency)</div>\n      <div class=\"cbq-question\">\n        \"इहाँ कुम्हड़बतिया कोउ नाहीं। जे तरजनी देखि मरि जाहीं॥\" पंक्ति में निहित लोकोक्ति और लक्ष्मण के साहस का आशय स्पष्ट कीजिए।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        'कुम्हड़बतिया' काशीफल (कद्दू) का वह छोटा-सा कोमल फल होता है जो उँगली की छुअन या तर्जनी दिखाने से मुरझा जाता है। लक्ष्मण इस लोक-विश्वास के माध्यम से निर्भीकतापूर्वक कहते हैं कि हम कोई कमजोर या भयभीत होने वाले व्यक्ति नहीं हैं जो आपकी तर्जनी उँगली या फरसा देखकर डर से मर जाएँगे। यहाँ लक्ष्मण का अदम्य क्षत्रिय तेज और व्यंग्य मुखरित हुआ है।\n      </div>\n    </div>\n  </div>\n</section>","9":"<section class=\"chapter-section\" id=\"ch9\" data-book=\"kshitij-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">9</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-2 (काव्य खंड) — पाठ 9</div>\n      <h2>आत्मकथ्य</h2>\n      <p>जयशंकर प्रसाद | छायावादी कविता — वैयक्तिक पीड़ा, जीवन का यथार्थ, अंतर्मुखी दृष्टि और विनम्र अभिव्यक्ति | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch9-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch9-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">कवि आत्मकथा लिखने से क्यों बचना चाहता है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>छायावादी कवि जयशंकर प्रसाद निम्नलिखित कारणों से अपनी आत्मकथा लिखने से बचना चाहते हैं:</p>\n          <ul>\n            <li><strong>साधारण व अभावग्रस्त जीवन:</strong> कवि का मानना है कि उनका जीवन अत्यंत सामान्य और खाली गगरी की तरह रिक्त रहा है; उसमें कोई ऐसी महान उपलब्धि नहीं जिसे सुनकर दुनिया वाह-वाह करे।</li>\n            <li><strong>व्यथाओं का पुनर्जागरण:</strong> आत्मकथा लिखने से जीवन के पुराने घाव और सोई हुई वेदना पुनः हरी हो जाएगी।</li>\n            <li><strong>उपहास का भय:</strong> वे अपनी कमजोरियों, भूलों और मित्रों द्वारा दिए गए छल-कपट को सार्वजनिक करके दुनिया में खुद को उपहास का पात्र नहीं बनाना चाहते।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">उपलब्धिहीन सामान्य जीवन की अनुभूति</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">निजी वेदना के जागने व उपहास से बचने की भावना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch9-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch9-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">आत्मकथा सुनाने के संदर्भ में 'अभी समय भी नहीं' कवि ऐसा क्यों कहता है?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि ऐसा इसलिए कहता है क्योंकि उसके अनुसार उसने अभी तक जीवन में कोई ऐसा महान कार्य या कीर्ति अर्जित नहीं की है जिसे समाज के सामने प्रस्तुत किया जाए। साथ ही, उसके हृदय की पीड़ा और दुखद स्मृतियाँ इस समय शांत होकर थकी-हारी सोई हुई हैं। कवि उन्हें जगाकर अपनी व्यथा को फिर से बढ़ाना नहीं चाहता।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">महान उपलब्धि के अभाव का तर्क</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सोई हुई व्यथा को न जगाने की इच्छा</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch9-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch9-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">स्मृति को 'पाथेय' बनाने से कवि का क्या आशय है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>'पाथेय' का अर्थ होता है—मार्ग का संबल या यात्रा में यात्री के काम आने वाला भोजन व सहारा।</p>\n          <p>कवि के जीवन में आज केवल सूनापन, दुख और निराशा है। अतीत में प्रियतमा के साथ बिताए गए सुखद क्षणों की मधुर स्मृतियाँ ही कवि के थके हुए जीवन रूपी यात्री का एकमात्र सहारा (पाथेय) हैं। उन्हीं स्मृतियों के सहारे वह अपने उदास जीवन की कठिन यात्रा तय कर रहा है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">'पाथेय' शब्द का अर्थ (मार्ग का संबल)</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अतीत की सुखद स्मृतियों को जीने का सहारा मानने का विश्लेषण</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch9-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch9-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">भाव स्पष्ट कीजिए: (क) \"मिला कहाँ वह सुख जिसका मैं स्वप्न देखकर जाग गया। आलिंगन में आते-आते मुसक्या कर जो भाग गया।\" (ख) \"जिसके अरुण-कपोलों की मतवाली सुंदर छाया में। अनुरागिनी उषा लेती थी निज सुहाग मधुमाया में॥\"</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>(क) भाव:</strong> सांसारिक सुख कवि के लिए स्वप्न की तरह क्षणभंगुर और छलावा साबित हुआ। जिस सुख की उसने कल्पना की थी और जिसे वह बाहों में भरने ही वाला था, वह उसे छूकर मुस्कुराता हुआ दूर भाग गया। कवि के जीवन में सुख कभी नहीं ठहरा।</p>\n          <p><strong>(ख) भाव:</strong> कवि अपनी प्रियतमा के अप्रतिम सौंदर्य का स्मरण करते हुए कहता है कि उसके लाल-लाल गालों (अरुण-कपोलों) की लाली इतनी मनमोहक थी कि प्रेममयी प्रातःकालीन उषा भी अपनी मांग का सुहाग सिंदूर मानो उसी की लालिमा से चुराकर भरती थी। यह छायावादी सौंदर्य का शिखर है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (क): सुख की क्षणभंगुरता व छलावे का स्पष्टीकरण</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (ख): प्रियतमा के रूप-सौंदर्य व उषा के मानवीकरण का भाव</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch9-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch9-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">'उज्ज्वल गाथा कैसे गाऊँ, मधुर चाँदनी रातों की'—कथन के माध्यम से कवि क्या कहना चाहता है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि कहना चाहता है कि प्रियतमा के साथ चाँदनी रातों में बिताए गए प्रेम, हँसी और खिलखिलाहट के निजी पलों की मधुर कहानियाँ उसकी सर्वथा गोपनीय और व्यक्तिगत निधि हैं।</p>\n          <p>वे प्रेम के पावन क्षण सार्वजनिक करने के लिए नहीं हैं। उन्हें दुनिया के सामने उजागर करके वह अपनी पवित्र भावनाओं की नुमाइश नहीं करना चाहता, क्योंकि वे अब केवल उसकी यादों में जीवित हैं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">निजी प्रेम क्षणों की गोपनीयता व पवित्रता का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सार्वजनिक नुमाइश से बचने की मर्यादा का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch9-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch9-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">'आत्मकथ्य' कविता की काव्यभाषा की विशेषताएँ उदाहरण सहित लिखिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>'आत्मकथ्य' कविता छायावादी काव्य-शिल्प का उत्कृष्ट उदाहरण है:</p>\n          <ul>\n            <li><strong>तत्समप्रधान खड़ी बोली:</strong> संस्कृतनिष्ठ शब्दावली का समृद्ध प्रयोग; जैसे—'अनंत नीलिमा', 'व्यंग्य-मलिन', 'अरुण-कपोल', 'अनुरागिनी उषा'।</li>\n            <li><strong>प्रतीकात्मकता:</strong> 'मधुप' (मन रूपी भौंरा), 'रीति गागर' (रिक्त जीवन), 'मुरझाकर गिरती पत्तियाँ' (जीवन के दुख-दर्द)।</li>\n            <li><strong>मानवीकरण एवं बिंब-विधान:</strong> <em>\"अरी सरलते तेरी हँसी उड़ाऊँ मैं\"</em> तथा उषा द्वारा सुहाग सिंदूर लेने में जीवंत मानवीकरण है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तत्सम शब्दावली व प्रतीकात्मकता का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मानवीकरण व सुंदर बिंब-विधान का सटीक विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch9-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch9-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">कवि ने जो सुख का स्वप्न देखा था, उसे कविता में किस रूप में अभिव्यक्त किया है?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि ने सुख के स्वप्न को अपनी प्रेयसी के साथ बिताए गए चाँदनी रातों के उल्लास, खिलखिलाहट और मधुर मिलन के रूप में देखा था। किंतु वह सुख वास्तविक जीवन में नहीं ठहर सका और आलिंगन में आते-आते मुस्कुराकर भाग गया, जिससे जीवन में केवल विरह और निराशा शेष रह गई।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रेयसी के साथ मिलन के स्वप्न व उसके छूटने का चित्रण</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: छायावादी शिल्प सौंदर्य (Poetic Aesthetic Competency)</div>\n      <div class=\"cbq-question\">\n        'आत्मकथ्य' कविता में कवि की आत्म-मुग्धता के स्थान पर आत्म-संकोच और विनम्रता अधिक प्रकट हुई है। इस पर टिप्पणी कीजिए।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        प्रायः आत्मकथा लिखने वाले अपनी सफलताओं और महानता का गुणगान करते हैं। किंतु प्रसाद जी अपनी किसी भी उपलब्धि का दंभ नहीं भरते। वे स्वयं को एक साधारण मनुष्य मानते हैं, अपनी भूलों को स्वीकारते हैं और अपनी पीड़ा को भीतर ही समेटे रखते हैं। उनका यह आत्म-संकोच उनके महान और विनम्र व्यक्तित्व की पहचान है।\n      </div>\n    </div>\n  </div>\n</section>","10":"<section class=\"chapter-section\" id=\"ch10\" data-book=\"kshitij-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">10</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-2 (काव्य खंड) — पाठ 10</div>\n      <h2>उत्साह और अट नहीं रही है</h2>\n      <p>सूर्यकांत त्रिपाठी 'निराला' | आह्वान गीत व प्रकृति-गीत — क्रांति चेतना, सामाजिक परिवर्तन और फागुन मास का अनुपम सौंदर्य | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch10-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch10-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">कवि बादल से फुहार, रिमझिम या बरसने के स्थान पर 'गरजो' क्यों कहता है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि निराला एक क्रांतिकारी कवि हैं। वे बादल को केवल जल बरसाने वाले प्राकृतिक साधन के रूप में नहीं, बल्कि शोषित समाज में नई चेतना और क्रांति के प्रतीक के रूप में देखते हैं।</p>\n          <p>फुहार या रिमझिम कोमलता और शांति की सूचक है, जिससे समाज में बड़ा परिवर्तन नहीं आ सकता। कवि बादलों के भीषण 'गर्जन' के द्वारा समाज के सोए हुए लोगों में नवजीवन, पौरुष, उत्साह और विप्लव (क्रांति) का शंखनाद करना चाहता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बादल को क्रांति व पौरुष के प्रतीक के रूप में दर्शाना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">फुहार की कोमलता बनाम गर्जन के क्रांतिकारी प्रभाव का भेद</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch10-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch10-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">कविता का शीर्षक 'उत्साह' क्यों रखा गया है?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कविता एक आह्वान गीत है जो मानव मन में उमंग, साहस और ऊर्जा भरने का संदेश देता है। जिस प्रकार बादलों का गर्जन और बरसना पीड़ित धरती और व्याकुल जन-मन में नई आशा और उत्साह का संचार करता है, उसी प्रकार क्रांति भी समाज में नवीन ऊर्जा भरती है। अतः 'उत्साह' शीर्षक सर्वथा सटीक और सार्थक है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आह्वान गीत के रूप में ऊर्जा व साहस जगाने का भाव</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शीर्षक की औचित्यपूर्ण सार्थकता</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch10-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch10-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">कविता में बादल किन-किन अर्थों की ओर संकेत करता है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>'उत्साह' कविता में बादल निम्नलिखित बहुआयामी अर्थों की ओर संकेत करता है:</p>\n          <ol>\n            <li><strong>तप्त मानव की प्यास बुझाने वाले:</strong> गर्मी से पीड़ित और व्याकुल लोगों को शीतलता व जल प्रदान करने वाले कल्याणकारी रूप में।</li>\n            <li><strong>क्रांतिकारी चेतना के अग्रदूत:</strong> अपने वज्र-गर्जन से पुरानी रूढ़ियों को तोड़कर सामाजिक परिवर्तन लाने वाले विद्रोही रूप में।</li>\n            <li><strong>नवीन सृष्टि के रचयिता कवि:</strong> नए अंकुर को जीवन देने वाले और साहित्य में नवचेतना भरने वाले सृजक के रूप में।</li>\n          </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तृष्णा निवारक व जलदाता रूप</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">क्रांति व परिवर्तन का प्रतीक</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सृजन व नई कविता का प्रतीक</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch10-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch10-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">शब्दों का ऐसा प्रयोग जिससे कविता के किसी खास भाव या दृश्य में ध्वन्यात्मक प्रभाव पैदा हो, नाद-सौंदर्य कहलाता है। 'उत्साह' कविता में से ऐसे उदाहरण छाँटिए।</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>'उत्साह' कविता में निम्नलिखित पंक्तियों में नाद-सौंदर्य स्पष्ट सुनाई देता है:</p>\n          <ul>\n            <li><em>\"घेर घेर घोर गगन, रन्ध्र-धरा पर घन!\"</em> ('घ' और 'र' की आवृत्ति से बादलों के उमड़ने-घुमड़ने की गड़गड़ाहट ध्वनित होती है)।</li>\n            <li><em>\"ललित ललित, काले घुँघराले, बाल कल्पना के-से पाले।\"</em></li>\n            <li><em>\"विद्युत-छवि उर में, कवि, नवजीवन वाले!\"</em></li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नाद-सौंदर्य की सटीक पंक्तियों का चयन</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">ध्वन्यात्मक प्रभाव की व्याख्या</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch10-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch10-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">छायावाद की एक खास विशेषता है अंतर्मन के भावों का बाहर की दुनिया से सामंजस्य बिठाना। कविता की किन पंक्तियों को पढ़कर यह धारणा पुष्ट होती है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>'अट नहीं रही है' कविता की निम्नलिखित पंक्तियाँ अंतर्मन की खुशी और फागुन के बाह्य सौंदर्य के एकाकार होने को सिद्ध करती हैं:</p>\n          <p><em>\"कहीं साँस लेते हो, घर-घर भर देते हो, उड़ने को नभ में तुम, पर-पर कर देते हो।\"</em></p>\n          <p>यहाँ प्रकृति के खिलने से मनुष्य का अंतर्मन भी कल्पना के पंख लगाकर आकाश में उड़ने को आतुर हो उठता है। कवि के मन का उल्लास बाहर फागुन की हरियाली और फूलों में अभिव्यक्त हो रहा है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सटीक काव्यांश का उद्धरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आंतरिक उल्लास व बाह्य प्रकृति के सामंजस्य की व्याख्या</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch10-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch10-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">'अट नहीं रही है' कविता के आधार पर फागुन के प्राकृतिक सौंदर्य और उसकी मादकता का वर्णन कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>फागुन मास (वसंत ऋतु) में प्रकृति का सौंदर्य चरम सीमा पर होता है:</p>\n          <ul>\n            <li><strong>चारों ओर हरियाली और लालिमा:</strong> पेड़ों की डालियाँ कहीं हरी पत्तियों से तो कहीं लाल-लाल कोमल कोंपलों से लद गई हैं।</li>\n            <li><strong>सुगंधित समीर:</strong> फूलों से सुशोभित प्रकृति के गले में मानो मंद-मंद सुगंध की माला पड़ी हुई है, जिससे सारा वातावरण महक रहा है।</li>\n            <li><strong>असीमित शोभा:</strong> फागुन की प्राकृतिक आभा (शोभा) इतनी अधिक और व्यापक है कि वह प्रकृति और आँखों में समा नहीं पा रही है (अट नहीं रही है)।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पेड़ों पर नए पत्तों व फूलों का सुंदर चित्रण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मादक सुगंध व प्रकृति में समा न पाने वाले सौंदर्य का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch10-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch10-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">कवि की आँख फागुन की सुंदरता से क्यों नहीं हट रही है?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>फागुन में प्रकृति का रूप इतना मनमोहक, रंग-बिरंगा, सजीव और अलौकिक होता है कि कवि का मन उस पर पूरी तरह मुग्ध हो गया है। चारों ओर बिखरी असीम सुंदरता कवि की आँखों को सम्मोहित कर लेती है, इसलिए चाहकर भी उसकी आँखें उस सौंदर्य से हट नहीं पातीं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">फागुन के सम्मोहनकारी व अप्रतिम सौंदर्य का कारण</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch10-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch10-q8')\">\n      <div class=\"q-num\">प्रश्न 8</div>\n      <div class=\"q-text\">फागुन में ऐसा क्या होता है जो बाकी ऋतुओं से भिन्न होता है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>फागुन मास (वसंत) सभी ऋतुओं का राजा है। इसमें प्रकृति में निम्नलिखित अनूठे परिवर्तन होते हैं:</p>\n          <ul>\n            <li>पतझड़ के सूखे पेड़ नए पत्तों, कोमल कोंपलों और रंग-बिरंगे फूलों से लदकर नवयौवन प्राप्त करते हैं।</li>\n            <li>वातावरण न अत्यधिक ठंडा होता है और न गर्म; मंद सुगंधित वायु हर प्राणी में नई उमंग और मादकता भर देती है।</li>\n            <li>पशु-पक्षी और मनुष्य सभी में एक अद्भुत उल्लास और जीवन-रस का संचार होता है जो अन्य किसी ऋतु में नहीं मिलता।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रकृति के नवयौवन व अनुकूल मौसम का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सुगंधित समीर व सर्वव्यापी उल्लास का चित्रण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: अभिकथन और कारण (Assertion &amp; Reason)</div>\n      <div class=\"cbq-question\">\n        <strong>अभिकथन (A):</strong> 'उत्साह' कविता में निराला जी बादलों को क्रांति का अग्रदूत मानते हैं।<br>\n        <strong>कारण (R):</strong> बादल अपने भीतर 'वज्र' छिपाए हुए हैं जो पुरानी सड़ी-गली व्यवस्था को नष्ट कर नवसृजन करने में सक्षम है।<br>\n        <strong>विकल्प:</strong><br>\n        (क) (A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।<br>\n        (ख) (A) और (R) दोनों सही हैं, परंतु (R), (A) की सही व्याख्या नहीं करता।<br>\n        (ग) (A) सही है, परंतु (R) गलत है।<br>\n        (घ) (A) गलत है, परंतु (R) सही है।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>सही उत्तर: (क)</strong><br>\n        <em>व्याख्या:</em> निराला जी के अनुसार बादलों के उर (हृदय) में छिपी बिजली और गर्जन विध्वंस के साथ-साथ नई कविता और नए जीवन का निर्माण करती है। अतः (R) बिल्कुल सही व्याख्या है।\n      </div>\n    </div>\n  </div>\n</section>","11":"<section class=\"chapter-section\" id=\"ch11\" data-book=\"kshitij-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">11</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-2 (काव्य खंड) — पाठ 11</div>\n      <h2>यह दंतुरित मुस्कान और फसल</h2>\n      <p>नागार्जुन | जनवादी कविता — वात्सल्य रस, शिशु की मासूमियत, श्रम का गौरव और प्रकृति-मानव का सह-अस्तित्व | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch11-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch11-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">बच्चे की दंतुरित मुस्कान का कवि के मन पर क्या प्रभाव पड़ता है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>नन्हें बच्चे की नए-नए दाँत निकली (दंतुरित) मुस्कान देखकर कवि का मन अपार वात्सल्य और आनंद से भर उठता है:</p>\n          <ul>\n            <li><strong>मुरझाए मन में नवजीवन:</strong> कवि को लगता है कि बच्चे की यह मोहक मुस्कान मृतप्राय और निराश व्यक्ति में भी नए प्राण फूँक सकती है।</li>\n            <li><strong>कमल खिलने की अनुभूति:</strong> धूल-धूसरित बच्चे को देखकर लगता है मानो तालाब को छोड़कर कमल का फूल उसकी झोपड़ी में खिल उठा हो।</li>\n            <li><strong>कठोरता का पिघलना:</strong> कवि का मन जो लंबे प्रवास के कारण कठोर और शुष्क हो गया था, वह बच्चे के स्पर्श मात्र से पिघलकर शेफालिका के फूलों की तरह झड़ने लगता है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">निराशा में नवजीवन व वात्सल्य के संचार का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कमल व शेफालिका के फूलों जैसे बिंबों का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch11-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch11-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">बच्चे की मुसकान और एक बड़े व्यक्ति की मुस्कान में क्या अंतर होता है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>बच्चे और बड़े व्यक्ति की मुस्कान में मौलिक अंतर होता है:</p>\n          <ul>\n            <li><strong>बच्चे की मुस्कान:</strong> पूर्णतया निष्कपट, निश्छल, स्वाभाविक और स्वार्थहीन होती है। इसमें कोई बनावटीपन नहीं होता और यह हर देखने वाले को निर्मल आनंद देती है।</li>\n            <li><strong>बड़े व्यक्ति की मुस्कान:</strong> प्रायः औपचारिकता, स्वार्थ, कूटनीति या व्यंग्य से भरी होती है। बड़ों की मुस्कान में अवसरवादिता और संकोच छिपा रहता है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बच्चे की निश्छलता व स्वाभाविकता का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बड़ों की मुस्कान की कृत्रिमता व औपचारिकता का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch11-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch11-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">कवि ने बच्चे की मुस्कान के सौंदर्य को किन-किन बिंबों के माध्यम से व्यक्त किया है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>नागार्जुन ने बच्चे की मुस्कान को निम्नलिखित जीवंत बिंबों से सजाया है:</p>\n          <ol>\n            <li><strong>मृतक में जान डालने वाला बिंब:</strong> <em>\"मृतक में भी डाल देगा जान\"</em>।</li>\n            <li><strong>कमल का फूल:</strong> धूल से सने शिशु को देखकर लगता है मानो तालाब छोड़कर कमल झोपड़ी में खिल गया हो (<em>\"जलजात\"</em>)।</li>\n            <li><strong>पाषाण पिघलने का बिंब:</strong> कठोर पत्थर पिघलकर जल बन गया हो (<em>\"पिघलकर जल बन गया होगा कठिन पाषाण\"</em>)।</li>\n            <li><strong>शेफालिका के फूल:</strong> बाँस और बबूल जैसे शुष्क वृक्षों से भी शेफालिका के कोमल फूल झड़ने लगे हों।</li>\n          </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कमल, पाषाण पिघलने व शेफालिका फूलों के बिंबों का उल्लेख</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मृतक में जान डालने के रूपक का विश्लेषण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch11-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch11-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">भाव स्पष्ट कीजिए: (क) \"छोड़कर तालाब मेरी झोपड़ी में खिल रहे जलजात।\" (ख) \"छू गया तुमसे कि झरने लग पड़े शेफालिका के फूल, बाँस था कि बबूल?\"</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>(क) भाव:</strong> 'जलजात' कमल को कहते हैं। कवि अपनी निर्धन झोपड़ी में धूल-धूसरित सुंदर शिशु को देखकर मुग्ध है। उसे लगता है कि साक्षात् कमल तालाब का वैभव छोड़कर उसके गरीब घर में खिल उठा है। यह बच्चे की दिव्यता का प्रतीक है।</p>\n          <p><strong>(ख) भाव:</strong> कवि का मन लंबे समय तक घर से दूर रहने के कारण बाँस और बबूल की तरह कठोर और नीरस हो चुका था। किंतु बच्चे के कोमल अंगों का स्पर्श पाते ही उसके हृदय में वात्सल्य और कोमलता का ऐसा झरना फूटा मानो कठोर काँटों वाले वृक्ष से भी शेफालिका के सुगंधित फूल झड़ने लगे हों।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (क): निर्धनता में शिशु को कमल जैसा दिव्य मानना</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (ख): कठोर मन के वात्सल्य में पिघलने का मार्मिक भाव</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch11-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch11-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">'फसल' कविता के आधार पर स्पष्ट कीजिए कि फसल क्या है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि नागार्जुन के अनुसार फसल किसी एक तत्व का परिणाम नहीं है, बल्कि प्रकृति और मानव-श्रम के अद्भुत समन्वय का फल है:</p>\n          <ol>\n            <li>हजार-हजार नदियों के अमृत-समान जल का जादुई प्रभाव।</li>\n            <li>करोड़ों कर्मठ किसानों और मजदूरों के हाथों के कठोर परिश्रम व स्पर्श की गरिमा।</li>\n            <li>विभिन्न प्रकार की उपजाऊ मिट्टियों (काली, दोमट, संदली) के पोषक तत्वों का सम्मिश्रण।</li>\n            <li>सूरज की किरणों की ऊर्जा और वायु की मंद थिरकन का रूपांतरण।</li>\n          </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रकृति के तत्वों (जल, मिट्टी, धूप, हवा) का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">करोड़ों किसानों के श्रम के योगदान की महत्ता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch11-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch11-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">'फसल को हाथों के स्पर्श की गरिमा और महिमा' कहकर कवि क्या व्यक्त करना चाहता है?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि यह स्पष्ट करना चाहता है कि यद्यपि प्रकृति (मिट्टी, जल, धूप) फसल के विकास के लिए कच्चा माल देती है, किंतु जब तक किसान और मजदूर अपने पसीने और हाथों के स्पर्श से उसकी जुताई, बुवाई और सींचन नहीं करते, तब तक अन्न का दाना नहीं उग सकता। कवि यहाँ श्रमिक वर्ग के श्रम के प्रति गहरी कृतज्ञता और सम्मान व्यक्त कर रहा है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मानव श्रम के बिना प्राकृतिक तत्वों की निष्फलता</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">किसान के श्रम की गरिमा व प्रतिष्ठा</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch11-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch11-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">भाव स्पष्ट कीजिए— \"रूपांतर है सूरज की किरणों का, सिमटा हुआ संकोच है हवा की थिरकन का!\"</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>भावार्थ:</strong> फसल के निर्माण में सूर्य की ऊष्मा और वायु का अमूल्य योगदान है। पौधे प्रकाश-संश्लेषण द्वारा सूर्य की किरणों की ऊर्जा को अन्न के दानों में रूपांतरित कर लेते हैं।</p>\n          <p>साथ ही, वायु की मंद थिरकन और स्पर्श पौधों में जीवन का संकोच और कोमलता भरकर उन्हें लहलहाता है। अतः फसल सूरज की धूप और हवा की गति का ही मूर्त रूप है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सूर्य की किरणों के ऊर्जा रूपांतरण का वैज्ञानिक-काव्यात्मक भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वायु की थिरकन के संकोच रूपी योगदान का अंकन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch11-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch11-q8')\">\n      <div class=\"q-num\">प्रश्न 8</div>\n      <div class=\"q-text\">कविता में फसल उपजाने के लिए आवश्यक तत्वों की बात कही गई है। वे आवश्यक तत्व कौन-कौन से हैं?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कविता के अनुसार फसल के लिए पाँच मुख्य तत्व अनिवार्य हैं:</p>\n          <ol>\n            <li><strong>पानी:</strong> नदियों का निर्मल जल।</li>\n            <li><strong>मिट्टी:</strong> खेतों की उपजाऊ मिट्टी के पोषक गुणधर्म।</li>\n            <li><strong>धूप:</strong> सूरज की किरणों की जीवनदायिनी ऊर्जा।</li>\n            <li><strong>हवा:</strong> वायु की थिरकन।</li>\n            <li><strong>मानव श्रम:</strong> करोड़ों किसानों और मजदूरों के हाथों का कठोर परिश्रम।</li>\n          </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पाँचों प्राकृतिक व मानवीय तत्वों का सटीक उल्लेख</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: केस-आधारित पर्यावरण व श्रम चेतना (Competency Question)</div>\n      <div class=\"cbq-question\">\n        वर्तमान उपभोक्तावादी युग में कृषि और किसान की उपेक्षा बढ़ती जा रही है। नागार्जुन की कविता 'फसल' आज के संदर्भ में हमें पर्यावरण और कृषक समाज के प्रति क्या दृष्टिकोण अपनाने की प्रेरणा देती है?\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        कविता यह सिद्ध करती है कि मानव जीवन की उत्तरजीविता प्रकृति (नदियों की शुचिता, मिट्टी की उर्वरता) और किसानों के पसीने पर टिकी है। यदि हम नदियों को प्रदूषित करेंगे, रासायनिक खादों से मिट्टी की शक्ति नष्ट करेंगे या अन्नदाता किसान के श्रम का यथोचित सम्मान नहीं करेंगे, तो हमारी खाद्य सुरक्षा और अस्तित्व संकट में पड़ जाएगा। अतः हमें प्रकृति का संरक्षण और कृषक वर्ग का सम्मान करना अनिवार्य है।\n      </div>\n    </div>\n  </div>\n</section>","12":"<section class=\"chapter-section\" id=\"ch12\" data-book=\"kshitij-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">12</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-2 (काव्य खंड) — पाठ 12</div>\n      <h2>संगतकार</h2>\n      <p>मंगलेश डबराल | समकालीन कविता — पृष्ठभूमि के सहायकों की भूमिका, निस्वार्थ योगदान और मानवीय संवेदना | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch12-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch12-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">संगतकार के माध्यम से कवि किस प्रकार के व्यक्तियों की ओर संकेत करना चाह रहा है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>संगतकार के माध्यम से कवि समाज के उन समस्त सहकर्मियों, सहायकों और पृष्ठभूमि में रहकर काम करने वाले व्यक्तियों की ओर संकेत कर रहा है, जो किसी भी मुख्य नायक, नेता, अभिनेता या संस्था की सफलता में रीढ़ की हड्डी की तरह कार्य करते हैं। वे स्वयं कभी प्रसिद्धि के केंद्र में नहीं आते, बल्कि पर्दे के पीछे रहकर मुख्य व्यक्ति को ऊँचाइयों पर पहुँचाने के लिए अपना सर्वस्व न्योछावर कर देते हैं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पर्दे के पीछे कार्य करने वाले सहायकों का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मुख्य नायक की सफलता में निस्वार्थ योगदान का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch12-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch12-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">संगतकार जैसे व्यक्ति संगीत के अलावा और किन-किन क्षेत्रों में दिखाई देते हैं?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>संगतकार जैसे समर्पित व्यक्ति जीवन के प्रत्येक क्षेत्र में मौजूद रहते हैं:</p>\n          <ul>\n            <li><strong>खेल के मैदान में:</strong> क्रिकेट या फुटबॉल में कप्तान के अलावा वे खिलाड़ी जो फील्डिंग, पासिंग या रणनीति में चुपचाप योगदान देते हैं; तथा कोच व सपोर्ट स्टाफ।</li>\n            <li><strong>सिनेमा और नाटक:</strong> मुख्य अभिनेता की सफलता के पीछे काम करने वाले निर्देशक, कैमरामैन, स्पॉटबॉय, मेकअप आर्टिस्ट और सह-कलाकार।</li>\n            <li><strong>राजनीति और समाज सेवा:</strong> बड़े नेता की रैलियों और चुनावी जीत की तैयारी करने वाले जमीनी कार्यकर्ता।</li>\n            <li><strong>चिकित्सा क्षेत्र:</strong> सफल शल्य-चिकित्सा (सर्जरी) में मुख्य सर्जन की सहायता करने वाले एनेस्थेटिस्ट और नर्सें।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">खेल व सिनेमा के उदाहरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">राजनीति व चिकित्सा/शल्य के उदाहरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch12-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch12-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">संगतकार की मुख्य गायक के सुर में अपना सुर मिलाने की भूमिका को स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>संगतकार मुख्य गायक की भारी, गंभीर और गरजदार आवाज़ में अपनी गूँजती, कोमल और सुंदर आवाज़ मिलाकर गायन को पूर्णता और गहराई प्रदान करता है। वह मुख्य गायक के बिखरे हुए सुरों को समेटता है और उसके द्वारा छोड़े गए स्थायी (टेक) को संभालकर गीत के प्रवाह को अखंड बनाए रखता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मुख्य गायक की आवाज़ को गहराई व पूर्णता देना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्थायी को संभालकर गायन के प्रवाह को जीवित रखना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch12-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch12-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">कवि ने संगतकार की आवाज में जो हिचक बताई है, उसे उसकी असफलता न मानकर 'मनुष्यता' क्यों कहा गया है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>संगतकार में मुख्य गायक से भी ऊँचा और बेहतर गाने की योग्यता व प्रतिभा हो सकती है, किंतु वह कभी जानबूझकर अपनी आवाज़ को मुख्य गायक की आवाज़ से ऊपर नहीं उठने देता।</p>\n          <p>उसकी यह हिचक उसकी किसी कमजोरी या अक्षमता की परिचायक नहीं है, बल्कि यह उसके मन में मुख्य गायक के प्रति अपार आदर, गुरु-शिष्य की मर्यादा और निस्वार्थ त्याग की भावना है। वह अपने अहंकार को दबाकर मुख्य गायक की प्रतिष्ठा की रक्षा करता है, इसलिए कवि इसे उसकी कमजोरी न मानकर सर्वोच्च 'मनुष्यता' कहता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रतिभा होते हुए भी स्वयं को संयमित रखने का गुण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मुख्य गायक के सम्मान व त्याग को मनुष्यता मानने का तर्क</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch12-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch12-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">मुख्य गायक जब अनहद में खो जाता है या उसका गला बैठने लगता है, तब संगतकार क्या भूमिका निभाता है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>जब मुख्य गायक कठिन तानों के अनहद भँवर में खोकर भटकने लगता है या तारसप्तक में गाते हुए उसकी आवाज़ टूटने और उत्साह बुझने लगता है, तब संगतकार पीछे से अपनी कोमल, ढाढ़स बँधाती आवाज़ से स्थायी को पकड़ लेता है। वह मुख्य गायक को यह एहसास दिलाता है कि वह अकेला नहीं है और जो राग गाया जा चुका है, उसे पुनः नए सिरे से उठाया जा सकता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्थायी को संभालकर गायक का ढाढ़स बँधाना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अकेलापन दूर कर संगीत को बिखरने से बचाने का कार्य</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch12-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch12-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">कभी-कभी तारसप्तक की ऊँचाई पर मुख्य गायक को संगतकार उसके 'बचपन के नौसिखियापन' की याद कैसे दिलाता है?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>जब मुख्य गायक थककर बिखरने लगता है, तो संगतकार का साथ उसे उस समय की याद दिला देता है जब वह स्वयं संगीत का एक नौसिखिया विद्यार्थी था और उसका गुरु उसे इसी तरह सहारा देकर सुर पकड़ना सिखाता था। यह स्मृति मुख्य गायक के मन में पुनः नई ऊर्जा और विनम्रता भर देती है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नौसिखियापन और सीखने के दौर की स्मृति का विश्लेषण</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: अभिकथन और कारण (Assertion &amp; Reason)</div>\n      <div class=\"cbq-question\">\n        <strong>अभिकथन (A):</strong> संगतकार मुख्य गायक के बिखरते हुए आत्मविश्वास को पुनः संबल प्रदान करता है।<br>\n        <strong>कारण (R):</strong> जब तारसप्तक में मुख्य गायक का गला बैठने लगता है और उत्साह बुझने लगता है, तब संगतकार अपने ढाढ़स बँधाते स्वर से गीत की टेक को संभाल लेता है।<br>\n        <strong>विकल्प:</strong><br>\n        (क) (A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।<br>\n        (ख) (A) और (R) दोनों सही हैं, परंतु (R), (A) की सही व्याख्या नहीं करता।<br>\n        (ग) (A) सही है, परंतु (R) गलत है।<br>\n        (घ) (A) गलत है, परंतु (R) सही है।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>सही उत्तर: (क)</strong><br>\n        <em>व्याख्या:</em> संगतकार मुख्य गायक को कभी अकेला महसूस नहीं होने देता और तारसप्तक की जटिल तानों के समय स्थायी को पकड़कर उसकी गरिमा को गिरने से बचाता है, अतः (R) बिल्कुल सही व्याख्या करता है।\n      </div>\n    </div>\n  </div>\n</section>","13":"<section class=\"chapter-section\" id=\"ch13\" data-book=\"kritika\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">13</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">कृतिका भाग-2 — पाठ 1</div>\n      <h2>माता का आँचल</h2>\n      <p>शिवपूजन सहाय (उपन्यास 'देहाती दुनिया' से) | संस्मरण — ग्रामीण बाल्यकाल, वात्सल्य, पिता-पुत्र का स्नेह और संकट में मातृ-छाया | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch13-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch13-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">प्रस्तुत पाठ के आधार पर यह कहा जा सकता है कि बच्चे का अपने पिता से अधिक जुड़ाव था, फिर भी विपदा के समय वह पिता के पास न जाकर माँ की शरण लेता है। आपकी समझ से इसकी क्या वजह हो सकती है?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>भोलानाथ का अधिकांश समय पिता के साथ ही बीतता था—पिता ही उसे नहलाते-धुलाते, पूजा में बिठाते, साथ खिलाते और घुमाने ले जाते थे। माँ से उसका संबंध केवल दूध पीने तक सीमित प्रतीत होता था।</p>\n          <p>किंतु जब बच्चे पर साँप का भीषण भय और संकट आया, तो वह बाहर बरामदे में बैठे पिता के पुकारने पर भी उनके पास न जाकर सीधा अंदर माँ की गोद में जाकर छिप गया। इसके मुख्य कारण निम्नलिखित हैं:</p>\n          <ul>\n            <li><strong>सुरक्षा और शांति की चरम अनुभूति:</strong> माँ का आँचल बच्चे के लिए प्रेम, ममता और सुरक्षा का सबसे अभेद्य किला होता है। संकट की घड़ी में माँ के हृदय की धड़कन बच्चे के भय को तुरंत शांत कर देती है।</li>\n            <li><strong>सहज वात्सल्य और ममता:</strong> माँ के आँचल में जो ममतामयी गर्माहट, कोमलता और अश्रुपूरित सहानुभूति मिलती है, वह पिता के कठोर संरक्षण में नहीं मिल पाती। माँ बच्चे के दर्द को देखकर स्वयं रो पड़ती है और उसे अपनी छाती से चिपका लेती है।</li>\n            <li><strong>प्राकृतिक मनोवैज्ञानिक सुरक्षा:</strong> विपदा के समय बालक स्वाभाविक रूप से उस शरणस्थली की ओर भागता है जहाँ उसे असीम अपनत्व और निर्भयता का बोध हो, और वह स्थान माँ का आँचल ही है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पिता के साथ दैनिक दिनचर्या व जुड़ाव का संदर्भ</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">माँ के आँचल में सुरक्षा, ममता व शांति की मनोवैज्ञानिक व्याख्या</span><span class=\"marking-marks\">2.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch13-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch13-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">आपके विचार से भोलानाथ अपने साथियों को देखकर सिसकना क्यों भूल जाता है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>बाल-मन स्वभाव से अत्यंत चंचल, खेलप्रिय और साथी-उन्मुख होता है। जब भोलानाथ माँ द्वारा कड़वा तेल लगाने और चोटी गूँथने पर रोने-सिसकने लगता था, तब पिता उसे गोद में उठाकर बाहर लाते थे।</p>\n          <p>किंतु जैसे ही भोलानाथ बाहर अपनी हमउम्र बाल-मंडली को तरह-तरह के खेल खेलते और हुल्लड़ मचाते देखता, उसका ध्यान अपने दुख-दर्द से हटकर खेल के स्वाभाविक आकर्षण में खो जाता था। बाल-मनोविज्ञान के अनुसार साथियों का संग बच्चों के हर कष्ट को भुला देता है, इसलिए वह पिता की गोद से उतरकर तुरंत सिसकना भूल जाता था।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बाल-मन की खेलप्रियता व चंचलता का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मित्र-मंडली के आकर्षण द्वारा दुख भूलने का मनोवैज्ञानिक विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch13-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch13-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">आपने देखा होगा कि भोलानाथ और उसके साथी जब-तब ऐसे खेल खेलते थे जिनमें दैनिक जीवन की वस्तुओं का उपयोग होता था। पाठ में वर्णित खेलों और आज के बच्चों के खेलों में क्या अंतर है?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>पाठ में वर्णित खेलों और आज के आधुनिक खेलों में ज़मीन-आसमान का अंतर आ गया है:</p>\n          <ul>\n            <li><strong>प्राकृतिक व सामूहिक खेल (तत्कालीन समय):</strong> भोलानाथ और उसके साथी मिट्टी, दीये, ठीकरी, पत्तों, तिनकों और टूटी-फूटी घरेलू वस्तुओं से खेल रचते थे (जैसे मिठाई की दुकान, बारात, खेती करना)। इन खेलों में प्रकृति से सीधा जुड़ाव, असीमित रचनात्मकता और समूह में परस्पर सहयोग की भावना थी। इनमें कोई आर्थिक खर्च नहीं था।</li>\n            <li><strong>एकाकी व तकनीकी खेल (वर्तमान समय):</strong> आज के बच्चे घर की चारदीवारी में वीडियो गेम्स, मोबाइल, कंप्यूटर और प्लास्टिक/इलेक्ट्रॉनिक खिलौनों में उलझे रहते हैं। इन खेलों में सामाजिक मेलजोल, शारीरिक परिश्रम और मौलिक कल्पनाशीलता का अभाव होता है तथा ये अत्यंत खर्चीले होते हैं।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भोलानाथ के खेलों की स्वाभाविकता, रचनात्मकता व सामूहिक सहभागिता</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वर्तमान आधुनिक/गैजेट-आधारित एकाकी खेलों से तुलनात्मक विश्लेषण</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch13-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch13-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">पाठ में आए ऐसे प्रसंगों का वर्णन कीजिए जो आपके दिल को छू गए हों।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>पाठ में अनेक ऐसे हृदयस्पर्शी प्रसंग हैं जो पाठक के मन को गहराई से छू लेते हैं:</p>\n          <ol>\n            <li><strong>पिता-पुत्र का वात्सल्य:</strong> पिता द्वारा भोलानाथ को पूजा में बिठाकर भभूत का तिलक लगाना और उसे 'बबुआ' कहना तथा कुश्ती में जानबूझकर बच्चे से हार जाना पिता के अगाध वात्सल्य को दर्शाता है।</li>\n            <li><strong>माता का वात्सल्यमयी खिलाना:</strong> माँ का यह कहकर विभिन्न पक्षियों के नाम पर कौर बनाकर खिलाना कि \"जल्दी खा लो नहीं तो उड़ जाएँगे\" बाल-सुलभ चंचलता को जीवंत करता है।</li>\n            <li><strong>साँप के भय से माँ की शरण:</strong> अंत में लहूलुहान और भयभीत होकर भोलानाथ का माँ के आँचल में मुँह छिपाना और माँ का व्याकुल होकर रो पड़ना ममता की पराकाष्ठा है।</li>\n          </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कम से कम 2-3 हृदयस्पर्शी प्रसंगों का सटीक उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भावुकता व वात्सल्य रस की सुस्पष्ट अभिव्यक्ति</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch13-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch13-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">'माता का आँचल' शीर्षक की उपयुक्तता बताते हुए कोई अन्य शीर्षक सुझाइए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>शीर्षक की सार्थकता:</strong> 'माता का आँचल' शीर्षक अत्यंत उपयुक्त, सार्थक और मर्मस्पर्शी है। यद्यपि पूरे पाठ में पिता के साथ बालक की दिनचर्या और खेल-कूद का विस्तार है, किंतु कहानी का चरमोत्कर्ष और केंद्रीय भाव उस क्षण प्रकट होता है जब भारी संकट में बालक पिता की पुकार छोड़कर सीधे माँ के आँचल में आश्रय पाता है। माँ का आँचल ही शांति, सांत्वना और सुरक्षा का अंतिम दुर्ग सिद्ध होता है।</p>\n          <p><strong>अन्य उपयुक्त शीर्षक:</strong> <em>'बचपन के वे दिन'</em>, <em>'मातृ-छाया'</em> अथवा <em>'भोलानाथ का बचपन'</em>।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शीर्षक के चरमोत्कर्ष व मूल भाव से जुड़ाव का औचित्य</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तर्कसंगत वैकल्पिक शीर्षक का प्रस्ताव</span><span class=\"marking-marks\">1 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch13-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch13-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">बच्चे माता-पिता के प्रति अपने प्रेम को कैसे अभिव्यक्त करते हैं?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>बच्चे अपने माता-पिता के प्रति प्रेम शब्दों द्वारा नहीं बल्कि अपनी सहज क्रियाओं और चेष्टाओं द्वारा व्यक्त करते हैं:</p>\n          <ul>\n            <li>माता-पिता की गोद में लिपटकर और उनके कंधे पर बैठकर अपनी प्रसन्नता प्रकट करना।</li>\n            <li>अपनी छोटी-छोटी बातें, जिज्ञासाएँ और दिनभर के किस्से बिना झिझक उनके साथ साझा करना।</li>\n            <li>माता-पिता के साथ खेलते हुए रूठना, लाड़ जताना और उन्हें चूमना।</li>\n            <li>विपत्ति या डर के समय माता-पिता के गले लग जाना और उनके आँचल में सुरक्षा महसूस करना।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बालक की सहज शारीरिक व भावनात्मक अभिव्यक्तियों का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">विश्वास व अपनत्व की मनोवैज्ञानिक व्याख्या</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch13-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch13-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">इस उपन्यास अंश में तीस के दशक की ग्रामीण संस्कृति का चित्रण है। आज की ग्रामीण संस्कृति में आपको किस तरह के परिवर्तन दिखाई देते हैं?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>तीस के दशक की ग्रामीण संस्कृति और आज के ग्रामीण परिवेश में निम्नलिखित गहरे परिवर्तन आ चुके हैं:</p>\n          <ul>\n            <li><strong>सामूहिकता का ह्रास:</strong> तीस के दशक में पूरा गाँव एक परिवार की तरह था, जहाँ बच्चों की सामूहिक टोलियाँ दिनभर खेतों और गलियों में खेलती थीं। आज गाँवों में भी एकल परिवार और व्यक्तिगत व्यस्तताएँ बढ़ गई हैं।</li>\n            <li><strong>खेल-कूद और मनोरंजन:</strong> पहले बच्चे धूल-मिट्टी, पेड़ों और घरेलू साधनों से खेलते थे। आज गाँवों में भी मोबाइल फोन, टीवी और इंटरनेट का प्रसार हो गया है।</li>\n            <li><strong>सांस्कृतिक और जीवनशैली में बदलाव:</strong> पहले के कच्चे घर, लोकगीत, चौपालें और पारंपरिक कृषि उपकरण अब पक्के मकानों, आधुनिक मशीनों (ट्रैक्टर आदि) और पाश्चात्य जीवनशैली से प्रतिस्थापित हो चुके हैं। यद्यपि शिक्षा व स्वास्थ्य के साधन बेहतर हुए हैं, किंतु पारस्परिक अपनत्व कम हुआ है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तीस के दशक के ग्रामीण जीवन (पारस्परिकता, खेल) का विश्लेषण</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आधुनिक तकनीकी व सामाजिक परिवर्तनों का तुलनात्मक विवेचन</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch13-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch13-q8')\">\n      <div class=\"q-num\">प्रश्न 8</div>\n      <div class=\"q-text\">'भोलानाथ' नाम कैसे पड़ा और उसका वास्तविक नाम क्या था?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखक का वास्तविक नाम <strong>तारकेश्वर नाथ</strong> था।</p>\n          <p>उनके पिता पूजा-अर्चना के समय उन्हें अपने पास बिठाकर उनके चौड़े ललाट पर भभूत का त्रिपुंड कर देते थे। सिर पर लंबी जटाएँ होने के कारण वे 'बम-भोला' जैसे दिखाई देने लगते थे। उनके पिता बड़े प्यार से उन्हें 'भोलानाथ' कहकर पुकारते थे। अतः परिवार और मित्रों के बीच उनका नाम 'भोलानाथ' ही प्रचलित हो गया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वास्तविक नाम 'तारकेश्वर नाथ' का सही उल्लेख</span><span class=\"marking-marks\">1 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">त्रिपुंड, जटाओं व पिता द्वारा प्यार से पुकारे जाने का प्रसंग</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch13-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch13-q9')\">\n      <div class=\"q-num\">प्रश्न 9</div>\n      <div class=\"q-text\">पाठ में वर्णित बारात के जुलूस और भोज का दृश्य किस प्रकार तत्कालीन सामाजिक जीवन का यथार्थ चित्र प्रस्तुत करता है?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>पाठ में बच्चों द्वारा कल्पित बारात का खेल तत्कालीन ग्रामीण रीति-रिवाजों और सामाजिक जीवन का सजीव आईना है:</p>\n          <ul>\n            <li><strong>पारंपरिक वैवाहिक रस्में:</strong> टूटे चूहेदानी की पालकी बनाना, आम के पत्तों की शहनाई, बकरे को घोड़ा बनाना और समधी बनकर हुक्का पीना तत्कालीन ग्रामीण विवाह के वास्तविक दृश्यों का बाल-अनुकरण है।</li>\n            <li><strong>पंगत भोज की संस्कृति:</strong> ढेलों के चूल्हे, दीयों की कड़ाही और गीली मिट्टी की पूरियाँ बनाकर पंगत में बिठाकर खिलाना उस युग के सामूहिक भोज और सामाजिक सौहार्द को दर्शाता है।</li>\n            <li><strong>बड़ों की स्नेहपूर्ण सहभागिता:</strong> जब पिता आकर पूछते कि \"भोज में क्या बना है?\" या पालकी का परदा उठाकर दुलहिन का मुख देखने की चेष्टा करते, तो बच्चे हँसकर भाग जाते। यह बड़ों और बच्चों के बीच के सहज वात्सल्य और अपनत्व को प्रमाणित करता है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बारात व भोज के प्रतीकात्मक खेल का यथार्थ वर्णन</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तत्कालीन सामाजिक सौहार्द व बड़ों के वात्सल्य का विश्लेषण</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Competency-Based Questions (CBQs) -->\n  <div class=\"cbq-card\">\n    <div class=\"cbq-badge\">CBSE Board Competency-Based Question (योग्यता आधारित प्रश्न)</div>\n    <div class=\"q-text\"><strong>प्रकरण अध्ययन (Case Study):</strong> 'माता का आँचल' पाठ यह स्थापित करता है कि शिशु की मानसिक व संवेगात्मक सुरक्षा के केंद्र में माँ का स्थान अद्वितीय है। वर्तमान समय में कार्यस्थल की व्यस्तता और डे-केयर संस्कृति के बीच बच्चे और माता-पिता के संवेगात्मक संबंधों पर पड़ने वाले प्रभावों का आलोचनात्मक मूल्यांकन कीजिए।</div>\n    <div class=\"answer-box\" style=\"margin-top: 15px;\">\n      <div class=\"answer-label\">विशेषज्ञ उत्तर व विश्लेषणात्मक दृष्टिकोण</div>\n      <div class=\"answer-text\">\n        <p><strong>विश्लेषण:</strong> पाठ में संकट के समय भोलानाथ का माँ के आँचल में छिपना यह प्रमाणित करता है कि बच्चे को शारीरिक कष्ट से अधिक संवेगात्मक आश्वस्ति की आवश्यकता होती है, जो केवल माँ के स्पर्श और स्नेह से मिलती है।</p>\n        <p><strong>वर्तमान संदर्भ में प्रभाव:</strong> आधुनिक जीवनशैली में माता-पिता की व्यस्तता और स्क्रीन-निर्भरता के कारण बच्चों में भावनात्मक अकेलापन बढ़ रहा है। अतः यह आवश्यक है कि भौतिक सुख-सुविधाओं के स्थान पर गुणवत्तापूर्ण समय (Quality Time) और प्रत्यक्ष संवेगात्मक सम्बल दिया जाए, ताकि बच्चे का मानसिक और नैतिक विकास सुदृढ़ हो सके।</p>\n      </div>\n    </div>\n  </div>\n</section>","14":"<section class=\"chapter-section\" id=\"ch14\" data-book=\"kritika\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">14</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">कृतिका भाग-2 — पाठ 2</div>\n      <h2>साना-साना हाथ जोड़ि...</h2>\n      <p>मधु कांकरिया | यात्रा-वृतांत — पूर्वोत्तर भारत, सिक्किम (गंतोक, युमथांग, कटाओ), प्राकृतिक सौंदर्य और श्रमशील नारियों का जीवन | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch14-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch14-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">झिलमिलाते सितारों की रोशनी में नहाया गंतोक लेखिका को किस तरह सम्मोहित कर रहा था?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>रात के समय गंतोक शहर की खूबसूरती जादुई और अद्भुत प्रतीत हो रही थी। ढलान पर बनी बस्तियों में जगमगाती बत्तियों की लड़ियाँ सितारों के गुच्छे जैसी चमक रही थीं, मानो आसमान उलट पड़ा हो और सारे सितारे ज़मीन पर बिखर गए हों।</p>\n          <p>इस रहस्यमयी सौंदर्य ने लेखिका के भीतर और बाहर एक गहरा सन्नाटा भर दिया। उनकी चेतना पूरी तरह सम्मोहित हो गई थी और वे उस जादुई उजास में स्वयं को शून्य और विस्मय में डूबा हुआ महसूस कर रही थीं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">जगमगाती रोशनी व सितारों के बिंब का चित्रण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">लेखिका के अंतर्मन पर सम्मोहन व शांति का प्रभाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch14-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch14-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">गंतोक को 'मेहनतकश बादशाहों का शहर' क्यों कहा गया?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>गंतोक को 'मेहनतकश बादशाहों का शहर' इसलिए कहा गया है क्योंकि यहाँ का सौंदर्य किसी राजा-महाराजा के विलास का परिणाम नहीं, बल्कि यहाँ के आम नागरिकों के अथक परिश्रम और पसीने की देन है।</p>\n          <p>यहाँ के स्त्री-पुरुष और बच्चे विषम पहाड़ी परिस्थितियों, हाड़ कंपाती ठंड और दुर्गम रास्तों में भी निरंतर कठोर श्रम करते हैं। वे कठिन परिस्थितियों में भी स्वाभिमान, गरिमा और मुस्कान के साथ जीवन जीते हैं, इसलिए उन्हें 'बादशाह' कहा गया है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कठिन भौगोलिक परिस्थिति व कठोर परिश्रम का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्वाभिमान, मस्तमौलापन व 'बादशाह' संज्ञा का औचित्य</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch14-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch14-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">कभी श्वेत तो कभी रंगीन पताकाओं का फहराना किन अलग-अलग अवसरों की ओर संकेत करता है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>सिक्किम में बौद्ध मान्यताओं के अनुसार पताकाओं का फहराना विशिष्ट अवसरों का प्रतीक है:</p>\n          <ul>\n            <li><strong>श्वेत पताकाएँ:</strong> जब किसी बौद्ध भिक्षु या मतावलंबी की मृत्यु होती है, तो उसकी आत्मा की शांति के लिए शहर से दूर किसी पवित्र स्थान पर 108 श्वेत पताकाएँ फहराई जाती हैं, जिन पर मंत्र लिखे होते हैं। इन्हें उतारा नहीं जाता, ये स्वतः नष्ट हो जाती हैं।</li>\n            <li><strong>रंगीन पताकाएँ:</strong> जब किसी नए कार्य का शुभारंभ होता है या कोई शुभ अवसर होता है, तब रंग-बिरंगी पताकाएँ लगाई जाती हैं।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">श्वेत पताका (शोक/मृत्यु व 108 संख्या) का संदर्भ</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">रंगीन पताका (शुभ कार्य/नया आरंभ) का संदर्भ</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch14-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch14-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">जितेन नार्गे ने लेखिका को सिक्किम की प्रकृति, वहाँ की भौगोलिक स्थिति एवं जनजीवन के बारे में क्या महत्त्वपूर्ण जानकारियाँ दीं, लिखिए।</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>गाइड जितेन नार्गे ने सिक्किम के संदर्भ में निम्नलिखित प्रामाणिक व रोचक जानकारियाँ दीं:</p>\n          <ul>\n            <li><strong>भौगोलिक व प्राकृतिक स्वरूप:</strong> गंतोक से युमथांग की दूरी 149 किमी है। रास्ते में तीस्ता नदी, पाइन और धूपी के घने जंगल, तथा घाटियों में खिले 'प्रिमता' और 'रूडोडेन्ड्रॉन' के फूल मन मोह लेते हैं।</li>\n            <li><strong>धार्मिक विश्वास व संस्कृति:</strong> यहाँ बौद्ध धर्म का व्यापक प्रभाव है। 'धर्म-चक्र' (प्रेयर व्हील) को घुमाने से सारे पाप धुल जाते हैं। खेदुम में देवी-देवताओं का वास माना जाता है जहाँ लोग गंदगी नहीं फैलाते।</li>\n            <li><strong>कठिन जनजीवन:</strong> पहाड़ की औरतें पीठ पर बँधी डोको (टोकरी) में बच्चों को लेकर पत्थर तोड़कर सड़कें बनाती हैं। बच्चे 3-4 किमी की चढ़ाई चढ़कर स्कूल पढ़ने जाते हैं और शाम को मवेशी चराते व लकड़ियाँ ढोते हैं।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रकृति, मार्ग व वनस्पतियों का विवरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">धार्मिक आस्थाएँ (धर्म-चक्र आदि) व जनजीवन का संघर्ष</span><span class=\"marking-marks\">2.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch14-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch14-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">'लोंग स्टॉक' में घूमते हुए चक्र को देखकर लेखिका को पूरे भारत की आत्मा एक-सी क्यों दिखाई दी?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि लोंग स्टॉक में जितेन नार्गे ने एक कुटिया में घूमता हुआ 'धर्म चक्र' (प्रेयर व्हील) दिखाते हुए कहा कि इसे घुमाने से सारे पाप धुल जाते हैं।</p>\n          <p>यह सुनकर लेखिका ने सोचा कि चाहे मैदान हो या पहाड़, तमाम वैज्ञानिक प्रगति के बावजूद पूरे भारत की अंतरात्मा एक ही जैसी है। पूरे देश के लोगों की आस्थाएँ, विश्वास, अंधविश्वास, पाप-पुण्य की अवधारणाएँ और कल्पनाएँ एक समान हैं। यह सांस्कृतिक एकता पूरे भारत को एक सूत्र में पिरोती है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">धर्म-चक्र व पाप-पुण्य की लोक-मान्यता का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अखिल भारतीय सांस्कृतिक व संवेगात्मक एकता का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch14-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch14-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">जितेन नार्गे की गाइड की भूमिका के बारे में विचार करते हुए लिखिए कि एक कुशल गाइड में क्या गुण होते हैं?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>जितेन नार्गे केवल ड्राइवर ही नहीं, एक अत्यंत कुशल, संवेदनशील और मार्गदर्शक गाइड सिद्ध हुआ। एक कुशल गाइड में निम्नलिखित गुण होने आवश्यक हैं:</p>\n          <ul>\n            <li><strong>स्थानीय भूगोल व संस्कृति का गहन ज्ञान:</strong> गाइड को क्षेत्र के इतिहास, मार्गों, धार्मिक मान्यताओं और लोक-संस्कृति की प्रामाणिक जानकारी होनी चाहिए, जैसे नार्गे को गाइड फिल्म की शूटिंग स्थल, खेदुम और कटाओ का ज्ञान था।</li>\n            <li><strong>वाक्पटुता व मिलनसार स्वभाव:</strong> उसे पर्यटकों को रोचक प्रसंगों और लोकगीतों से बाँधे रखने की कला आनी चाहिए।</li>\n            <li><strong>धैर्य व संवेदनशीलता:</strong> विषम और संकटकालीन परिस्थितियों में शांत रहकर पर्यटकों को सुरक्षित रखने तथा उनका उत्साह बनाए रखने की क्षमता होनी चाहिए।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">जितेन नार्गे के चरित्र-गुणों का मूल्यांकन</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">एक आदर्श गाइड के अनिवार्य व्यावहारिक गुणों का बिंदुवार निरूपण</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch14-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch14-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">इस यात्रा-वृतांत में लेखिका ने हिमालय के जिन रूपों का चित्र खींचा है, उन्हें अपने शब्दों में लिखिए।</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखिका ने यात्रा के दौरान हिमालय के पल-पल परिवर्तित होते भव्य और विस्मयकारी रूपों का चित्रण किया है:</p>\n          <ul>\n            <li><strong>विशाल और विराट रूप:</strong> जैसे-जैसे गाड़ी ऊँचाई पर बढ़ती है, हिमालय अपने छोटे रूप को त्यागकर विशालकाय और विराट स्वरूप में प्रकट होने लगता है। घाटियाँ पाताल जैसी गहरी और पर्वत गगनचुंबी नजर आते हैं।</li>\n            <li><strong>रंगों का जादुई खेल:</strong> कहीं हरी मखमली चादर ओढ़े पर्वत, कहीं पीले-भूरे पत्थरों के पहाड़, तो कहीं बादलों की ओट में छिपा हिमालय।</li>\n            <li><strong>दूधिया झरने व बर्फीला सौन्दर्य:</strong> 'सेवेन सिस्टर्स वाटरफॉल' जैसे कलकल बहते दूधिया झरने और कटाओ में चाँदी की तरह चमकती ताज़ी बर्फ हिमालय को अलौकिक और स्वर्गीय बनाती है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हिमालय के विराट व पल-पल बदलते रूपों का बिंब</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">झरनों, घाटियों व बर्फीले शिखरों की काव्यात्मक अभिव्यक्ति</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch14-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch14-q8')\">\n      <div class=\"q-num\">प्रश्न 8</div>\n      <div class=\"q-text\">प्रकृति ने जल-संचय की व्यवस्था किस प्रकार की है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>प्रकृति ने जल-संचय की एक अत्यंत अद्भुत और अनोखी व्यवस्था कर रखी है।</p>\n          <p>सर्दियों में प्रकृति हिमालय के ऊँचे शिखरों पर बर्फ के रूप में जल का विशाल भंडार संचित कर लेती है। जब गर्मियों में मैदानी भागों में भीषण गर्मी पड़ती है और त्राहि-त्राहि मचती है, तब ये ही हिम-शिखर पिघल-पिघलकर जलधारा बनते हैं और नदियों के रूप में प्रवाहित होकर करोड़ों कंठों की प्यास बुझाते हैं तथा खेतों को सींचते हैं। प्रकृति का यह जल-स्तंभ समस्त जीव-जगत के पोषण का मूल आधार है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सर्दियों में बर्फ के रूप में जल संचय की वैज्ञानिक-प्राकृतिक प्रक्रिया</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गर्मियों में पिघलकर नदियों द्वारा जीवन पोषण की व्याख्या</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch14-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch14-q9')\">\n      <div class=\"q-num\">प्रश्न 9</div>\n      <div class=\"q-text\">देश की सीमा पर बैठे फ़ौजी किस तरह की कठिनाइयों से जूझते हैं? उनके प्रति हमारा क्या उत्तरदायित्व होना चाहिए?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>सैनिकों की कठिनाइयाँ:</strong> हमारे वीर सैनिक शून्य से भी नीचे (-15° से -30°C) तापमान में, जहाँ पेट्रोल भी जम जाता है और हाथ-पैर सुन्न हो जाते हैं, दिन-रात मुस्तैदी से पहरा देते हैं। वे अपने परिवार और प्रियजनों से मीलों दूर रहकर प्राणों की बाज़ी लगाते हैं।</p>\n          <p><strong>हमारा उत्तरदायित्व:</strong></p>\n          <ul>\n            <li>सैनिकों के अदम्य साहस और बलिदान के प्रति हृदय से सम्मान और कृतज्ञता व्यक्त करना।</li>\n            <li>उनके परिवारों को समाज में सुरक्षा, सम्मान और संबल प्रदान करना।</li>\n            <li>देश के भीतर शांति और सौहार्द बनाए रखना ताकि उनका बलिदान व्यर्थ न जाए।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शून्य से नीचे तापमान व दुर्गम परिस्थितियों का विवरण</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नागरिक के रूप में सम्मान, कृतज्ञता व सहायता के दायित्व</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch14-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch14-q10')\">\n      <div class=\"q-num\">प्रश्न 10</div>\n      <div class=\"q-text\">'कटाओ' को 'भारत का स्विट्ज़रलैंड' क्यों कहा गया है और यह पर्यटन स्थल के रूप में क्यों अधिक प्रसिद्ध नहीं हुआ?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>'भारत का स्विट्ज़रलैंड' कहे जाने का कारण:</strong> कटाओ की बर्फीली वादियाँ, चाँदी के समान चमकते पर्वत शिखर और असीम प्राकृतिक सौन्दर्य यूरोप के स्विट्ज़रलैंड से भी बढ़कर है। लेखिका की स्विट्ज़रलैंड घूम चुकी सहेली 'मणि' ने भी कहा कि कटाओ स्विट्ज़रलैंड से कहीं अधिक खूबसूरत है।</p>\n          <p><strong>प्रसिद्ध न होने का कारण:</strong> कटाओ अभी तक व्यावसायिक पर्यटन (Commercial Tourism) का शिकार नहीं हुआ था। वहाँ न कोई होटल थे, न दुकानें, न विज्ञापनों का शोर। वहाँ तक पहुँचने का मार्ग अत्यंत दुर्गम और जोखिम भरा था। व्यावसायिकता से दूर रहने के कारण ही कटाओ का प्राकृतिक सौंदर्य अपनी मूल और पवित्र अवस्था में सुरक्षित रह सका।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बर्फीले सौंदर्य व स्विट्ज़रलैंड से तुलना का आधार</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">व्यावसायिकता व विज्ञापनों से दूरी तथा प्राकृतिक शुचिता का कारण</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Competency-Based Questions (CBQs) -->\n  <div class=\"cbq-card\">\n    <div class=\"cbq-badge\">CBSE Board Competency-Based Question (योग्यता आधारित प्रश्न)</div>\n    <div class=\"q-text\"><strong>पर्यावरण एवं पर्यटन विश्लेषण (Eco-Tourism Analysis):</strong> 'साना-साना हाथ जोड़ि...' पाठ में लेखिका ने कटाओ की प्राकृतिक शुचिता का श्रेय उसके व्यावसायिक न होने को दिया है। क्या पर्यटन विकास और पर्यावरण संरक्षण साथ-साथ चल सकते हैं? 'सतत पर्यटन' (Sustainable Tourism) के आलोक में अपने विचार प्रस्तुत कीजिए।</div>\n    <div class=\"answer-box\" style=\"margin-top: 15px;\">\n      <div class=\"answer-label\">विशेषज्ञ उत्तर व विश्लेषणात्मक दृष्टिकोण</div>\n      <div class=\"answer-text\">\n        <p><strong>विश्लेषण:</strong> हाँ, पर्यटन और पर्यावरण संरक्षण में संतुलन बनाया जा सकता है बशर्ते 'सतत पर्यटन' के नियमों का कड़ाई से पालन हो:</p>\n        <ul>\n          <li>पहाड़ी क्षेत्रों में प्लास्टिक व गैर-बायोडिग्रेडेबल वस्तुओं पर पूर्ण प्रतिबंध होना चाहिए।</li>\n          <li>पर्यटकों की दैनिक संख्या (Carrying Capacity) सीमित की जाए ताकि पारिस्थितिकी तंत्र पर अत्यधिक दबाव न पड़े।</li>\n          <li>स्थानीय संस्कृति और प्रकृति को क्षति पहुँचाए बिना पर्यावरण-अनुकूल (Eco-friendly) आवास और परिवहन को बढ़ावा दिया जाए।</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n</section>","15":"<section class=\"chapter-section\" id=\"ch15\" data-book=\"kritika\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">15</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">कृतिका भाग-2 — पाठ 3</div>\n      <h2>मैं क्यों लिखता हूँ?</h2>\n      <p>सच्चिदानंद हीरानंद वात्स्यायन 'अज्ञेय' | वैचारिक निबंध — रचना-प्रक्रिया, आंतरिक विवशता, प्रत्यक्ष अनुभव बनाम अनुभूति और हिरोशिमा का साक्षात्कार | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch15-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch15-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">लेखक के अनुसार प्रत्यक्ष अनुभव की अपेक्षा अनुभूति उसके लेखन में कहीं अधिक मदद करती है, क्यों?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखक के अनुसार 'प्रत्यक्ष अनुभव' आँखों के सामने घटित बाह्य घटना होती है, जिसे व्यक्ति केवल अपनी इंद्रियों से देखता है। वह बाहर घटित होकर समाप्त हो सकता है।</p>\n          <p>किंतु 'अनुभूति' मन और आत्मा की गहराई से जुड़ी होती है। अनुभूति में प्रत्यक्ष अनुभव कल्पना और संवेदना के साथ मिलकर आंतरिक सत्य बन जाता है। जब तक कोई घटना अनुभूति का अंग बनकर लेखक के अंतर्मन को उद्वेलित नहीं करती, तब तक कालजयी साहित्य का सृजन संभव नहीं है। अतः अनुभूति लेखन में अधिक सहायक होती है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रत्यक्ष अनुभव (इंद्रियजन्य बाह्य घटना) का स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अनुभूति (संवेदना व अंतर्मन की गहराई) की भूमिका का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch15-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch15-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">लेखक ने अपने आपको हिरोशिमा के विस्फोट का भोक्ता कब और किस तरह महसूस किया?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखक जब जापान की यात्रा पर हिरोशिमा गया, तो उसने अस्पताल में रेडिएशन से पीड़ित लोगों को देखा, किंतु तब तक वह केवल एक बौद्धिक दर्शक था।</p>\n          <p>एक दिन सड़क पर घूमते हुए उसने एक जले हुए पत्थर पर एक मानव की काली छाया देखी। उस दृश्य ने लेखक के मन को झकझोर दिया। उस पत्थर ने गवाही दी कि अणुबम के भीषण विस्फोट के समय कोई व्यक्ति वहाँ खड़ा रहा होगा और रेडियोधर्मी किरणों की प्रचण्ड भाप ने उस व्यक्ति को उड़ा दिया तथा उसकी छाया पत्थर पर स्थायी रूप से झुलस गई। इस दृश्य ने लेखक के हृदय में एक गहरा धमाका किया और वह स्वयं को उस त्रासदी का भोक्ता महसूस करने लगा।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">जले पत्थर पर मानव छाया देखने का प्रसंग</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आंतरिक संवेदना व 'भोक्ता' बनने की मनोवैज्ञानिक अनुभूति</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch15-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch15-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">'मैं क्यों लिखता हूँ?' के आधार पर बताइए कि लेखक को कौन-सी बातें लिखने के लिए प्रेरित करती हैं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखक को लिखने के लिए निम्नलिखित प्रमुख प्रेरणाएँ प्रेरित करती हैं:</p>\n          <ol>\n            <li><strong>आंतरिक विवशता और मुक्ति की चाह:</strong> लेखक के भीतर की बेचैनी और संवेगात्मक दबाव जब तक शब्दों में व्यक्त न हो जाए, तब तक उसे चैन नहीं मिलता। लिखकर ही वह उस आंतरिक दबाव से मुक्त होता है।</li>\n            <li><strong>स्वयं को जानना:</strong> लेखक यह जानने के लिए लिखता है कि वास्तव में वह क्यों लिखता है और उसके भीतर क्या घटित हो रहा है।</li>\n            <li><strong>बाहरी दबाव:</strong> संपादकों का आग्रह, प्रकाशकों का तकाज़ा और आर्थिक आवश्यकताएँ भी कभी-कभी लिखने का माध्यम बनती हैं।</li>\n          </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आंतरिक विवशता व आत्मानुभूति का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बाहरी दबावों (संपादक, आर्थिक) की भूमिका</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch15-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch15-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">कुछ रचनाकारों के लिए आत्मानुभूति ही लेखन का मूल कारण बनती है। क्या बाहरी दबाव भी लेखन का कारण हो सकते हैं? उदाहरण सहित समझाइए।</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>हाँ, बाहरी दबाव भी अनेक बार लेखन का तात्कालिक कारण बनते हैं। इन बाहरी दबावों में संपादकों का आग्रह, प्रकाशक का अनुबंध, पाठकों की माँग और आर्थिक आवश्यकताएँ प्रमुख हैं।</p>\n          <p>किंतु सच्चा और श्रेष्ठ लेखक वही है जो बाहरी दबाव को केवल एक निमित्त या अवसर मानता है और रचना तभी करता है जब वह बाह्य दबाव उसके अंतर्मन की अनुभूति से एकाकार हो जाए। उदाहरण के लिए, प्रेमचंद जी ने कई कहानियाँ पत्रिकाओं की माँग पर लिखीं, किंतु उनमें उनकी वास्तविक सामाजिक वेदना ही मुखरित हुई।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बाहरी दबावों के प्रकारों का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सच्चे लेखक द्वारा बाह्य दबाव को अंतर्मन से जोड़ने का तर्क</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch15-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch15-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">हिरोशिमा पर लिखी कविता लेखक के आंतरिक व बाह्य दोनों दबाव का परिणाम है, यह आप कैसे कह सकते हैं?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>हिरोशिमा पर लिखी कविता बाह्य और आंतरिक दोनों दबावों के अद्भुत समन्वय का परिणाम है:</p>\n          <ul>\n            <li><strong>बाह्य दबाव:</strong> लेखक ने हिरोशिमा में अणुबम की भीषण विभीषिका के प्रत्यक्ष प्रमाण देखे, विकिरण से पीड़ित लोगों को देखा और झुलसे हुए पत्थर पर मानव छाया देखी। यह प्रत्यक्ष बाह्य यथार्थ एक बाह्य दबाव के रूप में उपस्थित था।</li>\n            <li><strong>आंतरिक दबाव:</strong> पत्थर पर अंकित छाया को देखकर लेखक के भीतर संवेदना का विस्फोट हुआ। वह केवल एक दर्शक न रहकर उस त्रासदी का प्रत्यक्ष भोक्ता बन गया। जब वह भारत लौटा और रेलगाड़ी में यात्रा कर रहा था, तब उस आंतरिक विवशता और बेचैनी से मुक्ति पाने के लिए उसने यह कविता लिखी।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बाह्य दबाव (प्रत्यक्ष खंडहर व त्रासदी का दृश्य)</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आंतरिक दबाव (संवेदना का अंतर्द्वंद्व व मुक्ति की छटपटाहट)</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch15-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch15-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">विज्ञान का दुरुपयोग कहाँ-कहाँ हो रहा है और इसे रोकने के लिए एक नागरिक के रूप में आपकी क्या भूमिका हो सकती है?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>विज्ञान का दुरुपयोग:</strong> आज विज्ञान का दुरुपयोग परमाणु व जैविक हथियारों के निर्माण, साइबर अपराध, प्रकृति के अत्यधिक दोहन, प्लास्टिक प्रदूषण तथा भ्रूण हत्या जैसी अमानवीय प्रवृत्तियों में हो रहा है। हिरोशिमा और नागासाकी पर परमाणु हमला इसका सबसे क्रूर उदाहरण है।</p>\n          <p><strong>एक जागरूक नागरिक के रूप में भूमिका:</strong></p>\n          <ul>\n            <li>वैज्ञानिक अनुसंधानों का प्रयोग मानव कल्याण, चिकित्सा और शांति के लिए करने की वकालत करना।</li>\n            <li>इंटरनेट और डिजिटल तकनीक का प्रयोग नैतिक मर्यादाओं और रचनात्मक कार्यों में करना।</li>\n            <li>पर्यावरण संरक्षण के प्रति सजग रहना और विनाशकारी हथियारों व प्रदूषण के विरुद्ध जन-जागरूकता फैलाना।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">विज्ञान के समकालीन दुरुपयोगों का यथार्थवादी उल्लेख</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नागरिक के कर्तव्य, नैतिक चेतना व समाधानपरक उपाय</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Competency-Based Questions (CBQs) -->\n  <div class=\"cbq-card\">\n    <div class=\"cbq-badge\">CBSE Board Competency-Based Question (योग्यता आधारित प्रश्न)</div>\n    <div class=\"q-text\"><strong>रचनात्मक एवं नैतिक मूल्यांकन (Creative & Ethical Evaluation):</strong> 'मैं क्यों लिखता हूँ?' पाठ के आधार पर स्पष्ट कीजिए कि एक साहित्यकार और एक वैज्ञानिक के दायित्व में क्या समानता और अंतर है? आज के युग में विज्ञान और मानवीय संवेदनाओं का समन्वय क्यों अपरिहार्य है?</div>\n    <div class=\"answer-box\" style=\"margin-top: 15px;\">\n      <div class=\"answer-label\">विशेषज्ञ उत्तर व विश्लेषणात्मक दृष्टिकोण</div>\n      <div class=\"answer-text\">\n        <p><strong>समानता:</strong> दोनों ही सत्य की खोज करते हैं और मानव जीवन को उन्नत बनाने का प्रयास करते हैं।</p>\n        <p><strong>अंतर:</strong> वैज्ञानिक बाह्य जगत के नियमों और पदार्थों का विश्लेषण करता है, जबकि साहित्यकार अंतर्जगत की संवेदनाओं, मूल्यों और मानवीय अनुभूतियों को वाणी देता है। यदि विज्ञान के साथ मानवीय संवेदना नहीं जुड़ी होगी, तो वह हिरोशिमा जैसा संहारक बन जाएगा। अतः विज्ञान की शक्ति को संवेदना का मार्गदर्शन मिलना अनिवार्य है।</p>\n      </div>\n    </div>\n  </div>\n</section>","16":"<section class=\"chapter-section\" id=\"ch16\" data-book=\"sparsh-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">16</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (गद्य खंड) — पाठ 1</div>\n      <h2>बड़े भाई साहब</h2>\n      <p>प्रेमचंद | मनोवैज्ञानिक कहानी — शिक्षा प्रणाली पर व्यंग्य, रटंत विद्या बनाम व्यावहारिक अनुभव और भ्रातृ-प्रेम | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch16-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch16-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">छोटे भाई ने अपनी पढ़ाई और खेलकूद के बीच किस प्रकार का टाइम-टेबल बनाया और उसका क्या परिणाम हुआ?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>टाइम-टेबल का निर्माण:</strong> बड़े भाई साहब की डाँट-फटकार सुनकर छोटे भाई ने पढ़ाई के लिए एक अत्यंत कठोर समय-सारणी बनाई, जिसमें सुबह 6 बजे से रात 11 बजे तक हर विषय (अंग्रेजी, गणित, इतिहास आदि) के लिए समय निर्धारित था। किंतु उस टाइम-टेबल में खेलकूद के लिए एक मिनट का भी समय नहीं रखा गया था।</p>\n          <p><strong>परिणाम:</strong> टाइम-टेबल बनाना अलग बात है और उस पर अमल करना दूसरी। खेल के मैदान की सुखद हरियाली, फुटबॉल की उछल-कूद और कबड्डी के दाँव-पेंच उसे बरबस खींच ले जाते थे। पहले ही दिन से टाइम-टेबल की धज्जियाँ उड़ने लगीं और वह उसका पालन नहीं कर सका।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कठोर समय-सारणी व खेल के अभाव का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मैदान के आकर्षण व क्रियान्वयन की विफलता का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch16-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch16-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">बड़े भाई साहब दिमाग को आराम देने के लिए क्या-क्या करते थे?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>बड़े भाई साहब दिन-रात लगातार पढ़ते रहते थे। जब उनका दिमाग थक जाता था, तो वे अपनी कॉपियों और किताबों के हाशियों पर चिड़ियों, कुत्तों और बिल्लियों की तस्वीरें बनाते थे। कभी-कभी वे एक ही शब्द या नाम को दस-बीस बार लिखते थे या ऐसे बेमेल शेरों और तुकबंदियों की रचना करते थे जिनका कोई सिर-पैर नहीं होता था।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कॉपियों पर जानवरों के चित्र बनाना</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">निरर्थक शब्दों की तुकबंदियाँ व पुनरावृत्ति</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch16-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch16-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">बड़े भाई साहब की डाँट-फटकार अगर न मिलती, तो क्या छोटा भाई कक्षा में अव्वल आता? अपने विचार दीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>हमारे विचार से यदि बड़े भाई साहब की निरंतर निगरानी और डाँट-फटकार न होती, तो छोटा भाई कभी भी कक्षा में प्रथम नहीं आ पाता।</p>\n          <p>छोटा भाई स्वभाव से अत्यंत खेलप्रिय और मौज-मस्ती पसंद करने वाला था। बड़े भाई का कठोर अनुशासन और नैतिक डर ही तलवार की भाँति उसके सिर पर लटकता रहता था, जिसके कारण वह खेलकूद से समय चुराकर थोड़ा-बहुत अवश्य पढ़ लेता था। उसकी प्रतिभा उस डर और संयम के कारण ही निखर सकी।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">छोटे भाई के खेलप्रिय स्वभाव का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बड़े भाई के भय व अनुशासन द्वारा सफलता की व्याख्या</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch16-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch16-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">इस पाठ में लेखक ने समूची शिक्षा प्रणाली के किन-किन दोषों पर व्यंग्य किया है?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>प्रेमचंद जी ने तत्कालीन अंग्रेजी औपनिवेशिक शिक्षा प्रणाली की निम्नलिखित विसंगतियों पर तीखा कटाक्ष किया है:</p>\n          <ul>\n            <li><strong>रटंत विद्या को प्रोत्साहन:</strong> परीक्षा प्रणाली केवल रटने पर आधारित है, वास्तविक समझ और बुद्धि के विकास पर नहीं। आठ-आठ हेनरी और विलियम के नाम याद करने पर विवश किया जाता है।</li>\n            <li><strong>अव्यावहारिक पाठ्यक्रम:</strong> ज्यामिति में 'अ ब ज' की जगह 'अ ज ब' लिख देने पर शून्य अंक दे देना विद्यार्थियों के मानसिक शोषण का प्रमाण है।</li>\n            <li><strong>जीवनोपयोगी ज्ञान का अभाव:</strong> 'समय की पाबंदी' पर चार पन्ने का निबंध लिखने का आदेश देकर कहा जाता है कि संक्षेप में लिखो, जो अपने आप में हास्यास्पद अंतर्विरोध है। यह शिक्षा व्यक्ति को केवल डिग्रियाँ देती है, जीवन जीने की व्यावहारिक बुद्धि नहीं।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">रटंत प्रणाली व इतिहास-ज्यामिति के अव्यावहारिक उदाहरण</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">निबंध लेखन के अंतर्विरोध व बौद्धिक शोषण पर व्यंग्य</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch16-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch16-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">बड़े भाई साहब ने जिंदगी के अनुभव और किताबी ज्ञान में से किसे और क्यों महत्वपूर्ण कहा है?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>बड़े भाई साहब ने किताबी ज्ञान की तुलना में ज़िंदगी के तजुर्बे और व्यावहारिक अनुभव को कहीं अधिक श्रेष्ठ और महत्त्वपूर्ण माना है:</p>\n          <ul>\n            <li><strong>अम्मा और दादा का उदाहरण:</strong> हमारी अम्मा ने कोई दर्जा पास नहीं किया और दादा ने भी केवल पाँचवीं-छठी पढ़ी है, किंतु वे दुनिया की समझ में हमसे कहीं आगे हैं। यदि हम बीमार पड़ जाएँ, तो दादा को तार भेजने के बजाय घर में ही उचित प्रबंध कर लेंगे।</li>\n            <li><strong>हेडमास्टर साहब की माँ:</strong> एम.ए. पास हेडमास्टर साहब जब घर का खर्च चलाते थे, तो महीने के अंत में कर्ज लेना पड़ता था। जब उनकी अनपढ़ माँ ने प्रबंध संभाला, तो घर में बरकत आ गई।</li>\n            <li><strong>निष्कर्ष:</strong> किताबी ज्ञान केवल सूचनाएँ देता है, जबकि ज़िंदगी का अनुभव मनुष्य को जीवन जीने, संकटों का सामना करने और सही निर्णय लेने की व्यावहारिक सूझबूझ देता है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अम्मा, दादा व हेडमास्टर साहब के सटीक दृष्टांत</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">जीवन अनुभव की श्रेष्ठता व व्यावहारिक तर्क</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch16-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch16-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">बड़े भाई की स्वाभाविक विशेषताएँ क्या थीं? पाठ के आधार पर चरित्र-चित्रण कीजिए।</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>पाठ के आधार पर बड़े भाई साहब के चरित्र की प्रमुख विशेषताएँ निम्नलिखित हैं:</p>\n          <ul>\n            <li><strong>परिश्रमी व गंभीर:</strong> वे दिन-रात किताबों में आँखें गड़ाए रहते थे और कभी खेलकूद में समय बर्बाद नहीं करते थे।</li>\n            <li><strong>कर्तव्यपरायण व आदर्शवादी:</strong> वे स्वयं को बड़े भाई के रूप में एक आदर्श मिसाल बनाना चाहते थे, इसलिए अपनी बाल-सुलभ इच्छाओं का बलिदान कर देते थे।</li>\n            <li><strong>स्नेही व संरक्षक:</strong> ऊपर से कठोर और डांटने वाले दिखाई देने पर भी उनके दिल में छोटे भाई के प्रति अगाध प्रेम और उसकी भलाई की गहरी चिंता थी।</li>\n            <li><strong>उपदेश-कला में निपुण:</strong> वे सूक्ति-बाण चलाने और मनोवैज्ञानिक तर्क देकर छोटे भाई को अनुशासन में रखने में प्रवीण थे।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">परिश्रम, कर्तव्यनिष्ठा व बाल-इच्छाओं के त्याग का उल्लेख</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भ्रातृ-स्नेह, उपदेश-कला व आंतरिक कोमलता का विश्लेषण</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch16-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch16-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">'बुनियाद ही पुख्ता न हो तो मकान पायेदार कैसे बने?'—इस कथन का आशय स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>आशय:</strong> बड़े भाई साहब का मानना था कि जिस प्रकार किसी मजबूत और टिकाऊ मकान के निर्माण के लिए उसकी नींव (बुनियाद) का सुदृढ़ होना अनिवार्य है, उसी प्रकार जीवन में उच्च ज्ञान और सफलता प्राप्त करने के लिए प्रारंभिक शिक्षा का आधार ठोस होना चाहिए।</p>\n          <p>यही कारण था कि वे हर कक्षा में एक साल के बजाय दो-तीन साल लगाते थे ताकि उनकी शिक्षा की नींव पुख्ता बन सके। यद्यपि यह उनका आत्मसंतोषी तर्क था, किंतु बात मूलभूत रूप से सत्य थी।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नींव और इमारत के रूपक का स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रारंभिक शिक्षा की सुदृढ़ता के संदर्भ में निहितार्थ</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch16-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch16-q8')\">\n      <div class=\"q-num\">प्रश्न 8</div>\n      <div class=\"q-text\">पाठ के अंत में बड़े भाई साहब ने छोटे भाई के पतंग लूटने पर क्या प्रतिक्रिया दी और उनका क्या बड़प्पन प्रकट हुआ?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>पाठ के अंत में जब एक कटी हुई पतंग उनके ऊपर से गुज़री, तो लंबे कद के बड़े भाई साहब ने उछलकर उसकी डोर पकड़ ली और हॉस्टल की ओर बेतहाशा दौड़ पड़े। छोटा भाई भी उनके पीछे-पीछे दौड़ रहा था।</p>\n          <p>इस घटना से सिद्ध हुआ कि बड़े भाई साहब भी मूलतः एक किशोर बालक ही थे, जिनका मन भी पतंग उड़ाने और खेलने को ललचाता था। किंतु केवल छोटे भाई को राह पर रखने और अपने बड़े होने की मर्यादा निभाने के लिए वे अपनी इच्छाओं को दबाए रखते थे। डोर पकड़कर दौड़ने में उनका बाल-सुलभ रूप प्रकट हुआ और उनका आत्म-त्याग तथा बड़प्पन पूरी तरह उजागर हो गया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पतंग की डोर पकड़कर दौड़ने की घटना का चित्रण</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दबी हुई बाल-सुलभ इच्छाओं व बड़प्पन के त्याग का प्रकटीकरण</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Competency-Based Questions (CBQs) -->\n  <div class=\"cbq-card\">\n    <div class=\"cbq-badge\">CBSE Board Competency-Based Question (योग्यता आधारित प्रश्न)</div>\n    <div class=\"q-text\"><strong>मनोवैज्ञानिक एवं शैक्षणिक विश्लेषण (Psychological & Pedagogical Analysis):</strong> 'बड़े भाई साहब' पाठ में दो परस्पर विरोधी शैक्षणिक दृष्टियों (रटंत किताबी ज्ञान बनाम सहज खेलप्रियता) का द्वंद्व है। राष्ट्रीय शिक्षा नीति (NEP 2020) के संदर्भ में समीक्षा कीजिए कि खेल-आधारित और अनुभवात्मक अधिगम (Experiential Learning) किस प्रकार इन दोनों के बीच संतुलन स्थापित कर सकता है?</div>\n    <div class=\"answer-box\" style=\"margin-top: 15px;\">\n      <div class=\"answer-label\">विशेषज्ञ उत्तर व विश्लेषणात्मक दृष्टिकोण</div>\n      <div class=\"answer-text\">\n        <p><strong>विश्लेषण:</strong> बड़े भाई साहब जहाँ कठोर रटंत और अव्यावहारिक बोझिल पढ़ाई के शिकार थे, वहीं छोटा भाई स्वाभाविक रुचि और खेलकूद के माध्यम से भी मानसिक रूप से सजग था।</p>\n        <p><strong>NEP 2020 के आलोक में संतुलन:</strong> राष्ट्रीय शिक्षा नीति 2020 रटंत अधिगम का विरोध करती है और खेल-कूद व व्यावहारिक गतिविधियों के समन्वय पर बल देती है। जब पाठ्यक्रम में शारीरिक विकास, खेल और वास्तविक जीवन के अनुभवों को समाहित किया जाता है, तो विद्यार्थी बिना किसी मानसिक तनाव के सर्वांगीण विकास प्राप्त करते हैं।</p>\n      </div>\n    </div>\n  </div>\n</section>","17":"<section class=\"chapter-section\" id=\"ch17\" data-book=\"sparsh-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">17</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (गद्य खंड) — पाठ 2</div>\n      <h2>डायरी का एक पन्ना</h2>\n      <p>सीताराम सेकसरिया | ऐतिहासिक संस्मरण/डायरी — 26 जनवरी 1931, कोलकाता में स्वतंत्रता दिवस, पुलिस दमन, स्त्री समाज की वीरता और जन-आंदोलन | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch17-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch17-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">26 जनवरी 1931 के दिन को अमर बनाने के लिए कोलकाता के लोगों ने क्या-क्या तैयारियाँ की थीं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>26 जनवरी 1931 को प्रथम स्वाधीनता दिवस की पहली वर्षगाँठ मनाने के लिए कोलकाता वासियों ने अभूतपूर्व तैयारियाँ की थीं:</p>\n          <ul>\n            <li>पूरे शहर में प्रचार कार्य पर दो हज़ार रुपये खर्च किए गए थे और घर-घर जाकर लोगों को प्रेरित किया गया था।</li>\n            <li>शहर के अधिकांश मकानों, बाज़ारों और सार्वजनिक स्थलों पर राष्ट्रीय तिरंगा झंडा फहराया गया था।</li>\n            <li>मारवाड़ी बालिका विद्यालय की छात्राओं ने अपने विद्यालय में झंडोत्सव मनाया।</li>\n            <li>विभिन्न स्थानों से विशाल जुलूस निकालने और शाम 4:24 बजे मॉन्युमेंट के नीचे झंडा फहराने व स्वतंत्रता की प्रतिज्ञा पढ़ने की पूरी योजना बनाई गई थी।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रचार, ध्वजारोहण व सजावट का विवरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मॉन्युमेंट सभा व जुलूसों की पूर्व योजना का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch17-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch17-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">सुभाष बाबू के जुलूस में स्त्री समाज की क्या भूमिका थी?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>सुभाष चंद्र बोस के आंदोलन और 26 जनवरी के उत्सव में स्त्री समाज की भूमिका अत्यंत गौरवशाली और साहसिक थी:</p>\n          <ul>\n            <li>स्त्रियों ने पुलिस की पाबंदियों और लाठीचार्ज की परवाह किए बिना बड़ी संख्या में जुलूस निकाले।</li>\n            <li>मॉन्युमेंट की सीढ़ियों पर चढ़कर महिलाओं ने राष्ट्रीय ध्वज फहराया और स्वतंत्रता की घोषणा पढ़ी।</li>\n            <li>लाठीचार्ज के भीषण प्रहार झेलते हुए भी वे डटी रहीं। अंततः लगभग 105 महिलाओं को गिरफ्तार करके लालबाज़ार जेल भेजा गया, जो तत्कालीन समय में एक ऐतिहासिक मिसाल थी।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">जुलूस, ध्वजारोहण व लाठीचार्ज सहने का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">105 महिलाओं की गिरफ्तारी व ऐतिहासिक भूमिका</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch17-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch17-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">पुलिस कमिश्नर के नोटिस और कौंसिल के नोटिस में क्या अंतर था?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>दोनों नोटिसों में सीधा टकराव और विरोधाभास था:</p>\n          <ul>\n            <li><strong>पुलिस कमिश्नर का नोटिस:</strong> कमिश्नर ने कानूनी धाराओं के तहत आदेश निकाला कि शहर में किसी भी प्रकार की सभा या जुलूस निकालना गैर-कानूनी है। जो भी व्यक्ति इसमें भाग लेगा, उसे दोषी मानकर गिरफ्तार किया जाएगा।</li>\n            <li><strong>कौंसिल का नोटिस:</strong> प्रांतीय कौंसिल ने नागरिकों से खुला आह्वान किया कि 26 जनवरी को शाम ठीक 4:24 बजे मॉन्युमेंट के नीचे राष्ट्रीय झंडा फहराया जाएगा और स्वतंत्रता की प्रतिज्ञा पढ़ी जाएगी। सभी नागरिक इसमें बढ़-चढ़कर भाग लें।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पुलिस कमिश्नर के निषेधाज्ञा आदेश का विवरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कौंसिल के सभा व ध्वजारोहण के खुले आह्वान का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch17-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch17-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">धर्मतल्ले के मोड़ पर आकर जुलूस क्यों टूट गया और वहाँ क्या घटना घटी?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>धर्मतल्ले के मोड़ पर पुलिस ने जुलूस को रोक लिया और निहत्थे नागरिकों पर बर्बरतापूर्वक लाठीचार्ज शुरू कर दिया।</p>\n          <p>पुलिस की भीषण लाठियों के प्रहार से अनेक लोग घायल होकर लहूलुहान हो गए और वहीं गिर पड़े। इस भीषण प्रहार के कारण जुलूस का मुख्य भाग टूट गया। किंतु उसी समय 50-60 स्त्रियाँ वहीं सड़क पर बैठ गईं। पुलिस ने उन्हें घेरा और बाद में लालबाज़ार जेल भेज दिया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पुलिस के बर्बर लाठीचार्ज व घायलों का विवरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्त्रियों का सड़क पर धरना व गिरफ्तारी</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch17-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch17-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">डॉ. दासगुप्ता और बृजलाल गोयनका की इस आंदोलन में क्या भूमिका थी?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>डॉ. दासगुप्ता:</strong> वे घायलों की मरहम-पट्टी और चिकित्सा की देखरेख कर रहे थे तथा साथ ही घायलों के फोटो खिंचवा रहे थे, ताकि ब्रिटिश पुलिस की बर्बरता को पूरे देश और दुनिया के सामने उजागर किया जा सके।</p>\n          <p><strong>बृजलाल गोयनका:</strong> वे मारवाड़ी समुदाय के सक्रिय कार्यकर्ता थे। उन्होंने झंडा लेकर वंदे मातरम् बोलते हुए मॉन्युमेंट की ओर दौड़ लगाई। पुलिस ने उन्हें बुरी तरह पीटा और अंततः गिरफ्तार कर लिया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">डॉ. दासगुप्ता की चिकित्सीय व प्रचारक भूमिका</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बृजलाल गोयनका का ध्वज लेकर संघर्ष व बलिदान</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch17-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch17-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">'यह कलंक आज बहुत अंश में धुल गया'—लेखक के इस कथन का क्या आशय है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>आशय:</strong> कोलकाता के विषय में देश भर में यह अपयश या बदनामी फैली हुई थी कि यहाँ के लोग स्वतंत्रता संग्राम में सक्रिय योगदान नहीं दे रहे हैं और यहाँ आंदोलन का कोई विशेष काम नहीं हो रहा है।</p>\n          <p>किंतु 26 जनवरी 1931 को जिस प्रकार कोलकाता के पुरुषों, युवाओं और विशेषकर स्त्रियों ने अंग्रेजी पुलिस की लाठियों और गोलियों की परवाह न करते हुए ऐतिहासिक प्रदर्शन किया, जेलें भरीं और तिरंगा फहराया, उससे यह सिद्ध हो गया कि कोलकाता भी आज़ादी की लड़ाई में किसी से पीछे नहीं है। इस प्रकार वह कलंक धुल गया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कोलकाता पर लगे अपयश (निष्क्रियता) का संदर्भ</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">26 जनवरी के अभूतपूर्व जन-उभार द्वारा कलंक धुलने का तर्क</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch17-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch17-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">पाठ के आधार पर स्पष्ट कीजिए कि 26 जनवरी 1931 का दिन कोलकाता के इतिहास में अभूतपूर्व क्यों था?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>26 जनवरी 1931 का दिन कोलकाता के इतिहास में निम्नलिखित कारणों से अभूतपूर्व और अविस्मरणीय था:</p>\n          <ul>\n            <li><strong>जन-साधारण की व्यापक सहभागिता:</strong> पहली बार इतने बड़े पैमाने पर आम नागरिकों, व्यापारियों, छात्रों और महिलाओं ने खुलकर सरकारी निषेधाज्ञा को चुनौती दी।</li>\n            <li><strong>सुभाष चंद्र बोस का ओजस्वी नेतृत्व:</strong> सुभाष बाबू पुलिस की भीषण लाठियों के प्रहार सहते हुए भी 'वंदे मातरम्' बोलते हुए आगे बढ़ते रहे।</li>\n            <li><strong>नारी शक्ति का अभूतपूर्व शौर्य:</strong> इतनी बड़ी संख्या में स्त्रियों का लाठीचार्ज का सामना करना, मॉन्युमेंट पर तिरंगा फहराना और सामूहिक गिरफ्तारी देना इससे पहले कभी नहीं देखा गया था। इसने राष्ट्रीय आंदोलन को नई ऊर्जा प्रदान की।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नागरिक अवज्ञा, सरकारी आदेश का उल्लंघन व जन-उभार</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्त्री-शक्ति के योगदान व राष्ट्रीय चेतना के प्रसार का विवेचन</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Competency-Based Questions (CBQs) -->\n  <div class=\"cbq-card\">\n    <div class=\"cbq-badge\">CBSE Board Competency-Based Question (योग्यता आधारित प्रश्न)</div>\n    <div class=\"q-text\"><strong>ऐतिहासिक प्रलेखीकरण विश्लेषण (Historical Documentation Analysis):</strong> 'डायरी का एक पन्ना' पाठ यह सिद्ध करता है कि समकालीन घटनाओं का व्यक्तिगत डायरी में अंकन भविष्य के लिए प्रामाणिक इतिहास बन जाता है। इस कथन की समीक्षा करते हुए स्पष्ट कीजिए कि आज के डिजिटल युग में नागरिक प्रलेखीकरण (Citizen Journalism) की क्या प्रासंगिकता है?</div>\n    <div class=\"answer-box\" style=\"margin-top: 15px;\">\n      <div class=\"answer-label\">विशेषज्ञ उत्तर व विश्लेषणात्मक दृष्टिकोण</div>\n      <div class=\"answer-text\">\n        <p><strong>समीक्षा:</strong> सीताराम सेकसरिया जी ने जो कुछ अपनी आँखों से देखा, उसे निष्पक्षता और यथार्थ के साथ अपनी डायरी में दर्ज किया। यही संस्मरण आज स्वतंत्रता संग्राम के अनछुए पन्नों का प्रामाणिक दस्तावेज़ बन चुका है।</p>\n        <p><strong>आधुनिक संदर्भ:</strong> आज सोशल मीडिया और स्मार्टफोन के युग में प्रत्येक नागरिक किसी भी सामाजिक अन्याय या घटना का प्रत्यक्षदर्शी बनकर उसे प्रलेखित कर सकता है। बशर्ते उसमें सेकसरिया जी जैसी सत्यनिष्ठा और निष्पक्षता हो, यह आधुनिक नागरिक पत्रकारिता लोकतंत्र की सबसे बड़ी प्रहरी बन सकती है।</p>\n      </div>\n    </div>\n  </div>\n</section>","18":"<section class=\"chapter-section\" id=\"ch18\" data-book=\"sparsh-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">18</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (गद्य खंड) — पाठ 3</div>\n      <h2>तताँरा-वामीरो कथा</h2>\n      <p>लीलाधर मंडलोई | अंडमान-निकोबार द्वीपसमूह की लोककथा — रूढ़िवादी सामाजिक बंधनों का विरोध, पवित्र प्रेम और आत्म-बलिदान | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch18-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch18-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">तताँरा की तलवार के बारे में लोगों का क्या विश्वास था?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>तताँरा अपनी कमर में सदैव लकड़ी की एक तलवार बाँधे रहता था। यद्यपि वह लकड़ी की तलवार थी, किंतु लोगों का यह दृढ़ विश्वास था कि उस तलवार में कोई विलक्षण दैवीय शक्ति है। तताँरा कभी दूसरों के सामने उसका उपयोग नहीं करता था, फिर भी उसके साहसिक कारनामों के कारण लोग उस तलवार को चमत्कारी मानते थे।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">लकड़ी की तलवार का संदर्भ</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दैवीय/चमत्कारी शक्ति के जन-विश्वास का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch18-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch18-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">वामीरो ने तताँरा को बेरुखी से क्या जवाब दिया और बाद में उसके मन में क्या परिवर्तन आया?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>प्रारंभिक बेरुखी:</strong> जब तताँरा ने वामीरो से गाना जारी रखने का आग्रह किया, तो उसने तल्खी से कहा कि \"पहले बताओ तुम कौन हो और मुझे इस तरह क्यों घूर रहे हो? अपने गाँव की रीति जानते हुए भी किसी दूसरे गाँव के युवक के प्रश्नों का उत्तर देना मैं उचित नहीं समझती।\"</p>\n          <p><strong>मनोवैज्ञानिक परिवर्तन:</strong> किंतु जब उसने तताँरा का सौम्य, विनम्र और विवश चेहरा देखा तथा उसका नाम सुना, तो उसका हृदय पिघल गया। तताँरा का व्यक्तित्व उसके अंतर्मन में समा गया और वह भी उसके प्रेम में व्याकुल होकर अगले दिन शाम को समुद्र तट पर मिलने को विवश हो गई।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">रूढ़िवादी परंपरा के आधार पर वामीरो की तल्खी का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तताँरा के सौम्य रूप से प्रेम में बदलने की प्रक्रिया</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch18-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch18-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">तताँरा-वामीरो के गाँव की क्या प्राचीन परंपरा थी और वह उनके प्रेम में किस प्रकार बाधक बनी?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>निकोबार के गाँवों की यह कठोर और प्राचीन परंपरा थी कि विवाह केवल उसी गाँव के युवक-युवती के मध्य हो सकता था। किसी अन्य गाँव के लड़के या लड़की से वैवाहिक संबंध जोड़ना सर्वथा वर्जित और सामाजिक अपराध माना जाता था।</p>\n          <p>तताँरा 'पासा' गाँव का रहने वाला था जबकि वामीरो 'लपाती' गाँव की थी। दोनों एक-दूसरे से अगाध प्रेम करते थे, किंतु इस संकीर्ण व अमानवीय परंपरा के कारण उनका विवाह असंभव हो गया और समाज ने उन्हें अपमानित किया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">समान गाँव में ही विवाह की अनिवार्य रूढ़ि का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पासा और लपाती गाँव के भेद द्वारा प्रेम में बाधा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch18-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch18-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">पशु-पर्व के दिन मेले में क्या घटना घटी जिसके कारण तताँरा को अत्यधिक क्रोध आ गया?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>पशु-पर्व के मेले में वामीरो तताँरा को देखकर फूट-फूटकर रोने लगी। अपनी बेटी को एक पराये गाँव के युवक के सामने रोते देखकर वामीरो की माँ आगबबूला हो गई।</p>\n          <p>उसने भरी सभा में तताँरा को अत्यंत अपमानित किया और उसे अपशब्द कहे। पूरे गाँव के लोग तताँरा के विरुद्ध हो गए और उसका उपहास उड़ाने लगे। गाँव की संकीर्णता, अपनी बेबसी और वामीरो के आँसुओं को देखकर तताँरा का धैर्य टूट गया और उसे असहनीय क्रोध आ गया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वामीरो की माँ द्वारा सार्वजनिक अपमान व कटु वचनों का प्रसंग</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बेबसी व सामाजिक क्रूरता से उत्पन्न क्रोध का निरूपण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch18-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch18-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">तताँरा ने क्रोध में आकर क्या किया और उसका निकोबार द्वीपसमूह पर क्या परिणाम हुआ?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>तताँरा का कदम:</strong> प्रचंड क्रोध और निराशा में तताँरा ने अपनी कमर से लकड़ी की तलवार निकाली और पूरी शक्ति से उसे धरती में घोंप दिया। फिर उसने तलवार को ज़मीन पर खींचते हुए आगे बढ़ना शुरू कर दिया, जिससे धरती में एक विशाल दरार पड़ती चली गई और चीत्कार गूँज उठी।</p>\n          <p><strong>द्वीपसमूह पर परिणाम:</strong> देखते ही देखते पूरा द्वीप दो टुकड़ों में विभक्त हो गया। एक हिस्सा समुद्र में बहने लगा जिस पर तताँरा फँस गया और लहरों में विलीन हो गया। दूसरा हिस्सा स्थिर रहा। लोकमान्यता के अनुसार आज जो 'कार-निकोबार' और 'लिटिल अंडमान' दो अलग द्वीप हैं, वे पहले एक ही थे और तताँरा की तलवार से ही अलग हुए।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तलवार धरती में घोंपकर चीरने की नाटकीय घटना</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">द्वीप के दो भागों में बँटने (कार-निकोबार व लिटिल अंडमान) का भौगोलिक संदर्भ</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch18-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch18-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">तताँरा-वामीरो के त्याग और बलिदान ने समाज में क्या युगांतरकारी परिवर्तन लाया?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>तताँरा और वामीरो की मृत्यु एक अत्यंत कारुणिक और हृदयविदारक घटना थी, जिसने निकोबार समाज की सोई हुई अंतरात्मा को झकझोर कर जगा दिया:</p>\n          <ul>\n            <li><strong>रूढ़िवादी परंपरा का अंत:</strong> समाज के प्रबुद्ध लोगों को यह अहसास हुआ कि जो परंपराएँ मनुष्य के प्रेम, सुख और जीवन की रक्षा नहीं कर सकतीं, उन्हें ढोना व्यर्थ है।</li>\n            <li><strong>वैवाहिक संबंधों में उदारता:</strong> दोनों प्रेमियों के आत्म-बलिदान के बाद निकोबारियों ने अपनी सदियों पुरानी संकीर्ण वैवाहिक परंपरा को हमेशा के लिए समाप्त कर दिया। इसके बाद से दूसरे गाँवों में भी वैवाहिक संबंध स्वीकार किए जाने लगे।</li>\n            <li><strong>शिक्षा:</strong> उनका बलिदान यह अमर संदेश देता है कि जब रूढ़ियाँ बंधन बन जाएँ, तो समाज के हित में उनका टूटना ही प्रगति का मार्ग प्रशस्त करता है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">समाज की अंतरात्मा का जाग्रत होना व रूढ़ि का टूटना</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अन्य गाँवों में वैवाहिक संबंध स्वीकारने का युगांतरकारी परिवर्तन</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Competency-Based Questions (CBQs) -->\n  <div class=\"cbq-card\">\n    <div class=\"cbq-badge\">CBSE Board Competency-Based Question (योग्यता आधारित प्रश्न)</div>\n    <div class=\"q-text\"><strong>सामाजिक रूढ़ि-भंजन विश्लेषण (Societal Reform Analysis):</strong> 'जब कोई परंपरा समाज के विकास और मानवीय संवेदनाओं के मार्ग में अवरोध बन जाए, तो उसका टूटना ही श्रेयस्कर है।' 'तताँरा-वामीरो कथा' के आधार पर इस कथन की समकालीन भारतीय समाज (जैसे जातिगत व संकीर्ण विवाह बंधन) के संदर्भ में विवेचना कीजिए।</div>\n    <div class=\"answer-box\" style=\"margin-top: 15px;\">\n      <div class=\"answer-label\">विशेषज्ञ उत्तर व विश्लेषणात्मक दृष्टिकोण</div>\n      <div class=\"answer-text\">\n        <p><strong>विवेचना:</strong> परंपराएँ समाज को संगठित करने के लिए बनाई जाती हैं, विनाश करने के लिए नहीं। पाठ में लपाती और पासा गाँव की हठधर्मिता ने दो निर्दोष प्रेमियों के प्राण ले लिए, जिसके बाद ही समाज को अपनी गलती का बोध हुआ।</p>\n        <p><strong>समकालीन संदर्भ:</strong> आज भी भारतीय समाज में जाति, संप्रदाय और खाप पंचायतों जैसी संकीर्ण रूढ़ियों के नाम पर युवाओं की भावनाओं का दमन किया जाता है। तताँरा-वामीरो का त्याग हमें यह सिखाता है कि समाज को रूढ़ियों से ऊपर उठकर मानवीय मूल्यों और व्यक्तिगत स्वतंत्रता को प्राथमिकता देनी चाहिए।</p>\n      </div>\n    </div>\n  </div>\n</section>","19":"<section class=\"chapter-section\" id=\"ch19\" data-book=\"sparsh-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">19</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (गद्य खंड) — पाठ 4</div>\n      <h2>तीसरी कसम के शिल्पकार शैलेंद्र</h2>\n      <p>प्रहलाद अग्रवाल | समीक्षात्मक आलेख — हिंदी सिनेमा, फणीश्वरनाथ रेणु की कहानी, राजकपूर और शैलेंद्र की कलात्मक सत्यनिष्ठा | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch19-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch19-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">शैलेंद्र ने फिल्म 'तीसरी कसम' को 'कवि-हृदय की रचना' क्यों कहा है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>शैलेंद्र मूलतः एक अत्यंत संवेदनशील, भावुक और जनवादी कवि थे। उन्होंने 'तीसरी कसम' फिल्म को केवल धन कमाने या व्यावसायिक मुनाफे के लिए नहीं, बल्कि अपनी आंतरिक कलात्मक तृप्ति के लिए बनाया था।</p>\n          <p>फिल्म में फणीश्वरनाथ रेणु की मूल कहानी 'मारे गए गुलफाम' की आत्मा, देहाती संस्कृति, हीरामन की भोली संवेदनशीलता और हीराबाई के अव्यक्त दर्द को कविता की भाँति कोमल भावों के साथ परदे पर उतारा गया था। इसमें सिनेमाई तड़क-भड़क के स्थान पर कवि की विशुद्ध संवेदनशीलता थी।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शैलेंद्र की मूल संवेदनशीलता व कवि-व्यक्तित्व का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">व्यावसायिकता से परे कलात्मक व काव्यात्मक सत्यनिष्ठा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch19-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch19-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">राजकपूर ने फिल्म 'तीसरी कसम' में काम करने के लिए क्या पारिश्रमिक माँगा था और क्यों?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>जब शैलेंद्र ने राजकपूर को कहानी सुनाई, तो राजकपूर ने हँसते हुए अग्रिम पारिश्रमिक (एडवांस) के रूप में केवल <strong>'एक रुपया'</strong> माँगा।</p>\n          <p>राजकपूर शैलेंद्र के घनिष्ठ मित्र थे और जानते थे कि शैलेंद्र एक भावुक कवि हैं, कोई बड़े फिल्म वितरक या धनवान निर्माता नहीं। वे अपने मित्र के इस कलात्मक स्वप्न को पूरा करने में सच्चे साथी बनकर खड़े होना चाहते थे।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मात्र 'एक रुपया' पारिश्रमिक माँगने का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सच्ची मित्रता व शैलेंद्र की आर्थिक स्थिति समझने का कारण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch19-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch19-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">शैलेंद्र एक आदर्शवादी कवि थे, वे व्यावसायिक सफलता के लिए कला से समझौता नहीं कर सकते थे—पाठ के आधार पर सिद्ध कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>शैलेंद्र की कलात्मक निष्ठा निम्नलिखित प्रसंगों से प्रमाणित होती है:</p>\n          <ul>\n            <li>राजकपूर ने उन्हें चेतावनी दी थी कि यह फिल्म बॉक्स ऑफिस के फॉर्मूलों (सस्ते हास्य, एक्शन, तड़क-भड़क) से कोसों दूर है और इसमें पैसा डूब सकता है, फिर भी शैलेंद्र ने कहानी की मूल आत्मा से कोई समझौता नहीं किया।</li>\n            <li>फिल्म वितरकों (डिस्ट्रीब्यूटर्स) ने जब फिल्म खरीदने से मना किया क्योंकि इसमें मसाला नहीं था, तब भी शैलेंद्र अपनी कलात्मक शुचिता पर अडिग रहे और किसी भी दृश्य को व्यावसायिक बनाने के लिए बदला नहीं।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">राजकपूर की चेतावनी के बावजूद कला पर अडिग रहना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">फिल्म वितरकों व फॉर्मूला सिनेमा के दबाव को ठुकराना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch19-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch19-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">'तीसरी कसम' फिल्म को 'साहित्यिक कृति की हूबहू मूरखता' क्यों कहा गया और समीक्षकों ने इसकी सराहना क्यों की?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>'हूबहू मूरखता' कहे जाने का कारण:</strong> व्यावसायिक सिनेमा की दुनिया में यह माना जाता है कि साहित्यिक कहानियों को जस-का-तस परदे पर उतारना मूर्खता है, क्योंकि उसमें बॉक्स ऑफिस की कमाई वाले मसाले नहीं होते। शैलेंद्र ने फणीश्वरनाथ रेणु की कहानी 'मारे गए गुलफाम' के साथ कोई सिनेमाई छेड़छाड़ नहीं की और उसे ज्यों-का-त्यों परदे पर उतार दिया, जिसे फिल्म इंडस्ट्री के चालाक लोग अव्यावहारिक मूर्खता कहते थे।</p>\n          <p><strong>समीक्षकों द्वारा सराहना:</strong> उच्च कोटि के आलोचकों और विचारकों ने इसकी मुक्तकंठ से प्रशंसा की क्योंकि यह भारतीय सिनेमा की दुर्लभ फिल्म थी जिसमें ग्रामीण भारत का यथार्थ, लोक-संस्कृति, मानवीय करुणा और शुद्ध प्रेम बिना किसी मिलावट के जीवंत हुआ था। इसे भारत सरकार का 'स्वर्ण कमल' (सर्वश्रेष्ठ फिल्म) पुरस्कार प्राप्त हुआ।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">व्यावसायिक फिल्म जगत की दृष्टि से 'हूबहू मूरखता' का अर्थ</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">समीक्षकों की प्रशंसा, लोक-यथार्थ व 'स्वर्ण कमल' पुरस्कार</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch19-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch19-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">शैलेंद्र के गीतों की क्या विशेषताएँ थीं? वे आम जनता की भावनाओं को कैसे छूते थे?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>शैलेंद्र के गीतों की प्रमुख विशेषताएँ निम्नलिखित थीं:</p>\n          <ul>\n            <li><strong>सहज और सरल भाषा:</strong> वे कठिन और क्लिष्ट शब्दों के बजाय आम जनता की बोलचाल की भाषा में गहरे दार्शनिक विचार व्यक्त करते थे (जैसे: \"सजन रे झूठ मत बोलो, खुदा के पास जाना है\")।</li>\n            <li><strong>गहरी दार्शनिकता व आशावाद:</strong> उनके गीतों में दुख और निराशा को कभी स्थायी नहीं माना गया, बल्कि जीवन के प्रति अगाध प्रेम और आशा का संदेश दिया गया (जैसे: \"तू ज़िंदा है तो ज़िंदगी की जीत में यकीन कर\")।</li>\n            <li><strong>जन-मन का प्रतिनिधित्व:</strong> उनके गीत हर वर्ग के व्यक्ति के हृदय का संगीत बन जाते थे।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सरल भाषा में गूढ़ दार्शनिक भावों का समावेश</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आशावादिता, मानवीय करुणा व गीतों के उदाहरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch19-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch19-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">'शैलेंद्र ने धन कमाने के लिए नहीं, आत्म-तुष्टि के लिए फिल्म बनाई थी'—इस कथन की समीक्षा कीजिए।</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>समीक्षा:</strong> यह कथन शत-प्रतिशत सत्य है। शैलेंद्र एक सफल और अत्यधिक व्यस्त गीतकार थे, उनके पास धन और प्रसिद्धि की कोई कमी नहीं थी। यदि उनका उद्देश्य धन कमाना होता, तो वे उस दौर के प्रचलित फॉर्मूलों वाली मसाला फिल्म बनाते जिसमें मुनाफा पक्का होता।</p>\n          <p>किंतु शैलेंद्र के भीतर का सच्चा साहित्यकार एक ऐसी कृति का सृजन करना चाहता था जो आत्मा को तृप्त करे और भारतीय सिनेमा के इतिहास में एक मील का पत्थर बने। उन्होंने आर्थिक नुकसान और कर्ज का जोखिम उठाकर भी 'तीसरी कसम' बनाई। यद्यपि इस फिल्म के तनाव ने असमय ही उनके प्राण ले लिए, किंतु उन्होंने कला के साथ कभी सौदा नहीं किया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शैलेंद्र के सफल गीतकार होने व धन से परे उद्देश्य का विश्लेषण</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कलात्मक आत्म-तुष्टि, आर्थिक जोखिम व कालजयी कृति का निर्माण</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Competency-Based Questions (CBQs) -->\n  <div class=\"cbq-card\">\n    <div class=\"cbq-badge\">CBSE Board Competency-Based Question (योग्यता आधारित प्रश्न)</div>\n    <div class=\"q-text\"><strong>सिनेमा और साहित्यिक मूल्य (Cinema & Literary Values):</strong> वर्तमान युग में ओटीटी (OTT) और बड़े बजट की फिल्मों में हिंसा, सनसनी और अश्लीलता को व्यावसायिक सफलता का साधन माना जाता है। 'तीसरी कसम के शिल्पकार शैलेंद्र' के आलोक में विश्लेषण कीजिए कि सार्थक सिनेमा का सामाजिक उत्तरदायित्व क्या होना चाहिए?</div>\n    <div class=\"answer-box\" style=\"margin-top: 15px;\">\n      <div class=\"answer-label\">विशेषज्ञ उत्तर व विश्लेषणात्मक दृष्टिकोण</div>\n      <div class=\"answer-text\">\n        <p><strong>विश्लेषण:</strong> शैलेंद्र ने 'तीसरी कसम' बनाकर यह सिद्ध किया था कि सिनेमा केवल व्यापार नहीं, बल्कि मानवीय संवेदनाओं को परिष्कृत करने का सशक्त माध्यम है।</p>\n        <p><strong>सामाजिक उत्तरदायित्व:</strong> आज के फिल्म निर्माताओं को यह समझना चाहिए कि तात्कालिक मुनाफे के लिए समाज की संवेदनाओं को कुंद करना अनैतिक है। सार्थक सिनेमा वही है जो समाज को संवेदनशीलता, मानवीय मूल्य और सांस्कृतिक चेतना प्रदान करे, जैसा शैलेंद्र ने अपनी कृति में प्रस्तुत किया।</p>\n      </div>\n    </div>\n  </div>\n</section>","20":"<section class=\"chapter-section\" id=\"ch20\" data-book=\"sparsh-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">20</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (गद्य खंड) — पाठ 5</div>\n      <h2>अब कहाँ दूसरे के दुख से दुखी होने वाले</h2>\n      <p>निदा फ़ाज़ली | संस्मरणात्मक निबंध — पर्यावरण असंतुलन, मानवेतर प्राणियों के प्रति संवेदना, स्वार्थपरक आधुनिकता और प्रकृति का प्रतिशोध | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch20-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch20-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">बड़े-बड़े बिल्डर समुद्र को पीछे क्यों धकेल रहे थे और इसका प्रकृति पर क्या दुष्प्रभाव पड़ा?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>बिल्डरों का स्वार्थ:</strong> मुंबई जैसे महानगर में आबादी के दबाव और अधिक से अधिक धन कमाने के लोभ में बिल्डर समुद्र के किनारे मिट्टी पाटकर समुद्र को पीछे धकेल रहे थे और कंक्रीट की गगनचुंबी इमारतें खड़ी कर रहे थे।</p>\n          <p><strong>प्रकृति पर दुष्प्रभाव:</strong> प्रकृति के साथ इस निरंतर छेड़छाड़ के कारण भयानक असंतुलन पैदा हो गया। बेमौसम बरसात, भीषण गर्मी, भूकंप, तूफ़ान और सुनामी जैसी आपदाएँ आने लगीं। समुद्र ने क्रुद्ध होकर एक रात तीन बड़े समुद्री जहाजों को बच्चों की गेंद की तरह उठाकर शहर की सड़कों पर फेंक दिया, जिससे भारी तबाही हुई।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बिल्डरों के लालच व कंक्रीट जंगल बनाने का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्राकृतिक आपदाओं व समुद्र के रोष (जहाज फेंकने) का विवरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch20-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch20-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">सुलेमान (सोलोमन) ने चींटियों से क्या कहा और उनका कौन-सा मानवीय गुण प्रकट हुआ?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>जब हज़रत सुलेमान अपने लश्कर (सेना) के साथ गुज़र रहे थे, तो चींटियों ने घोड़ों की टापों की आवाज़ सुनकर भयभीत होकर एक-दूसरे से कहा कि \"जल्दी अपने बिलों में चलो।\"</p>\n          <p>सुलेमान ने उनकी बात सुनकर अपनी सेना को रोका और चींटियों से विनम्रतापूर्वक कहा: \"घबराओ नहीं, ईश्वर ने मुझे सबके लिए रहमत (दया) बनाकर भेजा है, किसी के लिए मुसीबत नहीं।\" इस प्रसंग से सुलेमान की असीम संवेदनशीलता, दया, करुणा और छोटे से छोटे जीव के प्रति सम्मान का गुण प्रकट होता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सुलेमान के रहमत भरे कथन का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दया, करुणा व जीव-मात्र के प्रति संवेदनशीलता का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch20-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch20-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">लेखक की माँ ने कब-कब रोज़ा रखा या प्रायश्चित किया और क्यों?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखक के घर के रोशनदान में एक कबूतर के जोड़े ने दो अंडे दिए थे। एक अंडा बिल्ली ने झपटकर तोड़ दिया था।</p>\n          <p>लेखक की माँ ने स्टूल पर चढ़कर दूसरे अंडे को बिल्ली से बचाने की कोशिश की, किंतु दुर्भाग्यवश उनके हाथ से फिसलकर दूसरा अंडा भी फर्श पर गिरकर टूट गया। कबूतरों के जोड़े को दुख से फड़फड़ाते देखकर माँ का हृदय चीत्कार कर उठा। इस अनजाने में हुए पाप का प्रायश्चित करने के लिए माँ ने पूरे दिन का रोज़ा रखा, न कुछ खाया-पिया और दिनभर नमाज़ में रो-रोकर खुदा से माफी माँगती रहीं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अंडा टूटने की कारुणिक घटना का विवरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">माँ द्वारा दिनभर का रोज़ा रखने व पश्चाताप का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch20-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch20-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">शेख अयाज़ के पिता अपने हाथ पर रेंगते च्योंटे को देखकर भोजन छोड़कर क्यों उठ खड़े हुए?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>सिंधी भाषा के प्रसिद्ध कवि शेख अयाज़ के पिता कुएँ से नहाकर लौटे और भोजन करने बैठे ही थे कि उन्होंने अपनी बाँह पर एक काला च्योंटा रेंगते देखा।</p>\n          <p>वे तुरंत भोजन की थाली छोड़कर उठ खड़े हुए। जब उनकी माँ ने पूछा कि क्या भोजन अच्छा नहीं लगा, तो उन्होंने उत्तर दिया: \"नहीं, मैंने एक बेघर को उसके घर से जुदा कर दिया है। मैं पहले इस बेघर जीव को उसके घर (कुएँ की मुँडेर पर) छोड़ने जा रहा हूँ, उसके बाद ही अन्न ग्रहण करूँगा।\" यह उनकी पराकाष्ठापूर्ण जीव-दया का परिचायक है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हाथ पर च्योंटा देखकर थाली छोड़ने का प्रसंग</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बेघर जीव को घर पहुँचाने की संवेदनशीलता का निरूपण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch20-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch20-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">'डेरा डालने' और 'घर बनाने' में क्या अंतर है? वर्तमान शहरीकरण ने जीव-जंतुओं के आवास को कैसे छीना है?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>अंतर:</strong> 'घर बनाना' स्थायी निवास होता है जहाँ सुरक्षा, अपनत्व और शांति की भावना होती है। जबकि 'डेरा डालना' अस्थाई और विवशतापूर्ण ठहराव होता है, जहाँ रहने वाला जानता है कि उसे कभी भी भगाया जा सकता है।</p>\n          <p><strong>शहरीकरण का दुष्परिणाम:</strong> अंधाधुंध शहरीकरण, वनों की कटाई और कंक्रीट के जंगलों के निर्माण ने पक्षियों और वन्यजीवों के प्राकृतिक आश्रय छीन लिए हैं। अब पक्षी पेड़ों की तलाश में भटकते हैं और इंसानों के फ्लैटों, खिड़कियों या एसी (AC) के बक्सों में अस्थायी 'डेरा डालने' को विवश हैं, जहाँ से भी स्वार्थी मनुष्य जाली लगाकर उन्हें बेदखल कर देता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">'घर बनाने' व 'डेरा डालने' के दार्शनिक अंतर का स्पष्टीकरण</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शहरीकरण द्वारा मूक प्राणियों के विस्थापन की त्रासदी</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch20-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch20-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">लेखक की पत्नी ने कबूतरों से तंग आकर क्या किया और यह घटना वर्तमान समाज की किस मानसिकता को दर्शाती है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखक की पत्नी ने कबूतरों द्वारा की जाने वाली गंदगी और सामान गिराने से परेशान होकर खिड़की पर लोहे की जाली लगवा दी और कबूतरों के आने का रास्ता बंद कर दिया। कबूतर बाहर उदास बैठकर रातभर फड़फड़ाते रहे।</p>\n          <p>यह घटना आधुनिक समाज की संवेदनहीन और आत्मकेंद्रित मानसिकता को दर्शाती है। आज का मनुष्य केवल अपनी सुविधा और स्वच्छता देखता है, उसे दूसरे मूक प्राणियों के दर्द और बेघरी से कोई सरोकार नहीं रह गया है। यह लेखक की माँ के काल से वर्तमान पीढ़ी के संवेदनहीन पतन का स्पष्ट प्रमाण है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">खिड़की पर जाली लगाने व कबूतरों के बेघर होने का प्रसंग</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आधुनिक आत्मकेंद्रित व संवेदनहीन मानसिकता पर टिप्पणी</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Competency-Based Questions (CBQs) -->\n  <div class=\"cbq-card\">\n    <div class=\"cbq-badge\">CBSE Board Competency-Based Question (योग्यता आधारित प्रश्न)</div>\n    <div class=\"q-text\"><strong>पारिस्थितिकी एवं संवेगात्मक विश्लेषण (Ecological & Emotional Analysis):</strong> 'यह धरती केवल मनुष्य की नहीं, अपितु समस्त जीव-जंतुओं की साझा धरोहर है।' 'अब कहाँ दूसरे के दुख से दुखी होने वाले' पाठ के आधार पर स्पष्ट कीजिए कि मानव का अति-अहंकार किस प्रकार वैश्विक जलवायु संकट (Climate Crisis) का कारण बन रहा है?</div>\n    <div class=\"answer-box\" style=\"margin-top: 15px;\">\n      <div class=\"answer-label\">विशेषज्ञ उत्तर व विश्लेषणात्मक दृष्टिकोण</div>\n      <div class=\"answer-text\">\n        <p><strong>विश्लेषण:</strong> लेखक ने पाठ में यह स्पष्ट किया है कि मनुष्य ने अपनी बुद्धि के घमंड में पूरी पृथ्वी को अपनी जागीर समझ लिया और अन्य सभी सहजीवियों को उनके प्राकृतिक अधिकारों से वंचित कर दिया।</p>\n        <p><strong>जलवायु संकट से संबंध:</strong> जंगलों की कटाई, नदियों-समुद्रों पर अवैध अतिक्रमण और अनियंत्रित औद्योगिकीकरण से पृथ्वी की सहने की सीमा समाप्त हो चुकी है। इसका परिणाम ग्लोबल वॉर्मिंग, ग्लेशियरों का पिघलना और अप्रत्याशित विनाश के रूप में सामने आ रहा है। जब तक मनुष्य सह-अस्तित्व की भावना को नहीं अपनाएगा, तब तक उसका स्वयं का अस्तित्व भी सुरक्षित नहीं रह सकता।</p>\n      </div>\n    </div>\n  </div>\n</section>","21":"<section class=\"chapter-section\" id=\"ch21\" data-book=\"sparsh-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">21</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (गद्य खंड) — पाठ 6</div>\n      <h2>पतझर में टूटी पत्तियाँ</h2>\n      <p>रवींद्र केलेकर | विचार-प्रधान निबंध — 'गिन्नी का सोना' (आदर्श बनाम व्यावहारिकता) एवं 'झेन की देन' (टी-सेरेमनी, मानसिक तनाव और वर्तमान का बोध) | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch21-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch21-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">'गिन्नी का सोना' और 'शुद्ध सोना' में क्या अंतर है? पाठ के आधार पर स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>शुद्ध सोना:</strong> यह शत-प्रतिशत खरा और शुद्ध होता है, जिसमें किसी प्रकार की मिलावट नहीं होती। यह शुद्ध आदर्शों का प्रतीक है। शुद्ध सोना बहुत मुलायम होता है, इसलिए केवल उससे मजबूत आभूषण नहीं बन सकते।</p>\n          <p><strong>गिन्नी का सोना:</strong> शुद्ध सोने में थोड़ा-सा ताँबा मिला देने से वह 'गिन्नी का सोना' बन जाता है। ताँबा मिलने से उसमें मजबूती और चमक आ जाती है और उससे सुंदर आभूषण गढ़े जा सकते हैं। यह व्यावहारिकता का प्रतीक है। लोग अक्सर शुद्ध सोने से अधिक गिन्नी के सोने को उपयोगी मानते हैं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शुद्ध सोने (बिना मिलावट/आदर्श) का लक्षण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गिन्नी के सोने (ताँबे की मिलावट/उपयोगिता) का अंतर</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch21-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch21-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">'प्रैक्टिकल आइडियलिस्ट' (व्यावहारिक आदर्शवादी) किसे कहते हैं और लेखक ने गांधीजी के संदर्भ में क्या कहा है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>प्रैक्टिकल आइडियलिस्ट:</strong> जो लोग व्यावहारिकता के नाम पर अपने आदर्शों को नहीं छोड़ते, बल्कि अपने शुद्ध आदर्शों को व्यवहार में लागू करने की क्षमता रखते हैं, उन्हें 'प्रैक्टिकल आइडियलिस्ट' कहा जाता है।</p>\n          <p><strong>गांधीजी का संदर्भ:</strong> कई लोग गांधीजी को भी 'प्रैक्टिकल आइडियलिस्ट' कहते हैं क्योंकि वे जानते थे कि जनता से किस प्रकार काम लेना है। किंतु लेखक का मानना है कि गांधीजी ने कभी अपने आदर्शों में व्यावहारिकता (ताँबा) नहीं मिलाई, बल्कि उन्होंने व्यावहारिकता के स्तर को ऊँचा उठाकर अपने शुद्ध सोने जैसे आदर्शों के बराबर पहुँचाया। यदि वे विशुद्ध व्यावहारिक होते, तो देश को आज़ादी की नई दिशा कभी न दे पाते।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">'प्रैक्टिकल आइडियलिस्ट' की सही परिभाषा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गांधीजी द्वारा आदर्शों को न गिराने के दृष्टिकोण की व्याख्या</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch21-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch21-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">जापान में 'टी-सेरेमनी' (चा-नो-यू) क्या है और इसमें मानसिक शांति कैसे प्राप्त होती है?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>चा-नो-यू (टी-सेरेमनी):</strong> यह जापान में चाय पीने की एक अत्यंत पवित्र और औपचारिक रस्म है। यह छह मंजिला इमारत की छत पर बनी फूस की एक छोटी-सी पर्णकुटी (टी-क्लब) में संपन्न होती है, जहाँ एक बार में केवल तीन व्यक्तियों को प्रवेश दिया जाता है।</p>\n          <p><strong>शांति प्राप्ति की विधि:</strong> वहाँ का वातावरण अत्यंत शांत और गरिमामय होता है। 'चाजीन' (चाय तैयार करने वाला) अत्यंत धीमे, सलीके और शांत भाव से बर्तन पोंछता है, अंगीठी सुलगाता है और चाय बनाता है। वहाँ कोई शोर नहीं होता। उस मौन और शांत परिवेश में जब लोग घूँट-घूँट (सिप-सिप) करके डेढ़-दो घंटे तक चाय पीते हैं, तो उनके मन की भागदौड़ थम जाती है और उन्हें असीम मानसिक शांति का अनुभव होता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">चा-नो-यू का परिचय, स्थान व तीन व्यक्तियों की मर्यादा</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">चाजीन की शांत क्रियाविधि व मानसिक शांति का मनोवैज्ञानिक प्रभाव</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch21-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch21-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">चाय पीने के बाद लेखक ने अपने दिमाग में किस प्रकार का परिवर्तन महसूस किया?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>चाय की चुस्कियाँ लेते हुए शुरू के दस-पंद्रह मिनट लेखक के भीतर बेचैनी रही, किंतु धीरे-धीरे उनके दिमाग की रफ्तार धीमी होने लगी। कुछ देर बाद दिमाग की गति बिल्कुल रुक गई और चारों ओर असीम सन्नाटा छा गया।</p>\n          <p>उन्हें ऐसा लगा मानो भूतकाल और भविष्यकाल दोनों उड़ गए हों और केवल वर्तमान क्षण ही सामने उपस्थित हो। वे उस वर्तमान क्षण में जीने लगे, जो अनंत काल जितना विस्तृत महसूस हुआ। उनके मस्तिष्क का सारा तनाव विलीन हो गया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दिमाग की रफ्तार का धीमा व पूर्णतः शांत होना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भूत व भविष्य से मुक्त होकर वर्तमान में जीने की अनुभूति</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch21-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch21-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">लेखक के अनुसार वास्तविक सत्य क्या है—भूतकाल, भविष्यकाल या वर्तमानकाल? स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखक के अनुसार <strong>वर्तमानकाल ही एकमात्र वास्तविक और जीवित सत्य है</strong>।</p>\n          <p>भूतकाल बीत चुका है, वह अब लौटकर नहीं आ सकता और भविष्यकाल अभी आया नहीं है, वह केवल हमारी कल्पना है। दोनों ही काल मिथ्या हैं। मनुष्य अक्सर या तो बीते दिनों की यादों में उलझकर दुखी रहता है या आने वाले कल के हसीन सपने देखकर चिंतित रहता है। जो व्यक्ति वर्तमान क्षण में पूरी सजगता के साथ जीता है, वही वास्तव में जीवन के वास्तविक आनंद और सत्य को प्राप्त करता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भूत व भविष्य को मिथ्या बताने का तर्क</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वर्तमान क्षण के एकमात्र यथार्थ सत्य होने का दार्शनिक विवेचन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch21-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch21-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">शुद्ध आदर्शों की तुलना सोने से और व्यावहारिकता की तुलना ताँबे से क्यों की गई है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखक ने शुद्ध आदर्शों की तुलना सोने से और व्यावहारिकता की तुलना ताँबे से अत्यंत सार्थक रूप में की है:</p>\n          <ul>\n            <li><strong>सोना (शुद्ध आदर्श):</strong> शुद्ध सोना अत्यंत मूल्यवान, अक्षुण्ण और शाश्वत होता है। समाज के नैतिक मूल्य, सत्य, अहिंसा और प्रेम सोने के समान अनमोल हैं, जो मानवता को पतन से बचाते हैं।</li>\n            <li><strong>ताँबा (व्यावहारिकता):</strong> ताँबा सस्ता धातु है जिसका उपयोग केवल सोने को आकार और मजबूती देने के लिए किया जाता है। यदि कोई ताँबे को ही सोना मान ले, तो यह उसका भ्रम है। इसी प्रकार यदि व्यावहारिकता में आदर्श न हों, तो वह केवल स्वार्थपरता बन जाती है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सोने के रूपक द्वारा नैतिक मूल्यों की व्याख्या</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">ताँबे द्वारा व्यावहारिकता व स्वार्थपरता के अंतर का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Competency-Based Questions (CBQs) -->\n  <div class=\"cbq-card\">\n    <div class=\"cbq-badge\">CBSE Board Competency-Based Question (योग्यता आधारित प्रश्न)</div>\n    <div class=\"q-text\"><strong>मानसिक स्वास्थ्य एवं जीवनशैली विश्लेषण (Mental Health & Mindfulness):</strong> आधुनिक जीवन की तीव्र प्रतिस्पर्धा में युवा मानसिक अवसाद (Depression) और तनाव से जूझ रहे हैं। 'झेन की देन' के आलोक में समझाइए कि 'माइंडफुलनेस' (सजग वर्तमान में जीना) किस प्रकार आधुनिक जीवनशैली की व्याधियों का प्रभावी उपचार सिद्ध हो सकता है?</div>\n    <div class=\"answer-box\" style=\"margin-top: 15px;\">\n      <div class=\"answer-label\">विशेषज्ञ उत्तर व विश्लेषणात्मक दृष्टिकोण</div>\n      <div class=\"answer-text\">\n        <p><strong>विश्लेषण:</strong> पाठ में बताया गया है कि जापान के लोग अमेरिका से प्रतिस्पर्धा करने के चक्कर में एक महीने का काम एक दिन में करने की कोशिश करते हैं, जिससे उनका मानसिक संतुलन बिगड़ जाता है और बहुसंख्यक आबादी मानसिक रोगी बन जाती है।</p>\n        <p><strong>माइंडफुलनेस का महत्व:</strong> 'झेन की देन' हमें सिखाती है कि भविष्य की अनिश्चित चिंताओं और अतीत के पछतावे से मुक्त होकर वर्तमान क्षण के प्रत्येक कार्य को पूरी तन्मयता से करना चाहिए। जब हम वर्तमान में सजगता से जीते हैं, तो मस्तिष्क की व्यर्थ भागदौड़ रुक जाती है, जिससे तनाव और अवसाद का स्थायी शमन होता है।</p>\n      </div>\n    </div>\n  </div>\n</section>","22":"<section class=\"chapter-section\" id=\"ch22\" data-book=\"sparsh-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">22</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (गद्य खंड) — पाठ 7</div>\n      <h2>कारतूस</h2>\n      <p>हबीब तनवीर | ऐतिहासिक एकांकी (नाटक) — 1799 गोरखपुर का जंगल, अवध के नवाब वज़ीर अली की जाँबाज़ी और अंग्रेजों के विरुद्ध विद्रोह | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch22-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch22-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">कर्नल कालिंज का खेमा जंगल में क्यों लगा हुआ था?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कर्नल कालिंज और लेफ्टिनेंट अपनी पूरी ब्रिटिश फौजी टुकड़ी के साथ गोरखपुर के घने जंगलों में खेमा डाले हुए थे। उनका मुख्य उद्देश्य अवध के पूर्व नवाब <strong>वज़ीर अली</strong> को गिरफ्तार करना था, जो अंग्रेजों की आँखों में धूल झोंककर इन जंगलों में छिपा हुआ था और अंग्रेजों को भारत से खदेड़ने की योजना बना रहा था।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गोरखपुर के जंगल में खेमा लगाने का संदर्भ</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वज़ीर अली को गिरफ्तार करने के उद्देश्य का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch22-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch22-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">वज़ीर अली ने कंपनी के वकील का कत्ल क्यों किया?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कंपनी ने वज़ीर अली को अवध के तख्त से हटाकर बनारस भेज दिया था और तीन लाख रुपये सालाना वजीफा मुकर्रर किया था। कुछ समय बाद गवर्नर जनरल ने उसे कलकत्ता तलब किया।</p>\n          <p>वज़ीर अली बनारस में रह रहे कंपनी के वकील के पास अपनी शिकायत लेकर गया। वकील ने वज़ीर अली की शिकायत सुनने के बजाय उसे खूब खरी-खोटी सुनाई और उसका घोर अपमान किया। स्वाभिमानी वज़ीर अली के दिल में अंग्रेजों के प्रति पहले से ही नफरत भरी थी। वकील की इस बदतमीजी को वह सहन न कर सका और उसने तलवार निकालकर वकील का काम तमाम कर दिया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कलकत्ता बुलाने व वकील के पास शिकायत का प्रसंग</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वकील द्वारा अपमान व स्वाभिमानी प्रतिशोध का कारण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch22-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch22-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">सआदत अली कौन था और उसने अंग्रेजों की क्या मदद की तथा अपनी आधी रियासत क्यों दे दी?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>सआदत अली वज़ीर अली का चाचा और नवाब आसिफउद्दौला का भाई था। वह अत्यंत ऐशो-आराम पसंद और कायर व्यक्ति था।</p>\n          <p>वह अवध का नवाब बनना चाहता था। अंग्रेजों ने उसकी इस लालसा का फायदा उठाया। अंग्रेजों ने वज़ीर अली को अपदस्थ करके सआदत अली को अवध की गद्दी पर बिठा दिया। इस उपकार के बदले सआदत अली ने अपनी आधी रियासत और दस लाख रुपये नकद अंग्रेजों को सौंप दिए ताकि वह निश्चिंत होकर भोग-विलास का जीवन जी सके।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सआदत अली का परिचय (चाचा, विलासी स्वभाव)</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नवाब बनने के बदले आधी रियासत व धन देने का सौदा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch22-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch22-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">वज़ीर अली के अफ़साने सुनकर कर्नल को रॉबिनहुड की याद क्यों आती थी?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>रॉबिनहुड की तरह वज़ीर अली भी अत्यंत साहसी, निडर, स्वाभिमानी और अंग्रेजों को चकमा देने में माहिर था।</p>\n          <p>उसने शासन के केवल पाँच महीनों में ही अवध के दरबार को ब्रिटिश प्रभाव से लगभग मुक्त कर दिया था। वह जंगलों में छिपकर सीमित संसाधनों में भी अंग्रेजों की नाक में दम किए हुए था। उसके अदम्य साहस, जाँबाज़ी और अंग्रेजों के विरुद्ध छापामार रणनीति के कारण कर्नल को रॉबिनहुड के कारनामों की याद आती थी।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वज़ीर अली के अदम्य साहस व जाँबाज़ी का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">रॉबिनहुड जैसी छापामार रणनीति व अंग्रेजों के छक्के छुड़ाने की तुलना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch22-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch22-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">सवार ने कर्नल से कारतूस कैसे हासिल किए और कर्नल हक्का-बक्का क्यों रह गया?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>कारतूस हासिल करना:</strong> वज़ीर अली स्वयं एक घुड़सवार के वेश में अकेला कर्नल के खेमे में घुस आया। उसने कर्नल से कहा कि वह वज़ीर अली को पकड़ने में मदद कर सकता है, इसलिए उसे दस कारतूस चाहिए। कर्नल ने खुश होकर उसे दस कारतूस दे दिए।</p>\n          <p><strong>कर्नल का हक्का-बक्का रह जाना:</strong> जब कर्नल ने उसका नाम पूछा, तो उसने गर्व से कहा—\"वज़ीर अली!\" और कहा कि \"आपने मुझे कारतूस दिए हैं, इसलिए मैं आपकी जान बख्शता हूँ।\" इतना कहकर वह घोड़े पर सवार होकर धूल उड़ाते हुए गायब हो गया। जिस शत्रु को पूरी सेना हफ़्तों से ढूँढ़ रही थी, वह उसके सामने आकर कारतूस ले गया और प्राण बख्श गया—यह देखकर कर्नल सन्न और हक्का-बक्का रह गया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">खेमे में अकेले आकर चतुराई से कारतूस लेने की घटना</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वास्तविक नाम बताकर प्राण बख्शने व कर्नल के विस्मय का निरूपण</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch22-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch22-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">'कारतूस' एकांकी के आधार पर वज़ीर अली के चरित्र की प्रमुख विशेषताओं पर प्रकाश डालिए।</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>वज़ीर अली का चरित्र एक सच्चे देशभक्त और अदम्य वीर सेनानी का है:</p>\n          <ul>\n            <li><strong>अदम्य साहसी व निडर:</strong> वह शेर की माँद में जाकर शिकार करने का साहस रखता था। ब्रिटिश छावनी में अकेले घुसकर कर्नल से कारतूस ले लेना उसकी अभूतपूर्व बहादुरी का प्रमाण है।</li>\n            <li><strong>सच्चा देशभक्त:</strong> उसके दिल में अंग्रेजों के प्रति गहरी नफरत थी। उसका एकमात्र लक्ष्य अंग्रेजों को भारत की भूमि से खदेड़ना था।</li>\n            <li><strong>स्वाभिमानी:</strong> जब कंपनी के वकील ने उसका अपमान किया, तो उसने झुकने के बजाय तलवार से उसका अंत कर दिया।</li>\n            <li><strong>शत्रु द्वारा भी प्रशंसित:</strong> उसकी वीरता देखकर स्वयं कर्नल कालिंज के मुँह से अनायास निकला—\"एक जाँबाज़ सिपाही!\"</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">साहस, निडरता व देशभक्ति के गुणों का निरूपण</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्वाभिमान व शत्रु (कर्नल) द्वारा 'जाँबाज़ सिपाही' कहे जाने का संदर्भ</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Competency-Based Questions (CBQs) -->\n  <div class=\"cbq-card\">\n    <div class=\"cbq-badge\">CBSE Board Competency-Based Question (योग्यता आधारित प्रश्न)</div>\n    <div class=\"q-text\"><strong>ऐतिहासिक देशभक्ति एवं नेतृत्व विश्लेषण (Historical Patriotism & Leadership):</strong> 'कारतूस' एकांकी में वज़ीर अली के संघर्ष के माध्यम से 1857 के प्रथम स्वतंत्रता संग्राम से पूर्व के भारतीय असंतोष की झलक मिलती है। समीक्षा कीजिए कि भारतीय राजाओं के आपसी विश्वासघात (जैसे सआदत अली) के बावजूद वज़ीर अली जैसे योद्धाओं का बलिदान किस प्रकार भारतीय स्वतंत्रता चेतना की आधारशिला बना?</div>\n    <div class=\"answer-box\" style=\"margin-top: 15px;\">\n      <div class=\"answer-label\">विशेषज्ञ उत्तर व विश्लेषणात्मक दृष्टिकोण</div>\n      <div class=\"answer-text\">\n        <p><strong>समीक्षा:</strong> ब्रिटिश ईस्ट इंडिया कंपनी ने 'फूट डालो और राज करो' की नीति के तहत सआदत अली जैसे विलासी और देशद्रोही राजाओं को मोहरा बनाकर भारत को गुलाम बनाया।</p>\n        <p><strong>स्वतंत्रता चेतना की आधारशिला:</strong> ऐसे निराशाजनक दौर में भी वज़ीर अली जैसे जाँबाज़ योद्धाओं ने व्यक्तिगत सुख-सुविधाओं का त्याग कर अंग्रेजों के विरुद्ध सशस्त्र विद्रोह किया। यद्यपि उनके पास विशाल सेना नहीं थी, किंतु उनके अदम्य साहस और बलिदान ने भारतीय जनमानस में यह विश्वास जगाया कि विदेशी सत्ता अजेय नहीं है। यही चेतना आगे चलकर 1857 की क्रांति का आधार बनी।</p>\n      </div>\n    </div>\n  </div>\n</section>","23":"<section class=\"chapter-section\" id=\"ch23\" data-book=\"sparsh-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">23</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (काव्य खंड) — पाठ 1</div>\n      <h2>साखी</h2>\n      <p>संत कबीरदास | सधुक्कड़ी भाषा — नीति, ज्ञान, अहंकार-मुक्ति, नाम-महिमा और भक्ति की साधना | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch23-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch23-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">मीठी वाणी बोलने से औरों को सुख और अपने तन को शीतलता कैसे प्राप्त होती है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कबीरदास जी के अनुसार—<em>\"ऐसी बाणी बोलिये, मन का आपा खोइ। औरन को सीतल करै, आपहु सीतल होइ॥\"</em></p>\n          <ul>\n            <li>जब मनुष्य अपने अहंकार (आपा) का त्याग करके मधुर और विनम्र वाणी बोलता है, तो उसके भीतर का क्रोध, कटुता और ईर्ष्या समाप्त हो जाती है, जिससे उसका अपना मन और शरीर शांत (शीतल) हो जाता है।</li>\n            <li>ऐसी वाणी सुनने वाले के हृदय की पीड़ा को हरकर उसे अपार सुख, प्रेम और आत्मीयता प्रदान करती है। मीठे बोल बैर को मिटाकर सौहार्द की सृष्टि करते हैं।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अहंकार त्याग से आत्मिक शीतलता मिलने का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">श्रोता के मन पर सुखद व शांतिदायक प्रभाव का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch23-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch23-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">दीपक दिखाई देने पर अँधियारा कैसे मिट जाता है? साखी के संदर्भ में स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कबीरदास जी कहते हैं—<em>\"जब मैं था तब हरि नहीं, अब हरि हैं मैं नाहिं। सब अँधियारा मिटि गया, जब दीपक देख्या माहिं॥\"</em></p>\n          <p>यहाँ 'दीपक' ज्ञान और ईश्वर-साक्षात्कार का प्रतीक है तथा 'अँधियारा' अज्ञान, भ्रम और अहंकार का प्रतीक है। जिस प्रकार दीपक जलते ही कमरे का सारा अंधकार स्वतः नष्ट हो जाता है, उसी प्रकार जब अंतःकरण में गुरु-कृपा से ईश्वरीय ज्ञान का दीपक जलता है, तो मनुष्य के भीतर से अज्ञान, वासना और अहम् का सारा अंधकार तत्क्षण विलीन हो जाता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दीपक (ज्ञान) व अंधकार (अज्ञान/अहंकार) का प्रतीकार्थ</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आत्म-साक्षात्कार से अज्ञान विनाश की व्याख्या</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch23-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch23-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">ईश्वर कण-कण में व्याप्त है, पर हम उसे क्यों नहीं देख पाते?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कबीरदास जी कस्तूरी मृग का उदाहरण देते हुए कहते हैं—<em>\"कस्तूरी कुंडलि बसै, मृग ढूँढ़ै बन माहि। ऐसे घटि-घटि रांम हैं, दुनियां देखै नांहि॥\"</em></p>\n          <p>जिस प्रकार मृग की अपनी नाभि में ही कस्तूरी की सुगंध होती है, किंतु अज्ञानतावश वह उसे सारे जंगल की घास में ढूँढ़ता फिरता है; उसी प्रकार परमात्मा प्रत्येक मनुष्य के अंतःकरण और सृष्टि के कण-कण में समाया हुआ है। किंतु अज्ञान, सांसारिक मोह-माया और अहंकार के पर्दे के कारण मनुष्य उसे अपने भीतर न देखकर बाहर देवालयों और तीर्थों में ढूँढ़ता भटकता रहता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कस्तूरी मृग के दृष्टांत का सटीक प्रयोग</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अज्ञानता व अहंकार द्वारा अंतःकरण के ईश्वर को न देख पाने का कारण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch23-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch23-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">संसार में सुखी व्यक्ति कौन है और दुखी कौन? यहाँ 'सोना' और 'जागना' किसके प्रतीक हैं?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कबीर के अनुसार—<em>\"सुखिया सब संसार है, खाइ अरु सोवै। दुखिया दास कबीर है, जागै अरु रोवै॥\"</em></p>\n          <ul>\n            <li><strong>सुखी व्यक्ति:</strong> जो लोग सांसारिक भोग-विलास, खाने-पीने और मौज-मस्ती में लिप्त रहते हैं और जिन्हें मृत्यु व ईश्वर का कोई भान नहीं है, वे सांसारिक दृष्टि से स्वयं को सुखी मानते हैं।</li>\n            <li><strong>दुखी व्यक्ति:</strong> कबीर जैसे प्रभु-भक्त और ज्ञानी संत दुखी हैं, क्योंकि वे संसार की नश्वरता को देखकर रोते हैं और ईश्वर के विरह में तड़पते रहते हैं।</li>\n            <li><strong>प्रतीकार्थ:</strong> यहाँ 'सोना' अज्ञान और मोह-माया में बेखबर रहने का प्रतीक है, जबकि 'जागना' आत्म-ज्ञान और ईश्वरीय चेतना के प्रति सजगता का प्रतीक है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सांसारिक सुखी व संत के दुख का तुलनात्मक अंतर</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">'सोना' (अज्ञान) व 'जागना' (आत्म-चेतना) के प्रतीकार्थ का विवेचन</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch23-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch23-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">अपने स्वभाव को निर्मल रखने के लिए कबीर ने क्या उपाय सुझाया है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कबीरदास जी कहते हैं—<em>\"निंदक नेड़ा राखिये, आँगणि कुटी बँधाइ। बिनु साबण पाँणीं बिना, निरमल करै सुभाइ॥\"</em></p>\n          <p>कबीर ने अपने स्वभाव को शुद्ध और पवित्र रखने के लिए निंदक (आलोचक) को अपने निकट रखने का उपाय सुझाया है। निंदक हमारे दोषों और कमियों को निष्पक्षता से बताता है, जिससे हमें अपनी गलतियों को सुधारने का अवसर मिलता है। इस प्रकार बिना साबुन और पानी के हमारा अंतःकरण स्वतः निर्मल हो जाता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">निंदक को निकट रखने के उपाय का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बिना साबुन-पानी स्वभाव निर्मल होने का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch23-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch23-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">'ऐके अषिर पीव का, पढ़े सु पंडित होइ'—इस पंक्ति द्वारा कवि क्या कहना चाहते हैं?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कबीरदास जी के अनुसार केवल मोटी-मोटी धार्मिक पुस्तकें (पोथियाँ) पढ़कर कोई व्यक्ति सच्चा ज्ञानी या पंडित नहीं बन सकता।</p>\n          <p>सच्चा विद्वान वही है जिसने परमात्मा के 'प्रेम' का एक अक्षर भी अपने जीवन में उतार लिया हो। किताबी पांडित्य के स्थान पर ईश्वर के प्रति सच्चा प्रेम और प्राणिमात्र के प्रति करुणा ही मनुष्य को वास्तविक ज्ञान और मोक्ष की ओर ले जाती है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पोथी-पांडित्य की व्यर्थता का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">ईश्वरीय प्रेम के एक अक्षर की महत्ता का निरूपण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch23-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch23-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">कबीर की उद्धृत साखियों की भाषा की विशेषता स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कबीरदास जी की भाषा की प्रमुख विशेषताएँ निम्नलिखित हैं:</p>\n          <ul>\n            <li><strong>सधुक्कड़ी एवं पंचमेल खिचड़ी:</strong> कबीर देशाटन करने वाले फक्कड़ संत थे। उनकी भाषा में अवधी, ब्रज, भोजपुरी, राजस्थानी, पंजाबी तथा अरबी-फारसी के तद्भव शब्दों का स्वाभाविक संगम मिलता है।</li>\n            <li><strong>गेयता और दोहा छंद:</strong> सभी साखियाँ दोहा छंद में रचित हैं जो अत्यंत सरल, गेय और स्मरणीय हैं।</li>\n            <li><strong>सटीक प्रतीक और रूपक:</strong> कबीर ने कस्तूरी, दीपक, निंदक, विष और अमृत जैसे दैनिक जीवन के प्रभावशाली बिंबों और प्रतीकों का सफल प्रयोग किया है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सधुक्कड़ी/पंचमेल खिचड़ी भाषा व विविध बोलियों का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दोहा छंद, गेयता व प्रतीकात्मकता का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch23-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch23-q8')\">\n      <div class=\"q-num\">प्रश्न 8</div>\n      <div class=\"q-text\">निम्नलिखित पंक्तियों का भाव स्पष्ट कीजिए: (क) 'बिरह भुवंगम तन बसै, मंत्र न लागै कोइ।' (ख) 'जब मैं था तब हरि नहीं, अब हरि हैं मैं नाहिं।'</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>(क) भावार्थ:</strong> जिस व्यक्ति के शरीर में ईश्वर के विरह रूपी भुजंग (साँप) ने अपना डेरा बना लिया हो, उस पर कोई भी मंत्र या दवा असर नहीं करती। वह विरही भक्त या तो जीवित नहीं रहता और यदि जीवित रहता भी है, तो प्रभु-प्रेम में बावला (पागल) सा होकर घूमता है।</p>\n          <p><strong>(ख) भावार्थ:</strong> जब तक मेरे अंतःकरण में 'मैं' अर्थात् अहंकार की भावना विद्यमान थी, तब तक मुझे ईश्वर (हरि) की प्राप्ति नहीं हुई थी। अब जब मुझे ज्ञान रूपी गुरु-कृपा से ईश्वर के दर्शन हो गए हैं, तो मेरा सारा अहंकार स्वतः समाप्त हो गया है। आत्मा और परमात्मा के मिलन में अहंकार ही सबसे बड़ी दीवार है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(क) विरह-सर्प व प्रभु-प्रेम की व्याकुलता का भाव</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ख) अहंकार ('मैं') और ईश्वर ('हरि') की परस्पर विरोधी प्रकृति</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Competency-Based Questions (CBQs) -->\n  <div class=\"cbq-card\">\n    <div class=\"cbq-badge\">CBSE Board Competency-Based Question (योग्यता आधारित प्रश्न)</div>\n    <div class=\"q-text\"><strong>नैतिक व सामाजिक प्रासंगिकता विश्लेषण (Moral Relevance Analysis):</strong> कबीर की साखियों में 'निंदक नेड़ा राखिये' और 'मीठी वाणी' का उपदेश वर्तमान सोशल मीडिया और डिजिटल संवाद के दौर में किस प्रकार सहिष्णुता और मानसिक संतुलन स्थापित करने में सहायक हो सकता है?</div>\n    <div class=\"answer-box\" style=\"margin-top: 15px;\">\n      <div class=\"answer-label\">विशेषज्ञ उत्तर व विश्लेषणात्मक दृष्टिकोण</div>\n      <div class=\"answer-text\">\n        <p><strong>विश्लेषण:</strong> वर्तमान सोशल मीडिया पर लोग असहिष्णुता, ट्रोलिंग और कटु भाषा का प्रयोग कर मानसिक अशांति फैलाते हैं।</p>\n        <p><strong>कबीर की शिक्षा का अनुप्रयोग:</strong> यदि हम कबीर के अनुसार मीठी वाणी का प्रयोग करें और आलोचना (निंदा) को सकारात्मक प्रतिक्रिया (Feedback) के रूप में स्वीकार करें, तो डिजिटल समाज में नफरत का शमन होगा और रचनात्मक संवाद को बढ़ावा मिलेगा।</p>\n      </div>\n    </div>\n  </div>\n</section>","24":"<section class=\"chapter-section\" id=\"ch24\" data-book=\"sparsh-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">24</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (काव्य खंड) — पाठ 2</div>\n      <h2>पद</h2>\n      <p>मीराबाई | राजस्थानी मिश्रित ब्रजभाषा — माधुर्य भाव, अनन्य कृष्ण-भक्ति, दैन्य भाव, रूप-सौंदर्य और आत्म-समर्पण | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch24-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch24-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">पहले पद में मीरा ने हरि से अपनी पीड़ा हरने की विनती किस प्रकार की है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>मीराबाई अपने आराध्य श्रीकृष्ण से दैन्य भाव से पुकारती हैं—<em>\"हरि आप हरो जन री भीर।\"</em></p>\n          <p>वे प्रभु को याद दिलाती हैं कि जिस प्रकार उन्होंने द्रौपदी की लाज बचाने के लिए वस्त्र बढ़ाए, प्रह्लाद की रक्षा के लिए नृसिंह रूप धरा और डूबते गजराज को मगरमच्छ से बचाया; उसी प्रकार वे अपनी दासी मीरा के सांसारिक कष्टों और विरह-वेदना का भी शीघ्र निवारण करें।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">द्रौपदी, प्रह्लाद व गजराज के उद्धार के दृष्टांत</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्वयं की विरह-पीड़ा हरने की कातर प्रार्थना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch24-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch24-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">दूसरे पद में मीराबाई श्याम की चाकरी क्यों करना चाहती हैं? स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>मीराबाई श्रीकृष्ण की सेविका (चाकर) बनकर उनके निकट रहना चाहती हैं—<em>\"स्याम म्हाने चाकर राखो जी।\"</em> चाकरी करने से उन्हें निम्नलिखित तीन अनमोल लाभ प्राप्त होंगे:</p>\n          <ul>\n            <li><strong>नित्य दर्शन का लाभ:</strong> वे प्रभु के लिए बाग-बगीचे लगाएँगी ताकि सुबह उठते ही नित्य उनके दर्शन कर सकें।</li>\n            <li><strong>नाम-स्मरण की पूँजी:</strong> वृंदावन की कुंज-गलियों में श्रीकृष्ण की लीलाओं का गुणगान करेंगी, जिससे उन्हें 'नाम-स्मरण' रूपी जेबखर्च प्राप्त होगा।</li>\n            <li><strong>भाव-भक्ति की जागीर:</strong> उन्हें प्रभु की अनन्य भाव-भक्ति रूपी स्थायी जागीर मिल जाएगी। इस प्रकार उन्हें दर्शन, स्मरण और भक्ति तीनों का परम सुख एक साथ प्राप्त होगा।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बाग लगाने व नित्य दर्शन की लालसा का उल्लेख</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दर्शन, स्मरण (खर्ची) व भाव-भक्ति (जागीर) रूपी त्रिवेणी का विश्लेषण</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch24-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch24-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">मीराबाई ने श्रीकृष्ण के रूप-सौंदर्य का क्या वर्णन किया है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>मीराबाई ने अपने आराध्य श्याम के मनमोहक रूप का चित्रण करते हुए कहा है:</p>\n          <p><em>\"सिर पर मोरमुकुट पीतांबर सोहै, गल बैजंती माला। बिंद्राबन में धेनु चरावे, मोहन मुरली वाला॥\"</em> उनके सिर पर मोरपंखों का मुकुट सुशोभित है, शरीर पर पीले वस्त्र (पीतांबर) शोभा पा रहे हैं और गले में वनफूलों की बैजंती माला लहरा रही है। वे वृंदावन में गायें चराते हैं और होठों पर मधुर मुरली बजाकर सबका मन मोह लेते हैं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मोरमुकुट, पीतांबर व बैजंती माला का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वृंदावन में धेनु चराने व मुरली वादन का सौंदर्य</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch24-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch24-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">मीराबाई की भक्ति-भावना का परिचय दीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>मीराबाई की भक्ति मुख्य रूप से <strong>माधुर्य भाव</strong> और <strong>कांता भाव</strong> (पति-पत्नी संबंध) की है, जिसमें दैन्य और दास्य भाव का भी अद्भुत समन्वय है:</p>\n          <ul>\n            <li>वे श्रीकृष्ण को अपना एकमात्र पति, स्वामी और सर्वस्व मानती हैं (\"मेरे तो गिरधर गोपाल, दूसरो न कोई\")।</li>\n            <li>उनकी भक्ति में लोक-लाज और कुल की मर्यादा का कोई भय नहीं है।</li>\n            <li>वे प्रभु के चरणों में दासी बनकर समर्पित होने में ही अपने जीवन की सार्थकता मानती हैं।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">माधुर्य भाव, अनन्यता व सर्वस्व समर्पण का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दास्य भाव व सांसारिक बंधनों से मुक्ति का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch24-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch24-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">मीराबाई ने अपने पदों में प्रभु के किन-किन भक्तों की रक्षा के उदाहरण दिए हैं?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>मीराबाई ने भगवान श्रीकृष्ण द्वारा भक्तों पर की गई कृपा के तीन पौराणिक उदाहरण दिए हैं:</p>\n          <ol>\n            <li><strong>द्रौपदी:</strong> भरी कौरव सभा में जब दुःशासन चीरहरण कर रहा था, तब प्रभु ने वस्त्र बढ़ाकर उसकी लाज बचाई।</li>\n            <li><strong>भक्त प्रह्लाद:</strong> हिरण्यकश्यप के अत्याचारों से बालक प्रह्लाद की रक्षा करने के लिए प्रभु ने नृसिंह अवतार लिया।</li>\n            <li><strong>ऐरावत (गजराज):</strong> जब मगरमच्छ ने हाथी का पैर पकड़कर उसे गहरे जल में खींच लिया था, तब भगवान ने ग्राह का वध करके गजराज का उद्धार किया।</li>\n          </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तीनों भक्तों (द्रौपदी, प्रह्लाद, गजराज) का स्पष्ट उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भगवान द्वारा संकट निवारण के संदर्भ की व्याख्या</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch24-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch24-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">भाव स्पष्ट कीजिए: 'चाकरी में दरसन पास्यूँ, सुमरण पास्यूँ खरची। भाव भगती जागीरी पास्यूँ, तीनूं बाताँ सरसी॥'</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>भावार्थ:</strong> मीराबाई कहती हैं कि जब वे अपने प्रियतम श्रीकृष्ण की चाकरी (सेवा) करेंगी, तो उन्हें किसी भौतिक धन या वेतन की आवश्यकता नहीं होगी।</p>\n          <p>उन्हें सेवा के बदले नित्य प्रभु के दर्शन का सौभाग्य मिलेगा, नाम-स्मरण के रूप में जीवन-यापन के लिए आध्यात्मिक खर्च प्राप्त होगा और प्रभु की भावपूर्ण भक्ति रूपी अकूत संपत्ति और जागीर सदा के लिए मिल जाएगी। इस प्रकार उन्हें एक ही सेवा से दर्शन, स्मरण और भक्ति तीनों परम लाभ सुलभ हो जाएँगे।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दर्शन व नाम-स्मरण (खर्ची) के आध्यात्मिक वेतन का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाव-भक्ति जागीर की सार्थकता व तीनों लाभों का विवेचन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Competency-Based Questions (CBQs) -->\n  <div class=\"cbq-card\">\n    <div class=\"cbq-badge\">CBSE Board Competency-Based Question (योग्यता आधारित प्रश्न)</div>\n    <div class=\"q-text\"><strong>स्त्री-विमर्श एवं भक्ति कालीन चेतना (Feminist & Devotional Analysis):</strong> मीराबाई का राजसी सुखों का त्याग कर श्रीकृष्ण की अनन्य भक्ति में लीन होना तत्कालीन सामंती पुरुष-प्रधान समाज के विरुद्ध एक मूक एवं सशक्त विद्रोह था। इस कथन की समीक्षा कीजिए।</div>\n    <div class=\"answer-box\" style=\"margin-top: 15px;\">\n      <div class=\"answer-label\">विशेषज्ञ उत्तर व विश्लेषणात्मक दृष्टिकोण</div>\n      <div class=\"answer-text\">\n        <p><strong>समीक्षा:</strong> 16वीं शताब्दी के रूढ़िवादी राजपूत समाज में स्त्रियों के लिए कड़े पर्दे और महलों की चारदीवारी की मर्यादा थी।</p>\n        <p>मीराबाई ने राणा के महलों, आभूषणों और विष के प्याले की परवाह किए बिना संतों के संग बैठकर कीर्तन किया और श्रीकृष्ण को अपना एकमात्र पति घोषित किया। उनका यह कदम तत्कालीन पितृसत्तात्मक समाज के बंधनों को तोड़कर स्त्री की आत्मिक और व्यक्तिगत स्वतंत्रता की घोषणा थी। मीरा भक्ति के माध्यम से आत्म-सम्मान और मुक्ति की अप्रतिम प्रतीक बनीं।</p>\n      </div>\n    </div>\n  </div>\n</section>","25":"<section class=\"chapter-section\" id=\"ch25\" data-book=\"sparsh-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">25</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (काव्य खंड) — पाठ 3</div>\n      <h2>मनुष्यता</h2>\n      <p>मैथिलीशरण गुप्त | खड़ी बोली — परोपकार, विश्व-बंधुत्व, त्याग, आत्म-बलिदान और सच्ची मानवता की प्रेरणा | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch25-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch25-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">कवि ने कैसी मृत्यु को 'सुमृत्य' कहा है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि मैथिलीशरण गुप्त के अनुसार केवल शरीर का नाश होना मृत्यु नहीं है। वे कहते हैं—<em>\"विचार लो कि मर्त्य हो न मृत्यु से डरो कभी, मरो परंतु यों मरो कि याद जो करे सभी।\"</em></p>\n          <p>कवि ने उस मृत्यु को <strong>'सुमृत्य'</strong> (सार्थक और गौरवशाली मृत्यु) कहा है जो परोपकार, जन-कल्याण और सत्य के लिए प्राप्त हो। ऐसा व्यक्ति भले ही शारीरिक रूप से मर जाए, किंतु अपने महान त्याग और आदर्शों के कारण युगों-युगों तक लोगों के दिलों में अमर रहता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">परोपकार व देशहित में प्राणोत्सर्ग का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">संसार द्वारा अमर स्मरण व सुमृत्यु की परिभाषा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch25-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch25-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">उदार व्यक्ति की पहचान कैसे होती है? कविता के आधार पर स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि के अनुसार उदार व्यक्ति वह है जो निस्वार्थ भाव से समस्त सृष्टि से प्रेम करता है और अपना सर्वस्व दूसरों के कल्याण के लिए समर्पित कर देता है।</p>\n          <p>ऐसे उदार व्यक्ति की कीर्ति और यश का गान स्वयं सरस्वती और इतिहास की पुस्तकें करती हैं, धरती उसके प्रति कृतज्ञता व्यक्त करती है और संपूर्ण विश्व उसकी पूजा करता है। उसके मन में अपने-पराए का भेद नहीं होता, वह सबको बंधु मानता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">निस्वार्थ परोपकार व आत्म-समर्पण के लक्षण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सरस्वती, धरा व विश्व द्वारा यश-गान का संदर्भ</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch25-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch25-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">कवि ने दधीचि, कर्ण और उशीनर आदि का उदाहरण देकर क्या संदेश दिया है?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि ने इन ऐतिहासिक व पौराणिक महापुरुषों के माध्यम से परोपकार और त्याग का अमर संदेश दिया है:</p>\n          <ul>\n            <li><strong>ऋषि दधीचि:</strong> उन्होंने देवासुर संग्राम में देवताओं और मानवता की रक्षा के लिए अपनी जीवित हड्डियाँ वज्र बनाने हेतु दान कर दीं।</li>\n            <li><strong>उशीनर (राजा शिबि):</strong> उन्होंने कबूतर के प्राणों की रक्षा के लिए अपने शरीर का मांस काटकर बाज को दे दिया।</li>\n            <li><strong>दानवीर कर्ण:</strong> उन्होंने याचक के प्राणों की रक्षा के लिए अपने शरीर से जुड़ा जन्मजात कवच और कुंडल भी हँसते-हँसते दान कर दिया।</li>\n            <li><strong>संदेश:</strong> यह नश्वर शरीर एक दिन नष्ट हो जाना है, अतः इस क्षणभंगुर देह के मोह में न पड़कर दूसरों के जीवन की रक्षा के लिए अपना सर्वस्व न्योछावर कर देना ही सच्चा मानव धर्म है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दधीचि, शिबि व कर्ण के त्याग के दृष्टांतों का उल्लेख</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नश्वर देह से परे अमर परोपकार का संदेश</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch25-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch25-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">कवि ने किन पंक्तियों में यह व्यक्त किया है कि हमें गर्व-रहित जीवन व्यतीत करना चाहिए?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि ने निम्नलिखित पंक्तियों में धन और संपदा के मद में अहंकार न करने की चेतावनी दी है:</p>\n          <p><em>\"रहो न भूल के कभी मदांध तुच्छ वित्त में,<br>सनाथ जान आपको करो न गर्व चित्त में।<br>अनाथ कौन है यहाँ? त्रिलोकनाथ साथ हैं,<br>दयालु दीनबंधु के बड़े विशाल हाथ हैं।\"</em></p>\n          <p>कवि समझाते हैं कि धन अत्यंत तुच्छ है, इसके घमंड में कभी अंधे नहीं होना चाहिए। इस संसार में कोई भी अनाथ और असहाय नहीं है, क्योंकि उस परमपिता परमेश्वर के कृपालु हाथ सबके सिर पर हैं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">संबंधित पंक्तियों का सटीक उद्धरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तुच्छ धन के घमंड त्याग व 'त्रिलोकनाथ' की सर्वव्यापकता का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch25-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch25-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">'मनुष्य मात्र बंधु है' से आप क्या समझते हैं? स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि के अनुसार—<em>\"मनुष्य मात्र बंधु है, यही बड़ा विवेक है।\"</em></p>\n          <p>इसका अर्थ यह है कि इस धरती के सभी मनुष्य एक ही ईश्वर (परमपिता) की संतान हैं। बाहरी रूप से कर्मों, जातियों, देशों और भाषाओं के आधार पर भेद भले ही दिखाई दें, किंतु अंतरात्मा में सभी एक समान हैं। यदि एक भाई दूसरे भाई के काम न आए, उसके कष्टों को न हरे, तो उसका मनुष्य होना व्यर्थ है। अतः विश्व-बंधुत्व की यह भावना ही सबसे बड़ा विवेक है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">एक ही परमपिता की संतान होने का दार्शनिक आधार</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">परस्पर बंधुत्व व कष्ट निवारण के दायित्व की व्याख्या</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch25-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch25-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">कवि ने सबको एक साथ चलने की प्रेरणा क्यों दी है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि कहते हैं—<em>\"चलो अभीष्ट मार्ग में सहर्ष खेलते हुए, विपत्ति-विप्र जो पड़ें उन्हें ढकेलते हुए।\"</em></p>\n          <p>कवि ने सबको एक साथ मिलकर आगे बढ़ने की प्रेरणा इसलिए दी है ताकि समाज में किसी प्रकार का भेदभाव, ईर्ष्या या अलगाव न पनपे। जब सभी लोग कदम से कदम मिलाकर चलेंगे, तो मार्ग की सारी बाधाएँ और विपत्तियाँ आसानी से दूर हो जाएँगी। सबकी सामूहिक प्रगति में ही प्रत्येक व्यक्ति का सच्चा कल्याण निहित है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भेदभाव मिटाने व एकता की शक्ति का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सामूहिक प्रगति व बाधाओं पर विजय का तर्क</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch25-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch25-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">व्यक्ति को किस प्रकार का जीवन व्यतीत करना चाहिए? इस कविता के आधार पर बताइए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>'मनुष्यता' कविता के अनुसार व्यक्ति को ऐसा जीवन जीना चाहिए जो केवल अपने तक सीमित न हो:</p>\n          <ul>\n            <li>पशुओं की तरह केवल अपनी चारागाह की चिंता न करे, बल्कि दूसरों की भलाई के लिए जिए (\"वही मनुष्य है कि जो मनुष्य के लिए मरे\")।</li>\n            <li>दूसरों के दुखों के प्रति गहरी सहानुभूति और करुणा रखे।</li>\n            <li>धन-दौलत के घमंड से दूर रहकर सबको अपना बंधु समझे और प्रेमभाव से जीवन पथ पर आगे बढ़े।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पशु-प्रवृत्ति (स्वार्थ) त्यागने का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">परोपकार, सहानुभूति व बंधुत्वपूर्ण जीवन का प्रतिपादन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch25-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch25-q8')\">\n      <div class=\"q-num\">प्रश्न 8</div>\n      <div class=\"q-text\">भाव स्पष्ट कीजिए: 'सहानुभूति चाहिए, महाविभूति है वही; वशीकृता सदैव है बनी हुई मही।'</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>भावार्थ:</strong> कवि कहते हैं कि दूसरों के दुख-दर्द को अपना समझकर उनके प्रति गहरी संवेदना (सहानुभूति) रखना ही मनुष्य की सबसे बड़ी पूँजी और धन (महाविभूति) है।</p>\n          <p>जिस मनुष्य के हृदय में करुणा और दया होती है, समस्त पृथ्वी और उसके प्राणी उसके वश में हो जाते हैं। भगवान बुद्ध ने भी पारंपरिक नियमों का विरोध कर केवल दया और करुणा के बल पर ही पूरे संसार को अपने प्रेम के समक्ष नतमस्तक कर लिया था।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सहानुभूति को वास्तविक धन (महाविभूति) बताने का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">करुणा द्वारा संसार को जीतने (बुद्ध का उदाहरण) की व्याख्या</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Competency-Based Questions (CBQs) -->\n  <div class=\"cbq-card\">\n    <div class=\"cbq-badge\">CBSE Board Competency-Based Question (योग्यता आधारित प्रश्न)</div>\n    <div class=\"q-text\"><strong>वैश्विक नागरिकता एवं बंधुत्व (Global Citizenship & Fraternity):</strong> 'मनुष्य मात्र बंधु है, यही बड़ा विवेक है' की अवधारणा आज के भू-राजनीतिक तनाव, युद्ध और शरणार्थी संकट के संदर्भ में संयुक्त राष्ट्र (UN) के 'वसुधैव कुटुम्बकम्' के आदर्श से किस प्रकार मेल खाती है?</div>\n    <div class=\"answer-box\" style=\"margin-top: 15px;\">\n      <div class=\"answer-label\">विशेषज्ञ उत्तर व विश्लेषणात्मक दृष्टिकोण</div>\n      <div class=\"answer-text\">\n        <p><strong>विश्लेषण:</strong> मैथिलीशरण गुप्त जी की यह कविता संकीर्ण राष्ट्रवाद और सीमाओं से परे जाकर संपूर्ण मानव जाति को एक परिवार मानती है।</p>\n        <p>वर्तमान समय में जब देश युद्ध और हथियारों की होड़ में उलझे हैं, तब 'मनुष्य मात्र बंधु है' का मंत्र यह स्मरण कराता है कि किसी भी निर्दोष मनुष्य का रक्त बहना संपूर्ण मानवता की पराजय है। विश्व शांति और सतत विकास के लिए प्रत्येक देश को इस सार्वभौमिक बंधुत्व को अपनी विदेश नीति और जीवन का मूल आधार बनाना होगा।</p>\n      </div>\n    </div>\n  </div>\n</section>","26":"<section class=\"chapter-section\" id=\"ch26\" data-book=\"sparsh-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">26</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (काव्य खंड) — पाठ 4</div>\n      <h2>पर्वत प्रदेश में पावस</h2>\n      <p>सुमित्रानंदन पंत | छायावादी कविता — पर्वतीय वर्षा ऋतु का जादुई सौंदर्य, मानवीकरण अलंकार, नाद-सौंदर्य और इंद्रजाल | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch26-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch26-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">पावस ऋतु में प्रकृति में क्या-क्या परिवर्तन आते हैं? कविता के आधार पर स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>पर्वतीय प्रदेश में वर्षा ऋतु में प्रकृति का रूप पल-पल बदलता रहता है:</p>\n          <ul>\n            <li>पर्वतों पर खिले सहस्रों फूल पर्वत की आँखों के समान प्रतीत होते हैं और नीचे फैला शांत तालाब दर्पण जैसा दिखाई देता है।</li>\n            <li>मोतियों की लड़ियों जैसे चमकते झरने कलकल ध्वनि में पर्वत के गौरव का गान करते हैं।</li>\n            <li>अचानक बादलों के घिर आने से ऐसा लगता है मानो पर्वत पंख लगाकर उड़ गए हों। धुआँ उठने से लगता है कि तालाब में आग लग गई हो और आकाश धरती पर टूट पड़ा हो। प्रकृति एक जादुई खेल दिखाती प्रतीत होती है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पल-पल बदलते प्राकृतिक परिवेश का चित्रण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">झरने, बादल, धुआँ व तालाब के परिवर्तनों का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch26-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch26-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">'मेखलाकार' शब्द का क्या अर्थ है? कवि ने इस शब्द का प्रयोग यहाँ क्यों किया है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>'मेखलाकार' का अर्थ:</strong> करधनी (कमर में बाँधने वाला गहना) के आकार का गोल या अर्द्धवृत्ताकार घेरा।</p>\n          <p><strong>प्रयोग का कारण:</strong> पर्वतीय प्रदेश में पर्वत श्रृंखलाएँ सीधी न होकर गोलाकार रूप में दूर-दूर तक फैली हुई थीं। वे धरती की कमर में बंधी करधनी की भाँति विशाल और वक्राकार प्रतीत हो रही थीं। पर्वत की उस भव्य विशालता और घुमावदार ढलान को सजीव चित्रित करने के लिए कवि ने इस सुंदर बिंब का प्रयोग किया है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">करधनी के आकार (शाब्दिक अर्थ) का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पर्वत की घुमावदार विशालता के सजीव बिंब का स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch26-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch26-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">'सहस्र दृग-सुमन' से क्या तात्पर्य है? कवि ने इस पद का प्रयोग किसके लिए किया है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>तात्पर्य:</strong> 'सहस्र' अर्थात् हज़ारों, 'दृग' अर्थात् आँखें और 'सुमन' अर्थात् फूल। इसका तात्पर्य है—<strong>'हज़ारों नेत्र रूपी फूल'</strong> (रूपक अलंकार)।</p>\n          <p><strong>प्रयोग का संदर्भ:</strong> कवि ने इस पद का प्रयोग पर्वत पर खिले अनगिनत जंगली फूलों के लिए किया है। मानवीकरण करते हुए कवि कल्पना करता है कि पर्वत उन हज़ारों पुष्प-रूपी आँखों से अपने चरणों में फैले विशाल तालाब के स्वच्छ जल में अपने विशालकाय रूप को विस्मय से निहार रहा है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पुष्प रूपी नेत्रों के अर्थ व रूपक का स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पर्वत द्वारा अपने रूप को निहारने के मानवीकरण का संदर्भ</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch26-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch26-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">कवि ने तालाब की समानता किसके साथ दिखाई है और क्यों?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि ने पर्वत के चरणों में स्थित तालाब की समानता एक <strong>विशाल दर्पण (आईने)</strong> से की है—<em>\"दर्पण-सा फैला है विशाल।\"</em></p>\n          <p><strong>कारण:</strong> तालाब का जल अत्यंत निर्मल, शांत, पारदर्शी और स्वच्छ है। जिस प्रकार दर्पण में व्यक्ति का संपूर्ण बिंब साफ़ दिखाई देता है, उसी प्रकार उस शांत जल में पर्वत और उसके ऊपर खिले फूलों का भव्य प्रतिबिंब हूबहू दिखाई दे रहा है, मानो वह पर्वत के लिए ही आईना बनकर फैला हो।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दर्पण/आईने से समानता का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">निर्मल जल व पर्वत के प्रतिबिंब की तार्किक व्याख्या</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch26-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch26-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">पर्वत के हृदय से उठ-उठकर ऊँचे वृक्ष आकाश की ओर क्यों देख रहे थे और वे किस बात को प्रतिबिंबित करते हैं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>पर्वत के सीने पर उगे ऊँचे-ऊँचे शाल के वृक्ष शांत आकाश की ओर एकटक (अनिमेष), स्थिर और चिंतामग्न भाव से देख रहे हैं।</p>\n          <p>वे पर्वत के हृदय में उठने वाली <strong>उच्चाकांक्षाओं</strong> (ऊँचा उठने की तीव्र इच्छाओं) को प्रतिबिंबित करते हैं। वे मानव मन की उस अदम्य लालसा का प्रतीक हैं जो सदैव अपनी वर्तमान सीमाओं को लांघकर और अधिक ऊँचाई प्राप्त करने के लिए मौन साधना में लीन रहता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अनिमेष व चिंतामग्न होकर आकाश देखने का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मानवीय उच्चाकांक्षाओं व साधना के प्रतीकार्थ की व्याख्या</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch26-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch26-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">शाल के वृक्ष भयभीत होकर धरती में क्यों धँस गए प्रतीत होते हैं?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>अचानक मूसलाधार वर्षा शुरू हो गई और बादलों का ऐसा घना कोहरा छाया कि पूरा पर्वत और आकाश गायब हो गए। चारों ओर घनघोर अंधकार छा गया और केवल झरनों का शोर सुनाई देने लगा।</p>\n          <p>प्रकृति के इस भयानक और रौद्र रूप को देखकर ऐसा प्रतीत हुआ मानो आकाश धरती पर टूट पड़ा हो। इस भयंकर उत्पात से डरकर शाल के ऊँचे वृक्ष भयभीत होकर धरती में धँस गए हों और कोहरे में छिप गए हों।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">घने कोहरे, मूसलाधार वर्षा व अंधकार का वातावरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भयभीत होकर धरती में धँसने के उत्प्रेक्षा/मानवीकरण का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch26-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch26-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">झरने किसके गौरव का गान कर रहे हैं? बहते हुए झरने की तुलना किससे की गई है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>पहाड़ों से गिरते हुए झरने अपनी कल-कल, छल-छल ध्वनि के माध्यम से <strong>विशाल पर्वत के उच्च गौरव और महानता का गान</strong> कर रहे हैं।</p>\n          <p>कवि ने फेन उगलते और तेज़ी से बहते हुए दूधिया झरनों की तुलना <strong>'मोतियों की चमकदार लड़ियों'</strong> से की है—<em>\"मोतियों की लड़ियों से सुंदर, झरते हैं झाग भरे निर्झर।\"</em> ये झरने पर्वतों के सीने से निकलकर दर्शकों की नसों में नया उत्साह और स्फूर्ति भर देते हैं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पर्वत के गौरव गान का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मोतियों की लड़ियों से तुलना व झाग भरे सौंदर्य का चित्रण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch26-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch26-q8')\">\n      <div class=\"q-num\">प्रश्न 8</div>\n      <div class=\"q-text\">भाव स्पष्ट कीजिए: 'इंद्र खेलता था इंद्रजाल!' तथा 'है टूट पड़ा भू पर अंबर!'</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>(क) 'इंद्र खेलता था इंद्रजाल':</strong> वर्षा के देवता इंद्र बादल रूपी यान (विमान) पर बैठकर आकाश में घूम-घूमकर पल-पल नए जादुई दृश्य रच रहे थे। कभी धूप, कभी मूसलाधार वर्षा, कभी धुंध तो कभी बादलों में पर्वतों का गायब हो जाना—यह सब किसी बाज़ीगर के तिलिस्म (इंद्रजाल) जैसा विस्मयकारी लग रहा था।</p>\n          <p><strong>(ख) 'है टूट पड़ा भू पर अंबर':</strong> मूसलाधार वर्षा का वेग इतना प्रचंड और भयंकर था कि ऐसा प्रतीत हुआ मानो स्वयं समूचा आकाश धरती पर गिर पड़ा हो और बाणों की भाँति जल की अनवरत धाराएँ धरती पर प्रहार कर रही हों।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(क) इंद्र के विमान व प्रकृति के जादुई खेल (इंद्रजाल) का भाव</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ख) मूसलाधार वर्षा के रौद्र रूप व आकाश टूटने का अतिशयोक्तिपूर्ण सौंदर्य</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Competency-Based Questions (CBQs) -->\n  <div class=\"cbq-card\">\n    <div class=\"cbq-badge\">CBSE Board Competency-Based Question (योग्यता आधारित प्रश्न)</div>\n    <div class=\"q-text\"><strong>छायावादी सौंदर्यशास्त्र एवं पर्यावरण बोध (Aesthetics & Eco-Consciousness):</strong> सुमित्रानंदन पंत को 'प्रकृति का सुकुमार कवि' क्यों कहा जाता है? 'पर्वत प्रदेश में पावस' के आधार पर विश्लेषण कीजिए कि छायावादी कवियों की दृष्टि प्रकृति को केवल वस्तु न मानकर सजीव चेतन सत्ता के रूप में कैसे देखती है?</div>\n    <div class=\"answer-box\" style=\"margin-top: 15px;\">\n      <div class=\"answer-label\">विशेषज्ञ उत्तर व विश्लेषणात्मक दृष्टिकोण</div>\n      <div class=\"answer-text\">\n        <p><strong>विश्लेषण:</strong> पंत जी ने कविता में प्रकृति के जड़ रूपों (पर्वत, फूल, वृक्ष, झरने) को मानवीकरण अलंकार के माध्यम से सजीव मानवीय क्रियाओं में संलग्न दिखाया है:</p>\n        <ul>\n          <li>पर्वत आँखों से अपने सौंदर्य को निहारता है, झरने गौरव-गान करते हैं और वृक्ष आकाश की ओर मौन चिंता में लीन हैं।</li>\n          <li>यह दृष्टि प्रकृति के साथ एकात्मता स्थापित करती है। आज जब मनुष्य प्रकृति को केवल उपभोग की वस्तु मानकर उसका विनाश कर रहा है, पंत जी का यह प्रकृति-प्रेम हमें पर्यावरण के प्रति संवेदनशील और आदरयुक्त बनने की प्रेरणा देता है।</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n</section>","27":"<section class=\"chapter-section\" id=\"ch27\" data-book=\"sparsh-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">27</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (काव्य खंड) — पाठ 5</div>\n      <h2>तोप</h2>\n      <p>वीरेन डंगवाल | समकालीन कविता — 1857 की ऐतिहासिक तोप, कंपनी बाग, साम्राज्यवाद की क्षणभंगुरता और शांति का संदेश | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch27-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch27-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">कंपनी बाग में रखी तोप क्या संदेश देती है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कंपनी बाग में रखी 1857 की तोप दो अत्यंत महत्त्वपूर्ण ऐतिहासिक संदेश देती है:</p>\n          <ul>\n            <li><strong>अतीत की भूलों से चेतावनी:</strong> ईस्ट इंडिया कंपनी व्यापार करने आई थी किंतु उसने भारतीयों की फूट का लाभ उठाकर देश को गुलाम बना लिया। हमें भविष्य में किसी भी विदेशी षड्यंत्र के प्रति सदैव सजग रहना चाहिए।</li>\n            <li><strong>सत्ता और हिंसा की क्षणभंगुरता:</strong> चाहे कोई शक्ति या तोप कितनी भी क्रूर और शक्तिशाली क्यों न हो, एक न एक दिन उसका अंत निश्चित है। अंततः शांति, मासूमियत और आम जनता की ही विजय होती है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">विदेशी षड्यंत्रों से सजग रहने की चेतावनी</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शक्ति व हिंसा के अंत तथा शांति की विजय का संदेश</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch27-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch27-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">तोप को कब और कहाँ रखा गया था? वह क्या याद दिलाती है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>यह तोप <strong>1857 के प्रथम स्वतंत्रता संग्राम</strong> की है और इसे कानपुर के कंपनी बाग के मुख्य प्रवेश द्वार पर विरासत के रूप में संभालकर रखा गया है।</p>\n          <p>यह तोप हमें याद दिलाती है कि कभी यह अत्यंत शक्तिशाली थी और इसने स्वतंत्रता सेनानी सूरमाओं के परखच्चे उड़ा दिए थे। साथ ही यह ब्रिटिश ईस्ट इंडिया कंपनी द्वारा भारतीयों पर ढाए गए अमानवीय जुल्मों और स्वतंत्रता सेनानियों के अमर बलिदान की स्मृति कराती है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">1857 व कंपनी बाग के प्रवेश द्वार का संदर्भ</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">क्रूरता, स्वतंत्रता संग्राम व अमर बलिदान की स्मृति</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch27-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch27-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">तोप की वर्तमान स्थिति क्या है? कविता के आधार पर वर्णन कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>वर्तमान समय में वह भयंकर तोप पूरी तरह निष्प्रभावी, शांत और खिलौना बनकर रह गई है:</p>\n          <ul>\n            <li>अब कंपनी बाग में घूमने आने वाले छोटे बच्चे उसकी पीठ पर बैठकर घुड़सवारी का आनंद लेते हैं।</li>\n            <li>जब बच्चे हट जाते हैं, तो गौरैया और अन्य चिड़ियाँ उसके ऊपर बैठकर गपशप करती हैं और बेधड़क उसके खुले मुँह के भीतर घुस जाती हैं।</li>\n            <li>वर्ष में दो बार (26 जनवरी और 15 अगस्त) उसकी साफ-सफाई व चमकाने का औपचारिक कार्य किया जाता है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बच्चों की घुड़सवारी व चिड़ियों की गपशप का चित्रण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">राष्ट्रीय पर्वों पर चमकाने व खिलौना बन जाने की स्थिति</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch27-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch27-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">चिड़ियाँ तोप के ऊपर बैठकर क्या दर्शाती हैं?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>चिड़ियों का तोप के ऊपर बैठना और उसके मुँह के भीतर घुस जाना यह दर्शाता है कि <strong>तोप की संहारक शक्ति अब पूरी तरह समाप्त हो चुकी है</strong>।</p>\n          <p>यह दृश्य हिंसा पर अहिंसा और विनाशकारी हथियारों पर जीवन की सहज मासूमियत की विजय को रेखांकित करता है। यह सिद्ध करता है कि कोई भी दमनकारी शक्ति हमेशा नहीं टिक सकती, अंत में जीवन, स्वतंत्रता और शांति ही स्थायी रूप से फलती-फूलती है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तोप की शक्ति शून्यता का निरूपण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हिंसा पर मासूमियत व शांति की विजय का प्रतीकार्थ</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch27-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch27-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">भाव स्पष्ट कीजिए: 'तोप कितनी भी बड़ी हो, एक दिन तो होना ही है उसका मुँह बंद।'</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>भावार्थ:</strong> कवि यह शाश्वत ऐतिहासिक सत्य उद्घाटित करते हैं कि अहंकार, तानाशाही और विनाशकारी अस्त्र-शस्त्रों का बल चाहे कितना भी प्रचंड क्यों न हो, वह कभी अमर नहीं हो सकता।</p>\n          <p>इतिहास गवाह है कि बड़े-बड़े क्रूर शासकों, अत्याचारियों और साम्राज्यवादी ताकतों की बंदूकें और तोपें एक दिन हमेशा के लिए खामोश हो जाती हैं। अंततः सत्य, मानवीय प्रेम और आम जनता की जीवटता ही अमर रहती है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तानाशाही व सैन्य शक्ति के अनिवार्य पतन का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सत्य व मानवीय चेतना की अमरता का प्रतिपादन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Competency-Based Questions (CBQs) -->\n  <div class=\"cbq-card\">\n    <div class=\"cbq-badge\">CBSE Board Competency-Based Question (योग्यता आधारित प्रश्न)</div>\n    <div class=\"q-text\"><strong>हथियारों की होड़ बनाम वैश्विक शांति (Disarmament & World Peace):</strong> 'तोप कितनी भी बड़ी हो, एक दिन तो होना ही है उसका मुँह बंद।' वर्तमान समय में विश्व के शक्तिशाली देशों के बीच चल रही परमाणु और मिसाइल प्रतिस्पर्धा के संदर्भ में इस पंक्ति की दार्शनिक प्रासंगिकता की विवेचना कीजिए।</div>\n    <div class=\"answer-box\" style=\"margin-top: 15px;\">\n      <div class=\"answer-label\">विशेषज्ञ उत्तर व विश्लेषणात्मक दृष्टिकोण</div>\n      <div class=\"answer-text\">\n        <p><strong>विवेचना:</strong> वर्तमान वैश्विक परिदृश्य में राष्ट्र अपनी सुरक्षा के नाम पर संहारक परमाणु अस्त्रों का जखीरा तैयार कर रहे हैं।</p>\n        <p>वीरेन डंगवाल की यह कविता विश्व शक्तियों को आईना दिखाती है कि विनाशकारी हथियार कभी स्थायी सुरक्षा या शांति की गारंटी नहीं बन सकते। जिस प्रकार 1857 की तोप आज चिड़ियों का बसेरा बन चुकी है, उसी प्रकार आधुनिक हथियारों की होड़ भी अंततः व्यर्थ सिद्ध होगी। वैश्विक मानवता का कल्याण केवल निःशस्त्रीकरण, संवाद और शांतिपूर्ण सह-अस्तित्व में ही संभव है।</p>\n      </div>\n    </div>\n  </div>\n</section>","28":"<section class=\"chapter-section\" id=\"ch28\" data-book=\"sparsh-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">28</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (काव्य खंड) — पाठ 6</div>\n      <h2>कर चले हम फ़िदा</h2>\n      <p>कैफ़ी आज़मी | देशभक्ति गीत (फिल्म 'हकीकत', 1962 भारत-चीन युद्ध) — सैनिकों का आत्म-बलिदान, देश-प्रेम और नई पीढ़ी को देश-रक्षा का दायित्व | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch28-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch28-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">'सर हिमालय का हमने न झुकने दिया'—इस पंक्ति में हिमालय किस बात का प्रतीक है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>इस पंक्ति में हिमालय <strong>भारत देश के मान, सम्मान, स्वाभिमान और संप्रभुता</strong> का सर्वोच्च प्रतीक है।</p>\n          <p>सैनिकों ने अपने प्राणों का बलिदान देकर भी शत्रु को हिमालय की बर्फीली चोटियों पर पाँव नहीं पसारने दिए। उन्होंने अपने शीश कटवा लिए किंतु भारत माता के मस्तक रूपी हिमालय को शत्रु के आगे झुकने नहीं दिया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हिमालय के राष्ट्रीय स्वाभिमान व गौरव का प्रतीक होना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्राण देकर भी सीमा सुरक्षा व मान अक्षुण्ण रखने की व्याख्या</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch28-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch28-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">इस गीत की ऐतिहासिक पृष्ठभूमि क्या है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>यह अमर देशभक्ति गीत <strong>1962 के भारत-चीन युद्ध</strong> की ऐतिहासिक पृष्ठभूमि पर चेतन आनंद द्वारा बनाई गई फिल्म <em>'हकीकत'</em> के लिए कैफ़ी आज़मी द्वारा लिखा गया था।</p>\n          <p>लद्दाख की बर्फीली घाटियों में विषम परिस्थितियों और सीमित संसाधनों के बावजूद चीनी सेना के भारी आक्रमण के सामने डटे रहकर अंतिम साँस तक मातृभूमि की रक्षा करने वाले भारतीय वीर सैनिकों के अदम्य शौर्य और बलिदान को यह गीत वाणी देता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">1962 भारत-चीन युद्ध व फिल्म 'हकीकत' का संदर्भ</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">लद्दाख की सीमा पर सैनिकों के बलिदान का ऐतिहासिक निरूपण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch28-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch28-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">गीत में 'धरती को दुल्हन' क्यों कहा गया है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>भारतीय संस्कृति में दुल्हन लाल जोड़े में सजती है और उसकी लाज व सम्मान की रक्षा करना दूल्हे का परम कर्तव्य होता है।</p>\n          <p>सैनिकों ने मातृभूमि की रक्षा करते हुए अपने रक्त की आहुति दी है, जिससे धरती वीरों के खून से लाल हो गई है। ऐसा लगता है मानो सैनिकों ने अपने रक्त से मातृभूमि रूपी दुल्हन को लाल चुनरी ओढ़ा दी हो। सैनिक अपनी दुल्हन (धरती) के मान-सम्मान की रक्षा के लिए अपने प्राण न्योछावर कर रहे हैं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">रक्त से धरती के लाल होने व लाल जोड़े का रूपक</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दुल्हन के सम्मान की रक्षा हेतु प्राणोत्सर्ग की व्याख्या</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch28-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch28-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">सैनिकों के अनुसार 'ज़िंदगी मौत से गले मिल रही है' का क्या तात्पर्य है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>युद्धभूमि में वीर सैनिक मौत को कोई भय या दुख का कारण नहीं मानते, बल्कि मातृभूमि के लिए अपने प्राण न्योछावर करने को एक पावन उत्सव मानते हैं।</p>\n          <p>सैनिक मृत्यु का आलिंगन उसी उत्साह और उल्लास से कर रहे हैं जैसे कोई प्रिय मित्र से गले मिलता है। यह कथन सैनिकों के अदम्य साहस, आत्म-बलिदान के अद्वितीय आनंद और देश-प्रेम की पराकाष्ठा को व्यक्त करता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मौत को भय न मानकर सहर्ष स्वीकार करने का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मातृभूमि के लिए प्राणोत्सर्ग के उल्लास का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch28-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch28-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">'खींच दो अपने खूँ से ज़मीं पर लकीर, इस तरफ़ आने पाए न रावण कोई'—पंक्ति का भावार्थ स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>भावार्थ:</strong> यहाँ 'रावण' विदेशी आक्रांताओं और शत्रुओं का प्रतीक है, और 'लकीर' लक्ष्मण रेखा की भाँति अभेद्य सुरक्षा का प्रतीक है।</p>\n          <p>बलिदानी सैनिक अपने देशवासियों और युवा साथियों का आह्वान करते हैं कि वे अपने रक्त से सीमा पर ऐसी अभेद्य लक्ष्मण रेखा खींच दें जिसे पार करने का दुस्साहस कोई भी शत्रु रूपी रावण न कर सके। यदि कोई शत्रु हमारी मातृभूमि रूपी सीता की पवित्रता पर कुदृष्टि डाले, तो उसका हाथ तुरंत काट दिया जाए।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">रावण (शत्रु) व लकीर (लक्ष्मण रेखा) के प्रतीकार्थ</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मातृभूमि की अखंडता हेतु रक्त से सुरक्षा रेखा खींचने का आह्वान</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch28-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch28-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">सैनिकों ने देशवासियों से क्या उम्मीदें रखी हैं?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>जाते-जाते बलिदानी सैनिकों ने देशवासियों और नई पीढ़ी से निम्नलिखित आशाएँ रखी हैं:</p>\n          <ul>\n            <li>देश की स्वतंत्रता, अखंडता और सम्मान की रक्षा का दायित्व अब देशवासियों के कंधों पर है (\"अब तुम्हारे हवाले वतन साथियों\")।</li>\n            <li>देश के लिए बलिदान देने वालों का काफिला कभी रुकना नहीं चाहिए।</li>\n            <li>मातृभूमि की रक्षा के लिए हर नागरिक अपने व्यक्तिगत सुखों का त्याग करने और सीने पर गोली खाने को तत्पर रहे।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">देश-रक्षा की बागडोर नई पीढ़ी को सौंपने का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बलिदान के काफिले को निरंतर जारी रखने की उम्मीद</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Competency-Based Questions (CBQs) -->\n  <div class=\"cbq-card\">\n    <div class=\"cbq-badge\">CBSE Board Competency-Based Question (योग्यता आधारित प्रश्न)</div>\n    <div class=\"q-text\"><strong>नागरिक चेतना एवं राष्ट्र निर्माण (Civic Duty & Nation Building):</strong> 'कर चले हम फ़िदा' में सीमा पर तैनात सैनिक अपना सर्वस्व बलिदान कर रहे हैं। शांतिकालीन समय में एक सामान्य नागरिक या विद्यार्थी के रूप में आप देश-सेवा में अपना क्या योगदान दे सकते हैं?</div>\n    <div class=\"answer-box\" style=\"margin-top: 15px;\">\n      <div class=\"answer-label\">विशेषज्ञ उत्तर व विश्लेषणात्मक दृष्टिकोण</div>\n      <div class=\"answer-text\">\n        <p><strong>विश्लेषण:</strong> देश-सेवा केवल सीमा पर बंदूक थामकर ही नहीं होती, बल्कि शांतिकाल में एक जिम्मेदार नागरिक के रूप में अपने कर्तव्यों का निष्ठापूर्वक पालन करना भी सच्ची देशभक्ति है:</p>\n        <ul>\n          <li>एक विद्यार्थी के रूप में लगन से पढ़ाई कर वैज्ञानिक, तकनीकी और आर्थिक प्रगति में योगदान देना।</li>\n          <li>पर्यावरण संरक्षण, स्वच्छता और जल-संरक्षण के प्रति सजग रहना।</li>\n          <li>जाति, धर्म और क्षेत्रवाद की संकीर्णताओं से ऊपर उठकर सामाजिक सौहार्द और राष्ट्रीय एकता को सुदृढ़ बनाना।</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n</section>","29":"<section class=\"chapter-section\" id=\"ch29\" data-book=\"sparsh-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">29</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (काव्य खंड) — पाठ 7</div>\n      <h2>आत्मत्राण</h2>\n      <p>रवींद्रनाथ ठाकुर (अनुवाद: आचार्य हजारीप्रसाद द्विवेदी) | प्रार्थना गीत — आत्म-निर्भरता, पुरुषार्थ, संशय-मुक्ति और संकटों से जूझने का आत्मिक संबल | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch29-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch29-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">कवि ईश्वर से विपदाओं से मुक्ति की प्रार्थना क्यों नहीं करता?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि ईश्वर से संकटों को टालने या उनसे भागने की भीख नहीं माँगता, क्योंकि वह कायर और परावलंबी नहीं बनना चाहता।</p>\n          <p>कवि चाहता है कि उसके जीवन में चाहे जैसी भी कठिन और विकट परिस्थितियाँ आएँ, वह उनसे भयभीत न हो। वह ईश्वर से केवल इतना आत्मिक बल और साहस माँगता है कि वह अपने पुरुषार्थ और आत्म-विश्वास के बल पर हर विपत्ति पर विजय प्राप्त कर सके।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">परावलंबन व कायरता के विरोध का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">विपदाओं पर स्वयं विजय पाने हेतु आत्म-बल माँगने का तर्क</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch29-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch29-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">'आत्मत्राण' शीर्षक का अर्थ स्पष्ट कीजिए। यह कविता सामान्य प्रार्थना गीतों से किस प्रकार भिन्न है?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>'आत्मत्राण' का अर्थ:</strong> 'आत्म' अर्थात् स्वयं और 'त्राण' अर्थात् रक्षा या मुक्ति। इसका अर्थ है—<strong>'स्वयं अपनी रक्षा करना'</strong> या आत्मिक शक्ति द्वारा संकटों से पार पाना।</p>\n          <p><strong>सामान्य प्रार्थना गीतों से भिन्नता:</strong></p>\n          <ul>\n            <li>सामान्य प्रार्थना गीतों में भक्त ईश्वर से धन, सुख, विपत्तियों का नाश और रोगों से मुक्ति की याचना करता है और ईश्वर पर पूर्णतः निर्भर हो जाता है।</li>\n            <li>किंतु 'आत्मत्राण' में कवि ईश्वर से कोई सांसारिक लाभ या दुख-निवारण नहीं माँगता। वह दुख और हानि को सहने की अदम्य आत्मिक शक्ति और निर्भयता की याचना करता है। यह प्रार्थना मनुष्य के स्वाभिमान और पुरुषार्थ को जाग्रत करती है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">'आत्मत्राण' का सटीक शाब्दिक व दार्शनिक अर्थ</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सामान्य प्रार्थना (याचना) बनाम आत्मत्राण (पुरुषार्थ/शक्ति) की तुलना</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch29-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch29-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">कवि विपत्ति के समय प्रभु से क्या याचना करता है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि विपत्ति के समय ईश्वर से निम्नलिखित विनम्र याचनाएँ करता है:</p>\n          <ul>\n            <li>विपत्तियों के समय उसके मन में कभी भय का संचार न हो (\"विपदाओं से मुझे बचाओ, यह मेरी प्रार्थना नहीं—केवल सब विपदाओं में न पाऊँ भय\")।</li>\n            <li>यदि कोई सांत्वना देने वाला या सहायक न मिले, तो भी उसका अपना पराक्रम और आत्म-विश्वास न डगमगाए।</li>\n            <li>संसार में केवल हानि या वंचना (धोखा) मिलने पर भी उसके मन में निराशा का वास न हो।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">निर्भयता व आत्म-विश्वास बनाए रखने की याचना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सहायक के अभाव में भी पराक्रम न डिगने का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch29-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch29-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">सुख के दिनों में कवि ईश्वर के प्रति क्या भाव रखना चाहता है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि कहता है—<em>\"नतशिर होकर सुख के दिन में, तब मुख पहचानूँ छिन-छिन में।\"</em></p>\n          <p>सुख के दिनों में अक्सर मनुष्य ईश्वर को भूल जाता है और घमंड में चूर हो जाता है। किंतु कवि चाहता है कि वह सुख और समृद्धि के समय भी विनम्र भाव से सिर झुकाकर हर पल ईश्वर के रूप को पहचाने और उनके प्रति कृतज्ञ रहे, ताकि सुख में भी उसका अहंकार न बढ़े।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नतशिर (विनम्र) होकर प्रतिपल प्रभु को याद रखने का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सुख में अहंकार से मुक्ति व कृतज्ञता का निरूपण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch29-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch29-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">'तव मुख अनाम'—कवि किन परिस्थितियों में ईश्वर पर संशय न करने की प्रार्थना करता है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि कहता है—<em>\"दुख-निशा में जो करे वंचना भुवन, उस दिन भी करूँ न संशय तुम पर।\"</em></p>\n          <p>जब घोर दुख और विपत्ति की अंधेरी रात छाई हो और पूरा संसार उसके साथ विश्वासघात (धोखा) करे, उस भीषण निराशा और अकेलेपन के क्षणों में भी कवि के मन में ईश्वर के न्याय, दया और सत्ता पर रत्ती भर भी संदेह (संशय) उत्पन्न न हो। उसका प्रभु पर विश्वास अडिग रहे।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">घोर विपत्ति व संसार के विश्वासघात की परिस्थिति</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">ईश्वर के प्रति अटूट आस्था व संशय-मुक्ति का संकल्प</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch29-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch29-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">भाव स्पष्ट कीजिए: 'मेरा भार अगर लघु करके न दो सांत्वना नहीं सही। केवल इतना रखना अनुनय—वहन कर सकूँ इसको निर्भय।'</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>भावार्थ:</strong> कवि ईश्वर से अपने दुखों के बोझ (भार) को कम करने या झूठी सांत्वना देने का आग्रह नहीं करता।</p>\n          <p>वह परमात्मा से केवल इतनी-सी विनम्र प्रार्थना करता है कि प्रभु उसे आंतरिक शक्ति, साहस और निर्भयता प्रदान करें ताकि वह अपने जीवन के हर संघर्ष और उत्तरदायित्व के भारी बोझ को बिना झुके और बिना घबराए अपनी शक्ति से स्वयं उठा सके। यह आत्म-निर्भरता की सर्वोच्च अभिव्यक्ति है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दुख का भार कम न करने व सांत्वना न माँगने का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">निर्भय होकर स्वयं भार वहन करने की आत्मिक शक्ति का प्रतिपादन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Competency-Based Questions (CBQs) -->\n  <div class=\"cbq-card\">\n    <div class=\"cbq-badge\">CBSE Board Competency-Based Question (योग्यता आधारित प्रश्न)</div>\n    <div class=\"q-text\"><strong>आत्म-निर्भरता एवं मनोवैज्ञानिक सशक्तिकरण (Self-Reliance & Psychological Resilience):</strong> 'आत्मत्राण' कविता पलायनवाद और परावलंबन के स्थान पर 'रेजिलिएंस' (आंतरिक संघर्ष-क्षमता) का संदेश देती है। विद्यार्थियों के जीवन में असफलता और मानसिक दबाव के समय यह दृष्टिकोण किस प्रकार संजीवनी का कार्य कर सकता है?</div>\n    <div class=\"answer-box\" style=\"margin-top: 15px;\">\n      <div class=\"answer-label\">विशेषज्ञ उत्तर व विश्लेषणात्मक दृष्टिकोण</div>\n      <div class=\"answer-text\">\n        <p><strong>विश्लेषण:</strong> परीक्षा या जीवन की असफलताओं में विद्यार्थी अक्सर तनावग्रस्त होकर भाग्य या परिस्थितियों को दोष देने लगते हैं या पलायन का रास्ता चुनते हैं।</p>\n        <p><strong>मानसिक सशक्तिकरण:</strong> रवींद्रनाथ ठाकुर की यह कविता सिखाती है कि बाधाओं से डरना नहीं, बल्कि अपनी आंतरिक क्षमता और आत्म-विश्वास पर भरोसा रखकर उनका सामना करना चाहिए। जब कोई विद्यार्थी संकटों को कम कराने के बजाय उनसे लड़ने की मानसिक शक्ति विकसित करता है, तो वह हर विफलता को अपनी सफलता की सीढ़ी बना लेता है।</p>\n      </div>\n    </div>\n  </div>\n</section>","30":"<section class=\"chapter-section\" id=\"ch30\" data-book=\"sanchayan\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">30</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">संचयन भाग-2 — पाठ 1</div>\n      <h2>हरिहर काका</h2>\n      <p>मिथिलेश्वर | मर्मस्पर्शी यथार्थवादी कहानी — पारिवारिक स्वार्थ, धर्म के ठेकेदारों का पाखंड, बुजुर्गों की उपेक्षा और संपत्ति का लोभ | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch30-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch30-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">अनपढ़ होते हुए भी हरिहर काका दुनिया की बेहतर समझ कैसे रखते हैं? कहानी के आधार पर स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>हरिहर काका भले ही औपचारिक रूप से पढ़े-लिखे नहीं थे, किंतु जीवन के कड़वे अनुभवों ने उन्हें दुनियादारी और इंसानी फितरत की गहरी समझ दी थी:</p>\n          <ul>\n            <li>वे भली-भाँति जानते थे कि उनके सगे भाई और ठाकुरबारी के महंत उनके प्रति जो थोड़ा-बहुत आदर या सेवा दिखा रहे हैं, वह उनके प्रति प्रेम के कारण नहीं, बल्कि उनकी 15 बीघे उपजाऊ जमीन के कारण है।</li>\n            <li>उन्होंने अपने गाँव में ऐसे कई बुजुर्गों को देखा था जिन्होंने जीते जी अपनी संपत्ति अपने परिजनों के नाम लिख दी थी और बाद में उन्हें कुत्ते की मौत मरना पड़ा था, कोई एक रोटी देने वाला भी नहीं बचा था।</li>\n            <li>इसलिए उन्होंने दृढ़ निश्चय किया कि जीते जी वे अपनी जमीन किसी के नाम नहीं लिखेंगे, चाहे भाई मार डालें या महंत जान से खत्म कर दें।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">15 बीघे जमीन के लोभ को पहचानने की क्षमता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गाँव के उपेक्षित वृद्धों के दृष्टांत से सीख व दृढ़ निर्णय</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch30-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch30-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">हरिहर काका को महंत और अपने भाई एक ही श्रेणी के क्यों लगने लगे?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>शुरू में हरिहर काका को लगता था कि भाई तो स्वार्थी हैं किंतु महंत जी भगवान के सच्चे सेवक हैं। किंतु बाद की घटनाओं ने सिद्ध कर दिया कि दोनों पक्षों में लेशमात्र भी अंतर नहीं था:</p>\n          <ul>\n            <li><strong>महंत का घिनौना रूप:</strong> महंत ने धर्म की आड़ में काका का अपहरण करवाया, उनके मुँह में कपड़ा ठूँसा, हाथ-पैर बाँधे और बंदूक की नोक पर जबरन सादे कागजों पर अँगूठे के निशान लगवाए।</li>\n            <li><strong>भाइयों की क्रूरता:</strong> भाइयों ने भी जब देखा कि काका जमीन नहीं लिख रहे, तो उन्होंने भी घर में काका को मारा-पीटा, जान से मारने की धमकी दी और जबरन अँगूठे लगवाए।</li>\n          </ul>\n          <p>दोनों का एकमात्र लक्ष्य काका की संपत्ति हड़पना था। रिश्ते और धर्म दोनों ही काका के लिए केवल स्वार्थ की चादर साबित हुए, इसलिए वे दोनों को एक ही थैली के चट्टे-बट्टे और हिंसक भेड़िया मानते हैं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">महंत द्वारा अपहरण व अँगूठा लगवाने की हिंसा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाइयों द्वारा मारपीट व जमीन हड़पने की स्वार्थपरता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch30-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch30-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">ठाकुरबारी के प्रति गाँव वालों के मन में अगाध श्रद्धा के क्या कारण थे?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>गाँव वालों का यह दृढ़ और अंधा विश्वास था कि उनके जीवन की हर सफलता और खुशी ठाकुर जी (ठाकुरबारी) की ही कृपा से मिलती है:</p>\n          <ul>\n            <li>खेतों में अच्छी फसल होना, मुकदमे में जीत, पुत्र का जन्म या बेटी का अच्छा विवाह होना—गाँव वाले इसका श्रेय ठाकुर जी की मन्नत को ही देते थे।</li>\n            <li>कृतज्ञता स्वरूप लोग अपनी पहली फसल का हिस्सा, घी, अनाज और जमीन का एक टुकड़ा ठाकुरबारी के नाम दान कर देते थे। इसी अंधविश्वास के कारण ठाकुरबारी एक संपन्न और शक्तिशाली मठ बन गई थी।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मन्नत पूरी होने व सफलता का श्रेय ठाकुर जी को देने का विश्वास</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अनाज, घी व जमीन दान देकर ठाकुरबारी को शक्तिशाली बनाने का संदर्भ</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch30-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch30-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">गाँव में हरिहर काका के मामले को लेकर कौन-से दो वर्ग बन गए थे और उनके क्या-क्या विचार थे?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>हरिहर काका की 15 बीघे जमीन को लेकर गाँव स्पष्ट रूप से दो विरोधी गुटों में बँट गया था:</p>\n          <ul>\n            <li><strong>पहला वर्ग (धार्मिक व मठाधीश समर्थक):</strong> इस वर्ग में ठाकुरबारी के महंत के समर्थक, बुजुर्ग और धार्मिक अंधविश्वास में डूबे लोग थे। उनका तर्क था कि हरिहर काका को अपनी सारी जमीन ठाकुरबारी के नाम लिख देनी चाहिए। इससे काका को परलोक में मोक्ष मिलेगा और गाँव का नाम रोशन होगा।</li>\n            <li><strong>दूसरा वर्ग (पारिवारिक व प्रगतिशील समर्थक):</strong> इस वर्ग में आधुनिक सोच वाले लोग, किसान और काका के भाइयों के समर्थक थे। उनका मानना था कि जमीन परिवार और भाइयों की पैतृक संपत्ति है। खून का रिश्ता सबसे बड़ा होता है, अतः जमीन परिवार से बाहर ठाकुरबारी के साधुओं को नहीं जानी चाहिए।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">ठाकुरबारी समर्थक वर्ग (मोक्ष, धर्म, दान) का तर्क</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पारिवारिक समर्थक वर्ग (खून का रिश्ता, पैतृक अधिकार) का तर्क</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch30-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch30-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">भाइयों द्वारा हरिहर काका के साथ किए गए अमानवीय व्यवहार का वर्णन कीजिए।</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>भाइयों ने हरिहर काका के साथ रिश्ते की सारी मर्यादाओं को तार-तार कर दिया:</p>\n          <ul>\n            <li>प्रारंभ में भाइयों की पत्नियों ने काका को बचा-खुचा रूखा-सूखा भोजन दिया और बीमार होने पर पानी पूछने वाला भी कोई नहीं था।</li>\n            <li>जब काका ने जमीन लिखने से मना कर दिया, तो भाइयों ने घर के दरवाजे बंद कर उन्हें हथियारों के बल पर घेर लिया।</li>\n            <li>उन्होंने काका को बेरहमी से पीटा, उनके मुँह में कपड़ा ठूँसा और जान से मारकर खेत में गाड़ देने की धमकी देकर जबरन सादे कागजों पर अँगूठे के निशान लिए। काका ने किसी तरह मुँह से कपड़ा निकालकर चीख लगाई जिससे पुलिस और ग्रामीण पहुँचे।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रारंभिक उपेक्षा व रूखा-सूखा भोजन देने का विवरण</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हथियारों के बल पर मारपीट, मुँह में कपड़ा ठूँसना व जबरन अँगूठे लगवाना</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch30-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch30-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">महंत जी ने हरिहर काका को अपने जाल में फँसाने के लिए क्या-क्या प्रलोभन और आध्यात्मिक चालें चलीं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>महंत ने हरिहर काका की कमजोर भावनात्मक स्थिति का लाभ उठाते हुए निम्नलिखित चालें चलीं:</p>\n          <ul>\n            <li>काका को आदर-सम्मान सहित ठाकुरबारी ले जाकर बढ़िया मालपुआ, खीर और स्वादिष्ट पकवान खिलाए।</li>\n            <li>काका को यह समझाया कि संसार नश्वर है और रिश्ते-नाते सब स्वार्थ के हैं। यदि वे अपनी जमीन ठाकुरबारी को दान कर देंगे, तो उन्हें स्वर्ग और मोक्ष मिलेगा तथा साधु-संत उनकी चरण-सेवा करेंगे।</li>\n            <li>जब काका इन मीठी बातों में नहीं आए, तो महंत ने अपने गुंडों द्वारा उनका अपहरण करवाकर हिंसा का सहारा लिया।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्वादिष्ट भोजन, आदर व स्वर्ग-मोक्ष के प्रलोभन का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">संसार की नश्वरता के आध्यात्मिक पाखंड व बाद में हिंसा का पर्दाफाश</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch30-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch30-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">'यदि समाज में न्याय और सुरक्षा की व्यवस्था न हो, तो असहाय वृद्धों का जीवन नर्क बन जाता है।' पाठ के आधार पर इस कथन की पुष्टि कीजिए।</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>पुष्टि:</strong> यह कथन 'हरिहर काका' कहानी के यथार्थ पर पूरी तरह खरा उतरता है:</p>\n          <ul>\n            <li>हरिहर काका के पास संपत्ति होने के बावजूद वे अपने ही घर में बंधक और प्रताड़ित हो गए। जिन सगे भाइयों और धार्मिक गुरु पर उन्हें विश्वास होना चाहिए था, वे ही उनके जान के प्यासे बन गए।</li>\n            <li>गाँव का समाज और पुलिस तंत्र भी केवल मूकदर्शक बना रहा या रिश्वतखोरी में लिप्त रहा। पुलिस के सिपाही काका की सुरक्षा के नाम पर उनकी ही कमाई पर मौज उड़ाते रहे।</li>\n            <li>समाज में वृद्धों की सुरक्षा के लिए कोई सुदृढ़ नैतिक या विधिक संरक्षण न होने के कारण काका जीवित रहते हुए भी एक जीते-जागते मुर्दे जैसी स्थिति में पहुँच गए।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पारिवारिक व सामाजिक सुरक्षा तंत्र की विफलता का विश्लेषण</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पुलिस-प्रशासन की शिथिलता व काका के नर्कतुल्य जीवन का विवेचन</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch30-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch30-q8')\">\n      <div class=\"q-num\">प्रश्न 8</div>\n      <div class=\"q-text\">कहानी के अंत में हरिहर काका की मानसिक व शारीरिक स्थिति का चित्रण कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कहानी के अंत में हरिहर काका पूरी तरह मौन और निस्तब्ध हो चुके हैं:</p>\n          <p>वे अपने परिवार से अलग एक दालान में रहते हैं। उनकी सुरक्षा के लिए चार पुलिस के सिपाही तैनात हैं जो काका के पैसों पर खूब दावतें उड़ाते हैं। काका ने एक नौकर रख लिया है जो उनके लिए खाना बना देता है। काका दिनभर खामोश बैठकर आकाश की ओर शून्य दृष्टि से ताकते रहते हैं। अपनों के क्रूर विश्वासघात और छल ने उनकी वाणी और जीने की इच्छा को पूरी तरह छीन लिया है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शून्य में ताकना व मौन रहने की मानसिक स्थिति</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पुलिस सुरक्षा, नौकर द्वारा भोजन व अलगाव का चित्रण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Competency-Based Questions (CBQs) -->\n  <div class=\"cbq-card\">\n    <div class=\"cbq-badge\">CBSE Board Competency-Based Question (योग्यता आधारित प्रश्न)</div>\n    <div class=\"q-text\"><strong>वृद्धजन अधिकार एवं सामाजिक सुरक्षा (Elderly Rights & Social Justice):</strong> वर्तमान भारतीय समाज में माता-पिता और वरिष्ठ नागरिकों के भरण-पोषण तथा कल्याण अधिनियम (Maintenance and Welfare of Parents and Senior Citizens Act) के आलोक में हरिहर काका की स्थिति की समीक्षा कीजिए। वृद्धों के अधिकारों की रक्षा हेतु समाज और कानून क्या कदम उठा सकते हैं?</div>\n    <div class=\"answer-box\" style=\"margin-top: 15px;\">\n      <div class=\"answer-label\">विशेषज्ञ उत्तर व विश्लेषणात्मक दृष्टिकोण</div>\n      <div class=\"answer-text\">\n        <p><strong>समीक्षा:</strong> 'हरिहर काका' की कथा वरिष्ठ नागरिकों की सुरक्षा के अभाव की चरम त्रासदी है। आज भारतीय कानून के तहत यदि कोई संतान या रिश्तेदार संपत्ति लेने के बाद बुजुर्गों की उपेक्षा या प्रताड़ना करता है, तो संपत्ति का हस्तांतरण निरस्त किया जा सकता है और कानूनी दंड का प्रावधान है।</p>\n        <p><strong>आवश्यक कदम:</strong> वृद्धों के लिए स्थानीय स्तर पर वरिष्ठ नागरिक हेल्पलाइन, अनिवार्य सामाजिक सुरक्षा ऑडिट और विधिक सहायता केंद्र होने चाहिए ताकि किसी भी हरिहर काका को जीते-जी अपनी ही संपत्ति के कारण बंधक और प्रताड़ित न होना पड़े।</p>\n      </div>\n    </div>\n  </div>\n</section>","31":"<section class=\"chapter-section\" id=\"ch31\" data-book=\"sanchayan\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">31</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">संचयन भाग-2 — पाठ 2</div>\n      <h2>सपनों के-से दिन</h2>\n      <p>गुरदयाल सिंह | आत्मकथात्मक संस्मरण — बचपन की खेलकूद, स्कूल का खौफ, पीटी मास्टर प्रीतम चंद, हेडमास्टर शर्मा जी और बाल-सुलभ स्मृतियाँ | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch31-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch31-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">कोई भी भाषा आपसी व्यवहार में बाधा नहीं बनती—पाठ के किस अंश से यह सिद्ध होता है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखक के बचपन के खेल-साथी विभिन्न पृष्ठभूमि के थे। उनमें से कई बच्चे राजस्थान या हरियाणा से व्यापार के सिलसिले में आए परिवारों के थे, जो अपनी मारवाड़ी या हरियाणवी बोली बोलते थे।</p>\n          <p>यद्यपि बच्चे एक-दूसरे की पूरी बोली या शब्दावली नहीं समझ पाते थे, फिर भी खेलते समय उनका व्यवहार, हँसना-कूदना, लड़ना और एक-दूसरे के आँसू पोंछना सब एक समान था। खेल के मैदान की स्वाभाविक संवेदना और बाल-मनोविज्ञान ने भाषा की किसी भी दीवार को बाधा नहीं बनने दिया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">विभिन्न राज्यों (राजस्थान/हरियाणा) के बच्चों का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">खेल की सर्वव्यापी भाषा व बाल-सुलभ आत्मीयता का निरूपण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch31-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch31-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">पीटी मास्टर प्रीतम चंद की छवि कैसी थी और हेडमास्टर मदन मोहन शर्मा जी उनके विपरीत कैसे थे?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>दोनों शिक्षकों के व्यक्तित्व में गहरा विरोधाभास था:</p>\n          <ul>\n            <li><strong>पीटी मास्टर प्रीतम चंद:</strong> दुबले-पतले, ठिगने कद और चेचक के दागों वाले चेहरे के थे। वे अत्यंत क्रूर, कठोर और अनुशासनप्रिय थे। वे बच्चों को बिना कारण बुरी तरह पीटते थे, उनकी खाल खींच लेते थे और जरा-सी गलती पर मुर्गा बना देते थे। बच्चे उनसे थर-थर काँपते थे।</li>\n            <li><strong>हेडमास्टर मदन मोहन शर्मा जी:</strong> इसके सर्वथा विपरीत शर्मा जी अत्यंत शांत, सौम्य और दयालु स्वभाव के थे। उन्होंने कभी किसी बच्चे को थप्पड़ तक नहीं मारा था। यदि कोई बच्चा गलती करता, तो वे बड़े प्यार से समझाते थे। सभी बच्चे उनका गहरा सम्मान करते थे।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पीटी मास्टर की क्रूरता, कठोर दंड व भयभीत छवि का चित्रण</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हेडमास्टर शर्मा जी की सौम्यता, दयालुता व आदर का उल्लेख</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch31-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch31-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">पीटी साहब को निलंबित (सस्पेंड) क्यों कर दिया गया था?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>एक दिन चौथी कक्षा में फारसी पढ़ाते समय जब बच्चे शब्द-रूप (याद किया हुआ पाठ) ठीक से नहीं सुना सके, तो प्रीतम चंद ने पूरी कक्षा को घुटने मोड़कर, पीठ झुकाकर और कानों को हाथों से पकड़वाकर 'मुर्गा' बना दिया।</p>\n          <p>बच्चे दर्द से काँप रहे थे। उसी समय हेडमास्टर शर्मा जी वहाँ से गुज़रे। बच्चों की ऐसी अमानवीय और बर्बर प्रताड़ना देखकर शर्मा जी अत्यंत क्रोधित हो गए। उन्होंने तुरंत \"व्हाट आर यू डूइंग? इट इज़ नॉट अलाउड!\" कहकर बच्चों को खड़ा किया और रियासत के शिक्षा विभाग को रिपोर्ट भेजकर प्रीतम चंद को तत्काल निलंबित (सस्पेंड) करवा दिया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">फारसी न सुनाने पर बच्चों को 'मुर्गा' बनाने की क्रूरता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हेडमास्टर शर्मा जी का रोष व निलंबन का आदेश</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch31-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch31-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">निलंबन के दौरान प्रीतम चंद को तोतों को बादाम खिलाते देखकर बच्चों को क्या ताज्जुब हुआ?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>निलंबन के बाद प्रीतम चंद अपने कमरे में मजे से रहते थे और उन्होंने पिंजरे में दो तोते पाल रखे थे। जब बच्चे हेडमास्टर साहब की चिट्ठी लेकर उनके घर गए, तो उन्होंने देखा कि प्रीतम चंद बड़े प्यार से तोतों से मीठी बातें कर रहे हैं और उन्हें अपने हाथों से छिले हुए बादाम खिला रहे हैं।</p>\n          <p>यह देखकर बच्चों को भारी आश्चर्य (ताज्जुब) हुआ कि जो व्यक्ति स्कूल में इंसान के बच्चों को बेदर्दी से पीटता था और जिसकी चमड़ी पत्थर जैसी कठोर लगती थी, वह पक्षियों के प्रति इतना कोमल और स्नेही कैसे हो सकता है!</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तोतों से मीठी बातें करने व बादाम खिलाने का प्रसंग</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">क्रूर शिक्षक के कोमल रूप पर बाल-सुलभ विस्मय का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch31-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch31-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">लेखक के बचपन में स्कूल जाने की क्या परिस्थितियाँ थीं और बच्चे स्कूल से क्यों डरते थे?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखक के बचपन में अधिकांश माता-पिता अनपढ़ थे और वे बच्चों की पढ़ाई को कोई खास महत्व नहीं देते थे। उनका मानना था कि दुकानदारी या खेती के लिए केवल थोड़ा-बहुत मुनीमी हिसाब आना ही काफी है।</p>\n          <p>बच्चे स्कूल जाने से इसलिए डरते थे क्योंकि उस समय स्कूलों में शिक्षकों द्वारा छात्रों को बेंत, थप्पड़ों और मुर्गा बनाने जैसी भयानक शारीरिक यातनाएँ दी जाती थीं। स्कूल जाना बच्चों के लिए किसी कारागार या प्रताड़ना केंद्र जैसा भयानक अनुभव होता था।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">माता-पिता की अनपढ़ता व शिक्षा के प्रति उदासीनता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शिक्षकों के कठोर शारीरिक दंड व स्कूल के खौफ का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch31-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch31-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">नई श्रेणी (कक्षा) में जाने पर लेखक को पुरानी किताबों से क्यों पढ़ना पड़ता था और उसके मन में क्या भावनाएँ आती थीं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखक का परिवार अत्यंत निर्धन था। उनके परिवार के पास नई किताबें खरीदने के पैसे नहीं होते थे। हेडमास्टर मदन मोहन शर्मा जी किसी अमीर परिवार के लड़के की पिछली कक्षा की पुरानी किताबें लेखक को दिलवा देते थे।</p>\n          <p>यद्यपि नई कक्षा में जाने की थोड़ी खुशी होती थी, किंतु पुरानी किताबों की बासी गंध और मुड़े हुए पन्ने देखकर लेखक का मन उदास हो जाता था। उसे लगता था कि अगली कक्षा में पढ़ाई और कठिन हो जाएगी और मास्टरों की मार भी दोगुनी हो जाएगी, जिससे उसका उत्साह समाप्त हो जाता था।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पारिवारिक निर्धनता व हेडमास्टर द्वारा पुरानी पुस्तकें दिलाने का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पुरानी किताबों की गंध, उदासी व मार के भय की बाल-मनोवैज्ञानिक व्याख्या</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch31-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch31-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">द्वितीय विश्व युद्ध के समय फौज में भर्ती के लिए नौजवानों को कैसे आकर्षित किया जाता था?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>द्वितीय विश्व युद्ध के समय ब्रिटिश सेना के भर्ती अधिकारी (नायब) गाँवों में नौटंकी और बाजे-गाजे के साथ आते थे।</p>\n          <p>वे नौजवानों को सेना के सुख-सुविधाओं का प्रलोभन देने वाले गीत गाकर सुनाते थे, जैसे: <em>\"भर्ती हो जा रे नौजवान... इत्थे मिले फटे-पुराने, उत्थे मिले बूट-सूट!\"</em> वे बताते थे कि फौज में शानदार वर्दी, चमचमाते बूट और खूब अच्छा खाना मिलता है। इस आकर्षण में आकर कई ग्रामीण युवक फौज में भर्ती हो जाते थे।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बाजे-गाजे व नौटंकी दल द्वारा प्रचार का संदर्भ</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वर्दी, जूते व भोजन के प्रलोभन भरे गीतों का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Competency-Based Questions (CBQs) -->\n  <div class=\"cbq-card\">\n    <div class=\"cbq-badge\">CBSE Board Competency-Based Question (योग्यता आधारित प्रश्न)</div>\n    <div class=\"q-text\"><strong>शिक्षा मनोविज्ञान एवं बाल-अधिकार विश्लेषण (Child Rights & Pedagogy):</strong> 'सपनों के-से दिन' में पीटी मास्टर प्रीतम चंद की शारीरिक दंड प्रणाली और हेडमास्टर मदन मोहन शर्मा के संवेदनशील दृष्टिकोण की तुलना कीजिए। शिक्षा का अधिकार अधिनियम (RTE Act 2009) में शारीरिक दंड (Corporal Punishment) के पूर्ण प्रतिबंध की आवश्यकता पर प्रकाश डालिए।</div>\n    <div class=\"answer-box\" style=\"margin-top: 15px;\">\n      <div class=\"answer-label\">विशेषज्ञ उत्तर व विश्लेषणात्मक दृष्टिकोण</div>\n      <div class=\"answer-text\">\n        <p><strong>तुलनात्मक विश्लेषण:</strong> पीटी मास्टर की क्रूर दंड प्रणाली बच्चों में भय, हीनभावना और स्कूल से पलायन की प्रवृत्ति पैदा करती थी। इसके विपरीत हेडमास्टर शर्मा जी का स्नेहपूर्ण और उपचारात्मक व्यवहार बच्चों में आदर और सीखने की ललक जगाता था।</p>\n        <p><strong>RTE Act 2009 का औचित्य:</strong> आधुनिक बाल-मनोविज्ञान यह प्रमाणित करता है कि भय और हिंसा से अनुशासन नहीं, बल्कि मानसिक विकार और विद्रोह पैदा होता है। RTE अधिनियम के तहत शारीरिक व मानसिक दंड पर पूर्ण प्रतिबंध इसलिए अनिवार्य है ताकि विद्यालय भयमुक्त, समावेशी और आनंददायी अधिगम स्थल बन सकें।</p>\n      </div>\n    </div>\n  </div>\n</section>","32":"<section class=\"chapter-section\" id=\"ch32\" data-book=\"sanchayan\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">32</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">संचयन भाग-2 — पाठ 3</div>\n      <h2>टोपी शुक्ला</h2>\n      <p>राही मासूम रज़ा | संवेदनात्मक उपन्यास अंश — सांप्रदायिक सीमाओं से परे बाल-मित्रता, भावनात्मक अकेलापन, भाषा के संस्कार और दादी का वात्सल्य | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch32-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch32-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">इफ़्फ़न और टोपी शुक्ला की मित्रता किन बातों पर आधारित थी? दोनों के पारिवारिक परिवेश में क्या भिन्नता थी?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>मित्रता का आधार:</strong> इफ़्फ़न और टोपी शुक्ला की मित्रता धर्म, जाति या भाषा पर आधारित नहीं थी, बल्कि यह दो कोमल बाल-हृदयों के <strong>भावनात्मक अकेलेपन और सच्चे प्यार की भूख</strong> पर आधारित थी। दोनों के बीच एक अटूट संवेगात्मक रिश्ता था।</p>\n          <p><strong>पारिवारिक परिवेश में भिन्नता:</strong></p>\n          <ul>\n            <li><strong>टोपी का परिवार:</strong> एक कट्टर हिंदू ब्राह्मण परिवार था, जहाँ पूजा-पाठ, छूआछूत और कठोर अनुशासन का कड़ाई से पालन होता था। घर में टोपी की भावनाओं को समझने वाला कोई नहीं था।</li>\n            <li><strong>इफ़्फ़न का परिवार:</strong> एक मुस्लिम जमींदार परिवार था। इफ़्फ़न के पिता कलेक्टर थे। घर में उर्दू-फारसी का माहौल था। इफ़्फ़न की दादी पूरब (मौलवी परिवार) की थीं जो टोपी को सगी दादी से भी अधिक वात्सल्य देती थीं।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भावनात्मक अकेलेपन व प्रेम पर आधारित मित्रता का उल्लेख</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हिंदू ब्राह्मण व मुस्लिम कलेक्टर परिवार के परिवेश की तुलना</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch32-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch32-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">टोपी ने इफ़्फ़न की दादी के देहांत पर ऐसा क्यों कहा कि \"काश! तेरी दादी की जगह मेरी दादी मर गई होती\"?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>टोपी का यह कथन किसी दुर्भावना के कारण नहीं, बल्कि उसके अत्यधिक दुख और बाल-सुलभ भावुकता का परिणाम था:</p>\n          <ul>\n            <li>टोपी की अपनी सगी दादी अत्यंत कठोर, कर्कश और बात-बात पर डाँटने वाली थीं। वे टोपी को कभी प्यार से पास नहीं बिठाती थीं।</li>\n            <li>इसके विपरीत इफ़्फ़न की दादी टोपी को अपनी संतानों की तरह प्यार करती थीं, उसे मीठी पूरबी बोली में कहानियाँ सुनाती थीं और उसके मन की बात समझती थीं।</li>\n            <li>इफ़्फ़न की दादी के जाने से टोपी का संसार सूना हो गया था। इसलिए उसने रोते हुए कहा कि काश उसकी अपनी कठोर दादी चली गई होती और प्यार देने वाली इफ़्फ़न की दादी जीवित रहती।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अपनी सगी दादी की कर्कशता व उपेक्षा का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">इफ़्फ़न की दादी के वात्सल्य, कहानियों व गहरे प्रेम का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch32-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch32-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">इफ़्फ़न की दादी अपने पीहर (मायके) को क्यों याद करती थीं और वे हवेली में खुश क्यों नहीं थीं?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>इफ़्फ़न की दादी पूरब के एक सामान्य जमींदार परिवार की बेटी थीं, जहाँ खूब खुलापन, देशी खाना (दही-भात, आम) और पूरबी बोली की मिठास थी।</p>\n          <p>उनका विवाह लखनऊ के एक मौलवी खानदान में हुआ जहाँ कठोर पर्दा-प्रथा और औपचारिकता का बोलबाला था। वहाँ पूरबी बोली बोलने और मनपसंद खाने पर पाबंदी थी। उस बड़ी हवेली में उनका दम घुटता था, इसलिए वे जीवनभर अपने मायके की उन्मुक्तता और सहज संस्कृति को याद कर तड़पती रहीं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मायके के खुलेपन व पूरबी बोली-संस्कृति का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">ससुराल की कठोर औपचारिकता व दमघोंटू माहौल का कारण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch32-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch32-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">टोपी के घर में 'अम्मी' और 'बावर्चीखाना' शब्द बोलने पर क्या बखेड़ा खड़ा हुआ?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>एक दिन भोजन करते समय टोपी ने अपनी माँ से सहज ही कह दिया—\"अम्मी, ज़रा बैंगन का भर्ता देना।\"</p>\n          <p>कट्टर ब्राह्मण परिवार में 'अम्मी' और 'बावर्चीखाना' जैसे उर्दू शब्दों को सुनते ही मानो प्रलय आ गई। उसकी दादी सुभद्रा देवी ने थाली फेंक दी और घर अपवित्र होने का शोर मचा दिया। उसकी माँ को डाँटा गया और टोपी की जमकर पिटाई की गई। उससे पूछा गया कि उसने यह 'मुसलमानों की भाषा' कहाँ से सीखी। इस घटना से घर में भीषण विवाद खड़ा हो गया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">'अम्मी' शब्द बोलते ही थाली फेंकने व धर्म भ्रष्ट होने का प्रसंग</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">टोपी की पिटाई व भाषा के प्रति सांप्रदायिक संकीर्णता का प्रकटीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch32-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch32-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">नौवीं कक्षा में दो बार फेल होने पर टोपी को किन-किन मानसिक यातनाओं और उपहास का सामना करना पड़ा?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>नौवीं कक्षा में दो बार फेल होने पर टोपी को घर और स्कूल दोनों जगह भीषण मानसिक प्रताड़ना झेलनी पड़ी:</p>\n          <ul>\n            <li><strong>घर में उपहास:</strong> घर में भाई और माता-पिता उसे ताने मारते थे। जब भी वह पढ़ने बैठता, घर के सदस्य उसे नौकरों की तरह बाज़ार से सौदा लाने भेज देते और कहते—\"तू कौन-सा लाट साहब बनने जा रहा है, फेल तो होना ही है।\"</li>\n            <li><strong>स्कूल में अकेलापन:</strong> उसके पुराने सहपाठी दसवीं कक्षा में चले गए थे और नए जूनियर लड़के उसका मज़ाक उड़ाते थे।</li>\n            <li><strong>अध्यापकों का व्यंग्य:</strong> अध्यापक कक्षा में नए लड़कों से कहते—\"देखो, बलभद्र (टोपी) भाई से पूछ लो, ये तो दो साल से इसी दर्जे में रिसर्च कर रहे हैं।\" इस तीखे उपहास ने टोपी के आत्मसम्मान को छलनी कर दिया था।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">घर में घरेलू नौकर जैसा बर्ताव व तानों का उल्लेख</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्कूल में अध्यापकों के व्यंग्य व सहपाठियों द्वारा उपहास की मानसिक पीड़ा</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch32-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch32-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">तीसरे वर्ष जब टोपी परीक्षा दे रहा था, तो उसने किस दृढ़ संकल्प से पढ़ाई की और उसे किन घरेलू कठिनाइयों का सामना करना पड़ा?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>तीसरे वर्ष टोपी ने अपना आत्मसम्मान बचाने के लिए किसी भी कीमत पर पास होने का दृढ़ संकल्प किया। किंतु परिवार ने उसे पढ़ने का अवसर नहीं दिया:</p>\n          <p>उसकी दादी, माँ और भाई लगातार उसे बाज़ार के छोटे-मोटे कामों में उलझाए रखते थे। परीक्षा के दिनों में भी उसे दुकानदारी और सौदा लाने भेजा जाता था। फिर भी टोपी ने रात-रात जागकर कठोर परिश्रम किया और तमाम बाधाओं के बावजूद तृतीय श्रेणी (थर्ड डिवीजन) में पास होकर सबको स्तब्ध कर दिया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दृढ़ संकल्प व आत्मसम्मान की रक्षा की भावना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">परिवार द्वारा काम में उलझाना व तृतीय श्रेणी में उत्तीर्ण होने का संघर्ष</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch32-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch32-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">इफ़्फ़न के पिता के तबादले के बाद नए कलेक्टर के बच्चों के साथ टोपी का क्या अनुभव रहा?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>इफ़्फ़न के तबादले के बाद उस सरकारी बंगले में एक नए कलेक्टर साहब आए। टोपी पुरानी यादों के वशीभूत होकर उस कोठी में गया ताकि नए कलेक्टर के बच्चों से मित्रता कर सके।</p>\n          <p>किंतु नए कलेक्टर के बच्चे अत्यंत घमंडी और अँग्रेजीदां थे। उन्होंने टोपी को 'देहाती और गंदा लड़का' समझकर दुत्कारा और अपने पालतू शिकारी कुत्ते को उसके पीछे छोड़ दिया। कुत्ते ने टोपी के पेट में काट लिया। इस अपमान और चोट के बाद टोपी ने प्रण किया कि वह कभी किसी ऐसे लड़के से दोस्ती नहीं करेगा जिसके पिता का तबादला होता हो।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नए बच्चों का घमंड व कुत्ता पीछे छोड़ने की घटना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">टोपी का अपमान व तबादले वाले लड़कों से दोस्ती न करने का प्रण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch32-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch32-q8')\">\n      <div class=\"q-num\">प्रश्न 8</div>\n      <div class=\"q-text\">'टोपी शुक्ला' कहानी सांप्रदायिक सौहार्द और बाल-मनोविज्ञान का अद्वितीय आख्यान है—इस कथन की समीक्षा कीजिए।</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>समीक्षा:</strong> यह कथन राही मासूम रज़ा की इस कालजयी कृति का सर्वोत्तम मूल्यांकन है:</p>\n          <ul>\n            <li><strong>सांप्रदायिक सौहार्द:</strong> टोपी (हिंदू ब्राह्मण) और इफ़्फ़न (मुस्लिम) की मित्रता यह सिद्ध करती है कि धर्म और भाषा इंसानों को बाँटने की कृत्रिम दीवारें हैं। टोपी को अपनी सगी दादी से अधिक प्रेम इफ़्फ़न की मुस्लिम दादी से मिलता है, जो मानवीय संवेदनाओं की सांप्रदायिकता पर सबसे बड़ी विजय है।</li>\n            <li><strong>बाल-मनोविज्ञान:</strong> कहानी बच्चों के संवेगात्मक अकेलेपन, प्यार की भूख, बड़ों के अहंकार द्वारा बच्चों के कोमल मन पर लगने वाले आघातों और शिक्षा प्रणाली में फेल होने पर मिलने वाली प्रताड़ना का अत्यंत प्रामाणिक और मर्मस्पर्शी चित्रण करती है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हिंदू-मुस्लिम सीमाओं से परे मानवीय प्रेम व सौहार्द का निरूपण</span><span class=\"marking-marks\">2 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बाल-मनोविज्ञान (अकेलापन, प्यार की चाह, परीक्षा का दबाव) का विश्लेषण</span><span class=\"marking-marks\">2 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Competency-Based Questions (CBQs) -->\n  <div class=\"cbq-card\">\n    <div class=\"cbq-badge\">CBSE Board Competency-Based Question (योग्यता आधारित प्रश्न)</div>\n    <div class=\"q-text\"><strong>भाषा, संस्कृति एवं सामाजिक समावेशिता (Linguistic Pluralism & Inclusivity):</strong> 'टोपी शुक्ला' में भाषा को धर्म से जोड़कर देखने की संकीर्ण मानसिकता पर चोट की गई है। क्या भाषा का कोई धर्म होता है? गंगा-जमुनी तहज़ीब और भारतीय भाषाई बहुलता के संदर्भ में इस पर अपने विचार लिखिए।</div>\n    <div class=\"answer-box\" style=\"margin-top: 15px;\">\n      <div class=\"answer-label\">विशेषज्ञ उत्तर व विश्लेषणात्मक दृष्टिकोण</div>\n      <div class=\"answer-text\">\n        <p><strong>विचार:</strong> भाषा का कोई धर्म नहीं होता, भाषा केवल अभिव्यक्ति और मानवीय संवेदनाओं का माध्यम होती है:</p>\n        <ul>\n          <li>हिंदी और उर्दू भारत की साझी गंगा-जमुनी संस्कृति की दो धाराएँ हैं। जब टोपी 'अम्मी' बोलता है, तो उसमें मातृ-प्रेम की अभिव्यक्ति होती है, कोई सांप्रदायिक षड्यंत्र नहीं।</li>\n          <li>भाषा को धार्मिक चश्मे से देखना अज्ञानता और संकीर्णता है। भारत की भाषाई विविधता और परस्पर शब्दों का आदान-प्रदान ही हमारी राष्ट्रीय शक्ति और सांस्कृतिक सौहार्द की पहचान है।</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n</section>"};
